window.UNIFIED_DATA = {"344":{"terms":[{"id":"344-t-1","term":"借景","answer":"将特定园林空间以外视线可及的景物有意识地组织起来欣赏，使其成为园内景物一部分的造景手段。实质是园内外及各空间景观的相互渗透、互为对景和相互烘托。手法有远借、邻借、仰借、俯借、借时、借天、借声、借香等。","category":"重点","chapter":"一、造景手法与视觉组织"},{"id":"344-t-2","term":"夹景","answer":"利用树丛、建筑、山石等将远景两侧屏障起来，形成狭长视景通道以突出端景的造景手法，可收束视线、加强景深。","category":"重点","chapter":"一、造景手法与视觉组织"},{"id":"344-t-3","term":"框景","answer":"利用门框、窗框、树丛、山石洞穴等有意识地框取景物，使景物如画幅般呈现的造景手法，起收束视线、美化构图的作用。","category":"重点","chapter":"一、造景手法与视觉组织"},{"id":"344-t-4","term":"主景","answer":"园林中处于主导地位、集中体现园林主题与特色的主要景观，是空间构图的重心，其余景物围绕其配置以突出之。","category":"重点","chapter":"一、造景手法与视觉组织"},{"id":"344-t-5","term":"景与景点","answer":"景：具有审美特征的客观景物与环境。景点：由若干相互关联的景物构成、具相对独立性与完整性并具审美特征的基本境域单位，常具一定主题内容或风景特色。","category":"重点","chapter":"一、造景手法与视觉组织"},{"id":"344-t-6","term":"对景","answer":"多用于园林局部空间焦点部位、两处景物相对成景相互观赏的造景手法，作用一是丰富空间景观，二是引人入胜。","category":"重点","chapter":"一、造景手法与视觉组织"},{"id":"344-t-7","term":"障景","answer":"利用遮挡的方法将景物屏障起来、避免一览无余的造景手法，形成\"一步一景、移步换景\"的含蓄效果，是古典园林艺术的重要规律。","category":"重点","chapter":"一、造景手法与视觉组织"},{"id":"344-t-8","term":"园林艺术的透视线","answer":"园林中远方可透视的空间，即视线所及的透视空间范围。","category":"重点","chapter":"一、造景手法与视觉组织"},{"id":"344-t-9","term":"透景线","answer":"在树木或其他物体中间保留的可透视远方景物的空间，其远方空间终点是可被观赏的具体景物（区别于仅为可透视空间的透视线）。","category":"重点","chapter":"一、造景手法与视觉组织"},{"id":"344-t-10","term":"写意山水园","answer":"以自然山水为蓝本，经艺术概括提炼、以少胜多、以形写神，追求\"虽由人作、宛自天开\"意境的中国古典园林形式。","category":"重点","chapter":"二、园林类型与形式／风格"},{"id":"344-t-11","term":"自然式园林","answer":"效法自然、服从自然、高于自然，采用自然山水形态与自由曲线布局、不对称构图的园林形式。","category":"重点","chapter":"二、园林类型与形式／风格"},{"id":"344-t-12","term":"规则式园林","answer":"以几何图案、对称轴线和直线为特征，采用规则对称构图与整齐修剪的园林形式。","category":"重点","chapter":"二、园林类型与形式／风格"},{"id":"344-t-13","term":"文人园林","answer":"由文人、士大夫主持营造或体现文人审美情趣的园林，以诗画入园、追求意境、托物言志、风格简远雅致。","category":"重点","chapter":"二、园林类型与形式／风格"},{"id":"344-t-14","term":"自然山水园","answer":"以真山真水或模拟自然山水为骨架、再现自然山水景观风貌的园林。","category":"重点","chapter":"二、园林类型与形式／风格"},{"id":"344-t-77","term":"宅园","answer":"依附于住宅的私家园林（多宅旁、宅后），供园主日常生活与游憩赏玩，是私家园林的主要形式。","category":"了解","chapter":"二、园林类型与形式／风格"},{"id":"344-t-76","term":"后现代主义","answer":"20世纪后期反对现代主义单一理性的思潮，在园林中表现为历史文脉、符号隐喻、多元拼贴与大众文化趣味。","category":"了解","chapter":"二、园林类型与形式／风格"},{"id":"344-t-78","term":"极简主义园林","answer":"受极简艺术影响的园林，以简洁几何形、纯粹材质、去除装饰为特征，追求\"少即是多\"的现代景观。","category":"了解","chapter":"二、园林类型与形式／风格"},{"id":"344-t-15","term":"一池三山","answer":"中国古典园林的理水布局模式，源于\"海上仙山\"神话，于池中筑蓬莱、方丈、瀛洲三岛，寄托求仙长生理想，是皇家园林的经典范式。","category":"重点","chapter":"三、园林史与实例（中国·外国）"},{"id":"344-t-16","term":"三山五园","answer":"清代北京西北郊的皇家园林群（三山＝香山、玉泉山、万寿山；五园＝畅春园、圆明园、静明园、静宜园、清漪园即颐和园），代表清代皇家园林的最高成就。","category":"重点","chapter":"三、园林史与实例（中国·外国）"},{"id":"344-t-17","term":"意大利台地园","answer":"意大利文艺复兴园林，依山就势建层层台地，轴线对称，水景雕塑丰富，常绿树修剪整齐，以埃斯特庄园（千泉宫）为代表。","category":"重点","chapter":"三、园林史与实例（中国·外国）"},{"id":"344-t-18","term":"枯山水","answer":"日本园林中不引水、用砂石苔藓表现山水的抽象写意手法，以砂拟水、以石拟山，供静观冥想，龙安寺为代表。","category":"重点","chapter":"三、园林史与实例（中国·外国）"},{"id":"344-t-19","term":"囿和苑","answer":"囿：先秦供帝王狩猎游玩的园地（圈养禽兽）。苑：在囿基础上发展、供帝王游憩居住并附宫室的园林，汉代以后多称\"苑\"。","category":"重点","chapter":"三、园林史与实例（中国·外国）"},{"id":"344-t-20","term":"行宫御苑","answer":"供皇帝出行驻跸、休憩的离宫园林，多建于风景优美的郊野或交通要道，如承德避暑山庄。","category":"重点","chapter":"三、园林史与实例（中国·外国）"},{"id":"344-t-21","term":"西蜀园林","answer":"四川地区的古典园林，依托自然山水、文风浓郁、纪念性突出（名人纪念园、祠宇园林），代表有杜甫草堂、武侯祠、望江楼等。","category":"重点","chapter":"三、园林史与实例（中国·外国）"},{"id":"344-t-75","term":"台与榭","answer":"台：高而平的土筑或石砌建筑，供登高远眺。榭：依水而建的园林建筑，供观水赏景。二者均为古典园林重要建筑类型。","category":"了解","chapter":"三、园林史与实例（中国·外国）"},{"id":"344-t-79","term":"英中式庭院","answer":"18世纪欧洲受中国园林影响、融入自然式元素（中国式塔、桥、蜿蜒水体等）的园林，是\"中国风\"在欧洲的产物。","category":"了解","chapter":"三、园林史与实例（中国·外国）"},{"id":"344-t-87","term":"古希腊柱廊园","answer":"古希腊住宅中以柱廊围合的庭院，是欧洲规则式园林与台地园的源头之一。","category":"了解","chapter":"三、园林史与实例（中国·外国）"},{"id":"344-t-22","term":"园林布局","answer":"对园林中山水、植物、建筑、园路等要素的位置、尺度、序列进行的整体安排与组织，是造园的核心环节。","category":"重点","chapter":"四、布局·空间·程序"},{"id":"344-t-23","term":"园林空间序列","answer":"通过空间的开合、明暗、疏密、抑扬等变化，按一定游览顺序组织形成的空间节奏与秩序，引导游人获得步移景异的体验。","category":"重点","chapter":"四、布局·空间·程序"},{"id":"344-t-24","term":"尺度","answer":"景物与人体及景物各部分之间的大小关系形成的大小感，涉及具体尺寸。方法有单位尺度引进法、人的习惯尺度法、景物与空间尺度法、模度尺设计法。","category":"重点","chapter":"四、布局·空间·程序"},{"id":"344-t-25","term":"风景评估","answer":"对风景资源的质量、价值、敏感度、开发条件等进行的科学评价分析，为规划、保护与利用提供依据。","category":"重点","chapter":"四、布局·空间·程序"},{"id":"344-t-26","term":"园林场地分析","answer":"对拟建场地的自然条件（地形、水系、植被、气候）、人文条件与周边关系进行调查评价，作为设计的依据。","category":"重点","chapter":"四、布局·空间·程序"},{"id":"344-t-27","term":"城市设计","answer":"对城市空间形态与三维形体环境进行的综合性设计，协调建筑、街道、广场、绿地等要素，创造宜人的城市环境。","category":"重点","chapter":"四、布局·空间·程序"},{"id":"344-t-28","term":"城市广场","answer":"城市中供公众集散、活动、交往的开敞空间，具有交通、集会、休闲、景观等多种功能。","category":"重点","chapter":"四、布局·空间·程序"},{"id":"344-t-29","term":"对比律","answer":"对风景要素间差异和矛盾加以组合利用、取得相互比较、相辅相成呼应关系的形式美法则。方法有水平与垂直、体量大小、色彩明暗、布局、开合、疏密对比等。","category":"重点","chapter":"五、形式美法则"},{"id":"344-t-88","term":"旋转的韵律","answer":"同一视觉要素以旋转方向有规律变化而形成的韵律（动感韵律），是节奏与韵律法则的一种表现形式。","category":"了解","chapter":"五、形式美法则"},{"id":"344-t-30","term":"城市绿地","answer":"城市中以植被为主要形态，用于改善生态、美化环境、提供游憩等功能的绿色用地，是城市用地的重要组成部分。","category":"重点","chapter":"六、绿地分类与指标"},{"id":"344-t-31","term":"城市绿线","answer":"城市规划中划定的各类城市绿地范围的控制线，是保护城市绿地的法定界线。","category":"重点","chapter":"六、绿地分类与指标"},{"id":"344-t-32","term":"专类公园","answer":"具有特定内容或形式、有一定游憩设施的公园绿地，如动物园、植物园、儿童公园、纪念性公园、游乐园等。","category":"重点","chapter":"六、绿地分类与指标"},{"id":"344-t-33","term":"城市湿地公园","answer":"纳入城市绿地系统规划、具有湿地生态功能和典型特征，以生态保护、科普教育、自然野趣和休闲游览为主要功能的公园。","category":"重点","chapter":"六、绿地分类与指标"},{"id":"344-t-34","term":"城市绿地率","answer":"城市各类绿地总面积占城市用地总面积的百分比，是衡量城市绿化水平的重要指标。","category":"重点","chapter":"六、绿地分类与指标"},{"id":"344-t-35","term":"广场用地","answer":"城市中以硬质铺装为主、供公众集散与活动的开敞空间用地，绿地率一般较低。","category":"重点","chapter":"六、绿地分类与指标"},{"id":"344-t-36","term":"开敞式绿地","answer":"向公众开放、无围墙或围栏封闭、可供自由进入活动的城市绿地。","category":"重点","chapter":"六、绿地分类与指标"},{"id":"344-t-37","term":"绿道","answer":"以自然植被和人工植被为依托，串联公园、水系、社区等的线性绿色开放空间，兼具游憩、生态与慢行交通功能。","category":"重点","chapter":"六、绿地分类与指标"},{"id":"344-t-38","term":"社区公园","answer":"为一定居住用地范围内的居民服务、有一定活动内容和设施的集中绿地（不含居住组团绿地）。","category":"重点","chapter":"六、绿地分类与指标"},{"id":"344-t-39","term":"装饰性绿地","answer":"以美化、装饰环境为主要功能的绿地，多用于建筑周围、道路节点等，观赏性为主。","category":"重点","chapter":"六、绿地分类与指标"},{"id":"344-t-40","term":"组团绿地","answer":"居住区组团中供居民就近活动的小型集中绿地，面积400㎡以上，服务半径短、使用方便。","category":"重点","chapter":"七、居住区绿地"},{"id":"344-t-41","term":"小区游园","answer":"居住小区内的集中公共绿地，面积4000㎡以上、服务半径400～500m，供居民游憩活动。","category":"重点","chapter":"七、居住区绿地"},{"id":"344-t-42","term":"居住区开放式绿地","answer":"居住区中向居民开放、不封闭的绿化游憩用地，供居民日常活动使用。","category":"重点","chapter":"七、居住区绿地"},{"id":"344-t-43","term":"防护绿地","answer":"具有卫生、隔离和安全防护功能的绿地，含卫生隔离带、道路防护绿地、城市高压走廊绿带、防风林、城市组团隔离带等。","category":"重点","chapter":"八、道路与防护绿地"},{"id":"344-t-44","term":"中央分车带","answer":"城市道路中央分隔上下行车流的分车带，兼作绿化与安全隔离。","category":"重点","chapter":"八、道路与防护绿地"},{"id":"344-t-45","term":"分车带","answer":"道路中分隔不同方向或不同类型车流的带状设施（含中央分车带与两侧分车带），其上的绿化称分车绿带或隔离绿带。","category":"重点","chapter":"八、道路与防护绿地"},{"id":"344-t-46","term":"城市避灾绿地","answer":"发生灾害时可供市民避难、疏散、救援的城市绿地（如公园、广场），具有防灾避险功能。","category":"重点","chapter":"八、道路与防护绿地"},{"id":"344-t-47","term":"长期避险绿地","answer":"规模较大、可较长时间安置灾民并提供生活保障的避灾绿地（如大型综合公园、郊野公园）。","category":"重点","chapter":"八、道路与防护绿地"},{"id":"344-t-48","term":"垂直绿化","answer":"利用攀援植物或绿化设施对墙面、棚架、栏杆、坡面等垂直面进行的绿化。","category":"重点","chapter":"九、植物造景与绿化形式"},{"id":"344-t-49","term":"屋顶绿化","answer":"在建筑物屋顶、露台等进行的绿化，具有隔热、雨水滞留、美化等生态功能。","category":"重点","chapter":"九、植物造景与绿化形式"},{"id":"344-t-50","term":"植物造景","answer":"运用乔木、灌木、藤本、草本及地被植物，通过艺术配置创造园林景观的手法。","category":"重点","chapter":"九、植物造景与绿化形式"},{"id":"344-t-51","term":"通透式配置","answer":"距相邻机动车道路面高度0.9～3.0m范围内树冠不遮挡驾驶员视线的植物配置方式。","category":"重点","chapter":"九、植物造景与绿化形式"},{"id":"344-t-81","term":"室内绿化","answer":"在室内空间配置植物进行绿化美化，改善环境、增添生机。","category":"了解","chapter":"九、植物造景与绿化形式"},{"id":"344-t-83","term":"古树名木","answer":"古树：树龄百年以上的树木。名木：具有重要历史、文化、科学价值或纪念意义的树木。二者均受法律保护。","category":"了解","chapter":"九、植物造景与绿化形式"},{"id":"344-t-84","term":"模纹花坛","answer":"以不同色彩的低矮植物按图案纹样种植、形成整齐精美图案的花坛。","category":"了解","chapter":"九、植物造景与绿化形式"},{"id":"344-t-52","term":"下沉式绿地","answer":"高程低于周边地面或铺装的绿地，利用高差蓄滞、下渗雨水，是海绵城市的重要设施。","category":"重点","chapter":"十、生态与雨洪热点"},{"id":"344-t-53","term":"低碳园林","answer":"在全生命周期内减少碳排放、提升碳汇、实现节能减排的园林。","category":"重点","chapter":"十、生态与雨洪热点"},{"id":"344-t-54","term":"可持续发展园林","answer":"满足当代需求而不损害后代、兼顾生态、经济、社会效益的园林，遵循生态持续性、社会经济持续性、旅游持续性。","category":"重点","chapter":"十、生态与雨洪热点"},{"id":"344-t-55","term":"城市废弃地","answer":"城市中因工业、采矿等活动废弃或退化、失去原有功能的土地（棕地）。","category":"重点","chapter":"十、生态与雨洪热点"},{"id":"344-t-56","term":"海绵城市","answer":"城市像海绵一样，降雨时吸水、蓄水、渗水、净水，需要时释放利用，实现\"渗、滞、蓄、净、用、排\"。","category":"重点","chapter":"十、生态与雨洪热点"},{"id":"344-t-57","term":"廊道","answer":"景观生态学中与本地有所区别的带状土地，既分隔又连接景观的不同部分（如河流、林带）。","category":"重点","chapter":"十、生态与雨洪热点"},{"id":"344-t-58","term":"滨水绿地","answer":"濒临江、河、湖、海等水体布置的绿地，兼具生态、景观与游憩功能。","category":"重点","chapter":"十、生态与雨洪热点"},{"id":"344-t-59","term":"川西林盘","answer":"成都平原以宅院为核心、竹林环绕、农田菜地散布的传统村落景观单元（林＝林盘环境，盘＝聚落）。","category":"重点","chapter":"十、生态与雨洪热点"},{"id":"344-t-60","term":"水体净化","answer":"通过物理、化学、生物（尤其水生植物、微生物）方法去除水体污染物、改善水质的过程。","category":"重点","chapter":"十、生态与雨洪热点"},{"id":"344-t-61","term":"水体富营养化","answer":"水体中氮、磷等营养物质过多，引起藻类大量繁殖、水质恶化的现象。","category":"重点","chapter":"十、生态与雨洪热点"},{"id":"344-t-62","term":"雨水花园","answer":"利用植物、土壤、砾石滞留净化雨水的下凹式绿地设施，兼具景观与雨洪管理功能。","category":"重点","chapter":"十、生态与雨洪热点"},{"id":"344-t-80","term":"生物通道","answer":"为野生动物跨越道路等人工障碍而设置的通道（如动物天桥、涵洞），保障生境连通。","category":"了解","chapter":"十、生态与雨洪热点"},{"id":"344-t-63","term":"森林公园","answer":"具有一定规模和质量的森林风景资源与环境条件、可开展森林旅游，并按法定程序申报批准的森林地域。","category":"重点","chapter":"十一、保护地·乡村与旅游"},{"id":"344-t-64","term":"自然保护区","answer":"对有代表性的自然生态系统、珍稀濒危野生动植物天然集中分布区、有特殊意义的自然遗迹等，依法划出并批准进行特殊保护和管理的区域。","category":"重点","chapter":"十一、保护地·乡村与旅游"},{"id":"344-t-65","term":"风景名胜区","answer":"具有观赏、文化、科学价值，自然人文景观集中，可供游览或科学文化活动的区域；分级为市县级、省级、国家重点。","category":"重点","chapter":"十一、保护地·乡村与旅游"},{"id":"344-t-82","term":"观光农业","answer":"依托农业农村资源，按现代旅游业规律改造配套，赋予观赏、品尝、购买、娱乐、劳动、学习、居住等功能的农业旅游形式，是一三产业融合的产物。","category":"了解","chapter":"十一、保护地·乡村与旅游"},{"id":"344-t-66","term":"假植","answer":"苗木栽植前临时埋土保护根系的措施，防止失水，待正式栽植时使用。","category":"重点","chapter":"十二、工程与设施"},{"id":"344-t-67","term":"竖向设计","answer":"在充分利用原地形基础上，确定园内各景物高程及地形改造方案的设计，含道路建筑标高、排水坡度与土方平衡。","category":"重点","chapter":"十二、工程与设施"},{"id":"344-t-68","term":"园林小品","answer":"园林中体量小巧、造型精美的构筑物与设施（亭廊花架、雕塑、座椅、灯具、指示牌等），兼具功能与景观作用。","category":"重点","chapter":"十二、工程与设施"},{"id":"344-t-69","term":"园林路网设计","answer":"对园内道路系统的分级、布局、线型、密度与铺装进行的规划设计，组织游览交通。","category":"重点","chapter":"十二、工程与设施"},{"id":"344-t-70","term":"园路","answer":"园林中组织游览、引导交通的通道；主干道宽4～6m、纵坡≤8%、横坡1%～4%，布局宜通达成环。","category":"重点","chapter":"十二、工程与设施"},{"id":"344-t-71","term":"驳岸","answer":"园林水体边缘的护岸构筑物，防止水土流失、稳固岸线，兼具景观与亲水功能。","category":"重点","chapter":"十二、工程与设施"},{"id":"344-t-85","term":"园路铺装","answer":"园路表面的铺砌处理（材料、图案、色彩），起耐磨防滑、引导、美化作用。","category":"了解","chapter":"十二、工程与设施"},{"id":"344-t-86","term":"装饰型硬质景观","answer":"以装饰、观赏为主要功能的硬质景观（雕塑、水景、艺术铺装等），突出形式美感。","category":"了解","chapter":"十二、工程与设施"},{"id":"344-t-72","term":"土地承载力","answer":"一定区域内土地资源在保障生态稳定的前提下所能承受的人口与开发活动等的最大限度。","category":"重点","chapter":"十三、总论与评价"},{"id":"344-t-73","term":"游人容量","answer":"在保持景观稳定性、保障游赏质量与安全、合理利用资源的限度内，单位时间、一定规划单元内所能容纳的游人数量。","category":"重点","chapter":"十三、总论与评价"},{"id":"344-t-74","term":"园林规划设计","answer":"在一定范围内由山水、植物、建筑、园路、广场、动物等要素，依据自然科学、艺术与工程技术规律及经济技术条件，利用并模仿自然创造的可观赏、可游憩的理想生态环境。","category":"重点","chapter":"十三、总论与评价"}],"bigs":[{"id":"344-b-1","title":"简述中国古典园林的特点","type":"简答","category":"重点","score":10,"source":"2020","full":[{"h":"1. 本于自然、高于自然","t":"中国园林以自然山水为蓝本，但并非简单模仿。造园者通过叠山理水、植物配置和建筑经营，对自然进行概括、提炼和典型化，使人工山水既有自然之理，又有自然之趣，达到“虽由人作，宛自天开”的境界。"},{"h":"2. 建筑美与自然美融合","t":"亭台楼阁、厅堂廊榭、墙垣漏窗和铺地等，既是使用空间，也是观景对象。建筑多依山傍水、错落布置，以通透轻盈的木构、灰瓦白墙与山水植物相协调，形成可游可居的整体。"},{"h":"3. 诗画情趣","t":"造园常以诗画为蓝本，景名、匾额、楹联点明主题，文人参与相地、立意和品题，使园林具有书卷气和文学意境；一景一题，情景相生。"},{"h":"4. 重意境","t":"通过借景、框景、对景、障景、象征和比德，把景物与人的情感、品格联系起来，使有限空间产生象外之旨，游人由景入情、由情入理。"},{"h":"5. 类型与地域多样","t":"皇家、私家、寺观园林功能不同；北方雄浑、江南秀丽、岭南务实、西蜀朴野，形成多样统一的中国园林体系。"}],"pit":"只答“自然”不答建筑、诗画、意境；漏“虽由人作，宛自天开”。"},{"id":"344-b-2","title":"简述“三远”的基本内容","type":"简答","category":"重点","score":10,"source":"2020","full":[{"h":"1. 高远","t":"自下仰视，视点低、景物高，山势显得高峻突兀，色彩清明。园林中常用高山、台、塔、楼阁造成高耸感，使人产生仰望、崇高之势。"},{"h":"2. 深远","t":"自前窥后，视线穿过层层山峦、洞壑、林木，山势重叠，色彩晦暗。园林常用曲径、山洞、层次植物造成幽深不尽的空间感。"},{"h":"3. 平远","t":"自近望远，视点低平，山势平缓，色彩明丽。园林常用开阔水面、远山、平岗、汀洲，形成平远开阔的意境。"},{"h":"4. 综合应用","t":"三远不是孤立使用，而是根据场地和游线综合组织：高远取势，深远取幽，平远取阔，从而丰富空间层次、引导视线、扩大园林境界。"}],"pit":"只背三个词，不解释视点、效果和园林应用。"},{"id":"344-b-3","title":"简述城市绿地系统规划的原则","type":"简答","category":"重点","score":10,"source":"2021","full":[{"h":"1. 生态优先、因地制宜","t":"结合山水、气候、土壤和现有植被，保护河流、山体、湿地等敏感生态区，构建区域生态安全格局，避免先破坏后修复。"},{"h":"2. 系统完整、均衡布局","t":"以点（公园）、线（绿道、道路绿地）、面（片区绿地）结合，分级配置市级、区级、社区级绿地，按服务半径均衡覆盖，形成网络。"},{"h":"3. 功能复合、以人为本","t":"兼顾生态、游憩、景观、防灾、文化教育等功能，满足老人、儿童、青年等不同人群需求，提高绿地使用效率。"},{"h":"4. 城乡统筹、区域协调","t":"市域、城区、社区相衔接，用绿道、生态廊道连接城乡绿地，统筹建设用地与生态空间。"},{"h":"5. 可实施、有弹性","t":"与总规、控规、专项规划衔接，指标落地，明确用地、资金、建设时序，分期实施并保留弹性。"}],"pit":"只答“保护环境”；不答布局、指标、实施。"},{"id":"344-b-4","title":"简述城市湿地公园的设计原则","type":"简答","category":"重点","score":10,"source":"2022","full":[{"h":"1. 保护优先、最小干预","t":"保护原有水系、湿地植被和动物栖息地，尽量保留自然岸线、浅滩、岛屿，减少土方和硬化，维护湿地生态过程。"},{"h":"2. 生态修复、水质净化","t":"通过人工湿地、雨水湿地、生态驳岸和植物过滤带，恢复水体自净能力，控制面源污染，改善水质。"},{"h":"3. 功能分区、动静分离","t":"按保育区、恢复重建区、合理利用区、管理服务区划分，明确各区和允许活动，保育区禁止游人进入，合理利用区控制容量。"},{"h":"4. 科普游憩、低干扰","t":"设置栈道、观鸟屋、解说牌和自然课堂，组织低干扰游线，控制游客量和活动强度。"},{"h":"5. 地域特色、自然野趣","t":"选用乡土湿地植物，采用自然驳岸和低维护材料，体现地域自然野趣，避免城市公园化。"}],"pit":"把湿地公园做成普通综合公园；漏保育区和容量控制。"},{"id":"344-b-5","title":"简述园林地形的功能作用","type":"简答","category":"重点","score":10,"source":"2019","full":[{"h":"1. 分隔空间、组织边界","t":"山体、坡地、台地可以划分不同空间，形成开合、动静、内外之别，使园林有层次而不一览无余。"},{"h":"2. 控制视线、引导游线","t":"地形可遮挡、夹景、对景，控制视线方向；坡道、台阶、谷地引导游人前行，形成游览节奏。"},{"h":"3. 塑造景观、作为底景","t":"山体、谷地、坡面构成山水骨架，既是观赏对象，也是建筑、植物、水体的底景。"},{"h":"4. 改善小气候、组织排水","t":"坡向、坡度影响日照、通风和汇水；地形组织地表径流，减少积水和冲刷。"},{"h":"5. 承载活动、布置设施","t":"平地、台地、坡地可承载集会、游憩、运动等不同活动，为设施布置提供条件。"},{"h":"6. 小结","t":"地形不是背景，而是组织空间、视线、游线、排水和活动的骨架；设计时应先定山水格局，再落建筑、植物和设施。"},{"h":"7. 应用提示","t":"设计时先定山水格局，再安排建筑、植物和道路，避免先排房子后补地形。"}],"pit":"只答“造景”；不答空间、视线、排水、活动。"},{"id":"344-b-6","title":"简述园林美及其三种形态","type":"简答","category":"重点","score":10,"source":"2023","full":[{"h":"1. 自然美","t":"自然美来自山水、植物、天象的形态、色彩、声音和质感，是园林美的基础。三种形态不是简单相加，而是层层递进、相互渗透。"},{"h":"2. 艺术美","t":"艺术美来自建筑、小品、铺装、雕塑等人工创造，体现设计者的构思和技艺。自然美提供素材，艺术美组织形式，社会美赋予意义。"},{"h":"3. 社会美","t":"社会美来自游憩、交往、文化和历史，体现人的生活方式和精神需求。形式美是共同规律，意境美是最高追求。"},{"h":"4. 形式美","t":"通过对比协调、比例尺度、节奏韵律、均衡统一等形式美法则，把自然、艺术、社会三方面组织成整体。园林审美最终落在人的体验和联想上。"},{"h":"5. 意境美","t":"在形式美基础上情景交融，产生联想和余味，使园林从“好看”升华为“耐看”。因此园林美既是客观形式，也是主观感受。"}],"pit":"只答“好看”；不答三种形态和形式美法则。"},{"id":"344-b-7","title":"以三山五园为例，简析清代皇家园林成就","type":"简答","category":"重点","score":10,"source":"2024","full":[{"h":"1. 三山五园","t":"三山为万寿山、香山、玉泉山；五园为静宜园、静明园、清漪园、圆明园、畅春园，构成清代北京西北郊皇家园林群。"},{"h":"2. 规模宏大、功能齐全","t":"集朝寝、理政、礼佛、游憩、水利于一体，既有宫殿的庄严，又有园林的闲适，体现皇家园林的综合功能。"},{"h":"3. 整体规划、借景山水","t":"以西山、玉泉山、昆明湖为骨架，把园外山水纳入园内，形成大尺度山水园林。"},{"h":"4. 集锦式布局、中西合璧","t":"圆明园四十景各具主题，西洋楼引入西方建筑和喷泉，体现集锦式布局和中西合璧。"},{"h":"5. 艺术成就","t":"代表清代皇家园林高峰，体现“虽由人作，宛自天开”的造园理想，对后世皇家园林影响深远。"}],"pit":"三山、五园名称写错；只答规模不答艺术成就。"},{"id":"344-b-8","title":"简述城市绿地规划与景观设计的关系","type":"简答","category":"重点","score":10,"source":"2024","full":[{"h":"1. 层次不同","t":"规划偏宏观，解决绿地系统、指标、布局和用地；设计偏微观，解决场地、空间、形态和设施。"},{"h":"2. 规划指导设计","t":"规划确定绿地性质、结构、容量、服务半径和指标，为设计提供依据和边界。"},{"h":"3. 设计落实规划","t":"设计通过功能分区、游线、植物、竖向和设施，把规划意图落到具体空间。"},{"h":"4. 设计反馈规划","t":"设计中发现的问题可反馈规划调整，规划应保留弹性，形成双向互动。"},{"h":"5. 共同目标","t":"两者都服务于生态、功能、景观、人本和可持续，不能割裂。"},{"h":"6. 小结","t":"规划解决“在哪里、有多少、是什么”，设计解决“怎么用、怎么美、怎么落地”；两者要双向反馈，不能各自为政。"},{"h":"7. 应用提示","t":"实际项目中先用规划定指标和布局，再用设计检验服务半径、游线和功能是否合理。"}],"pit":"把两者混为一谈；不答双向反馈。"},{"id":"344-b-9","title":"简述风景园林设计方案构思要点","type":"简答","category":"重点","score":10,"source":"2025","full":[{"h":"1. 读懂场地","t":"调查区位、地形、水文、植被、文脉、人群和限制条件，找出场地的机会与问题。"},{"h":"2. 明确目标","t":"确定功能定位、主题、服务对象和指标，避免只做形式。"},{"h":"3. 搭建结构","t":"组织山水骨架、功能分区、轴线节点和动静关系，形成整体布局。"},{"h":"4. 塑造特色","t":"提炼地域文化、植物特色、材料色彩和夜景，形成可识别的景观。"},{"h":"5. 保证落地","t":"考虑竖向、排水、交通、生态、造价和维护，保证方案可实施。"},{"h":"6. 小结","t":"好的构思不是先画形式，而是从场地问题出发，用结构、功能和特色回答“为什么这样设计”。"},{"h":"7. 应用提示","t":"汇报方案时按“场地问题—目标—结构—特色—落地”讲，比只讲形式更有说服力。"}],"pit":"只讲“好看”；不答场地、功能、技术。"},{"id":"344-b-10","title":"中国古典园林与英国自然风景园林的造园理念差异及文化根源","type":"简答","category":"重点","score":10,"source":"2026","full":[{"h":"1. 中国理念","t":"以“天人合一”为哲学基础，以诗画意境为审美理想，追求“虽由人作，宛自天开”，重写意和可游可居。比较时要同时看自然观、空间观和审美理想。"},{"h":"2. 英国理念","t":"受经验主义、浪漫主义和风景画影响，追求自然如画、感伤情调，强调自然本身的美。中国园林强调“可游可居”，英国园林强调“如画观赏”。"},{"h":"3. 中国手法","t":"叠山理水、曲径通幽、借景框景，建筑与山水植物相互成景，空间曲折含蓄。中国园林以建筑点景，英国园林以建筑点缀风景。"},{"h":"4. 英国手法","t":"缓坡草地、树丛、水面、废墟、庙宇，组织如画风景，空间开阔自然。两国都反对规则式，但反对的出发点和程度不同。"},{"h":"5. 文化根源","t":"中国重文人、山水诗画、儒道禅；英国重经验主义、浪漫主义、园林旅行，二者自然观不同。文化根源决定了二者对“自然”的不同理解。"}],"pit":"只答手法，不答文化根源；不答案例。"},{"id":"344-b-11","title":"简述低碳园林的内涵及主要实现途径","type":"简答","category":"重点","score":10,"source":"2026","full":[{"h":"1. 内涵","t":"在全生命周期内降低能耗、减少排放、提高碳汇、降低维护，实现低能耗、低排放、低维护。"},{"h":"2. 规划减排","t":"紧凑布局、保留现状、减少土方和拆除，尽量近自然。"},{"h":"3. 材料减排","t":"使用乡土材料、再生材料和低碳材料，减少水泥、钢材等高碳材料。"},{"h":"4. 植物增汇","t":"构建乔灌草复层，增加碳汇植物，减少大草坪和频繁修剪。"},{"h":"5. 运维减排","t":"利用雨水、太阳能和废弃物循环，推行低碳养护。"},{"h":"6. 小结","t":"低碳园林不是单一技术，而是规划、材料、植物、运维全过程的系统减碳，不能只靠“多栽树”。"},{"h":"7. 应用提示","t":"低碳指标要进入方案评审和后期养护，不能只在设计说明里写口号。"}],"pit":"只答“种树”；不答规划、材料、运维。"},{"id":"344-b-12","title":"简述海绵城市理念在园林绿地设计中的应用途径","type":"简答","category":"重点","score":10,"source":"2026","full":[{"h":"1. 源头减排","t":"设置下沉式绿地、雨水花园、透水铺装、绿色屋顶，就地消纳雨水。"},{"h":"2. 过程控制","t":"用植草沟、旱溪、湿地、雨水塘和调蓄池，延缓、滞蓄和净化径流。"},{"h":"3. 系统治理","t":"蓝绿灰结合，统筹排水防涝、污染控制和资源利用。"},{"h":"4. 植物选择","t":"选用耐湿耐旱、净化能力强、乡土适应性好的植物。"},{"h":"5. 设计衔接","t":"做好竖向、汇水、溢流和维护设计，保证长期运行。"},{"h":"6. 小结","t":"海绵设施必须与竖向、汇水、溢流和维护结合，否则容易“建得起、用不好”。"},{"h":"7. 应用提示","t":"先算汇水分区和高程，再选设施；否则雨水花园可能变成积水坑。"}],"pit":"只列设施；不答竖向、维护、系统。"},{"id":"344-b-58","title":"简述山水画论中的“三远”。","type":"简答","category":"重点","score":10,"source":"2020","full":[{"h":"1. 出处","t":"北宋郭熙《林泉高致》，三种观察与构图方式。"},{"h":"2. 高远","t":"自下仰视山巅，势突兀雄伟，园林中用于高台楼阁仰观。"},{"h":"3. 深远","t":"自前窥后，层层重叠幽深，用于障景、夹景与纵深轴线。"},{"h":"4. 平远","t":"自近望远，冲融缥缈，用于开阔水面与远山借景。"}],"pit":""},{"id":"344-b-59","title":"清代皇家园林“三山五园”及其艺术成就。","type":"简答","category":"重点","score":10,"source":"2024","full":[{"h":"1. 三山","t":"香山、玉泉山、万寿山；五园：静宜园、静明园、清漪园（颐和园）、圆明园、畅春园。"},{"h":"2. 规模宏大","t":"依托西山与海淀水系形成园林集群。"},{"h":"3. 集锦式布局","t":"一园汇集江南胜景，园中有园。"},{"h":"4. 叠山理水成熟","t":"土石相间、借景西山、水系贯通。"},{"h":"5. 中西合璧","t":"圆明园西洋楼引入巴洛克水法与建筑。"}],"pit":""},{"id":"344-b-60","title":"风景园林设计方案的构思要点。","type":"简答","category":"重点","score":10,"source":"2025","full":[{"h":"1. 现状调研","t":"地形、水文、植被、文脉、交通与使用人群。"},{"h":"2. 主题定位","t":"提炼场地特质，确定立意与风格（意在笔先）。"},{"h":"3. 功能布局","t":"分区、出入口、游线、节点与设施。"},{"h":"4. 结构组织","t":"轴线、序列、视线与对景关系。"},{"h":"5. 竖向与水系","t":"地形塑造、排水与雨洪管理。"},{"h":"6. 植物与材料","t":"乡土为主、复层配置、季相与低维护。"},{"h":"7. 可实施性","t":"造价、构造、分期与管理。"}],"pit":""},{"id":"344-b-85","title":"景观可持续性的植物配置策略。","type":"简答","category":"重点","score":10,"source":"2026","full":[{"h":"1. 乡土为主、外来为辅","t":"适地适树，抗逆性强、养护低。"},{"h":"2. 复层群落结构","t":"乔灌草结合，提高叶面积指数与稳定性。"},{"h":"3. 物种多样与生态位错位","t":"避免单一纯林，错开花期与根系层次。"},{"h":"4. 低维护设计","t":"减少高耗水草坪与大色块一年生花卉，多用多年生与自播种。"},{"h":"5. 适应雨洪","t":"耐旱耐涝种类结合下凹绿地与雨水花园。"},{"h":"6. 增汇减碳","t":"选固碳强的树种、保护大树、减少更换运输。"},{"h":"7. 季相与生境兼顾","t":"四季景观与鸟嗜蜜源植物。"}],"pit":""},{"id":"344-b-62","title":"低碳型园林的内涵及主要实现途径。","type":"简答","category":"重点","score":10,"source":"2026","full":[{"h":"1. 内涵","t":"全生命周期（材料、施工、养护、废弃）低能耗低排放低污染，同时增强碳汇。"},{"h":"2. 资源节约","t":"因地制宜，节约水土资源、提高利用率。"},{"h":"3. 材料低碳","t":"就地取材、乡土与再生材料，减少高碳材料与长途运输。"},{"h":"4. 增汇","t":"提高绿量与复层结构，保护现有大树与绿地碳库。"},{"h":"5. 减排","t":"减少硬化与土方，雨水就地消纳，降低灌溉与机械养护能耗。"},{"h":"6. 循环","t":"园林废弃物堆肥还田，减少化肥农药。"},{"h":"7. 管理","t":"低碳养护标准与碳汇计量评估。"}],"pit":""},{"id":"344-b-63","title":"数字化技术对风景园林的促进与创新作用。","type":"简答","category":"重点","score":10,"source":"2026","full":[{"h":"1. 调研","t":"无人机航测、三维激光扫描、GIS与遥感，快速获取地形植被信息。"},{"h":"2. 分析模拟","t":"日照、风环境、雨洪、可视域与热环境模拟，支撑科学决策。"},{"h":"3. 设计","t":"参数化设计与BIM协同，提高精度与专业配合效率。"},{"h":"4. 表现沟通","t":"VR／AR、实时渲染与数字孪生，便于公众参与与方案比选。"},{"h":"5. 施工运维","t":"智慧灌溉、物联网监测、苗木二维码档案，实现精细养护。"},{"h":"6. 创新","t":"从经验设计走向循证设计，从静态图纸走向全周期管理。"}],"pit":""},{"id":"344-b-new19","title":"景观可持续性的植物配置策略","type":"简答","category":"重点","score":10,"source":"2026补编","full":[{"h":"1. 立地适配，适地适树","t":"先判立地条件再选种：光照、土壤质地与酸碱度、地下水位、建筑遮挡、污染与压实程度逐项核对。阳性树不种在建筑北侧，耐荫地被不放在西晒屋面，盐碱地段避开喜酸树种。配置的可持续性首先来自树与地不打架——种错位置，后面所有养护都是补救。"},{"h":"2. 以乡土植物为主体，外来植物为辅","t":"乡土植物对本地气候土壤适应性强、生长快、抗逆性强、低养护，是可持续配置的成本底座；外来树种只在驯化稳定、观赏价值突出时作点缀，比例不宜过半。成都一带的骨干可用水杉、银杏、香樟、楠木、垂丝海棠、慈竹等，配以本地乡土草本地被替代大面积草坪。"},{"h":"3. 复层混交，构建近自然群落结构","t":"按乔木—亚乔木—灌木—地被—草坪组织复层结构，混交林为主体、纯林为辅，常绿与落叶保持合理比例。复层群落郁闭后地面温度与土温波动小、杂草竞争力弱、抗病虫害能力强，养护投入随之下降；同时为鸟类与昆虫提供多层次生境。这就是用结构换维护。"},{"h":"4. 生物多样性与生境营造","t":"选用蜜源、食源与连续开花的植物组合，保证花期衔接；保留部分枯木、落果层与灌丛作为小动物栖息地；对古树名木原地保护、设保护范围并复壮。多样性既提升群落抗逆性，也是景观长期稳定的前提。"},{"h":"5. 低维护与全生命周期成本控制","t":"用耐旱耐瘠薄的乡土草本地被替代高耗水草坪，减少修剪频次；选用抗污染、抗病虫害树种降低农药依赖；灌溉方式配合滴灌与雨水回用；把建设投资与十年养护费合并核算，而不是只比苗木单价。"},{"h":"6. 与雨洪、微气候协同","t":"耐湿树种下沉至下凹绿地与雨水花园，耐旱树种布置于高处，形成水分梯度配置；乔木遮阴降低夏季地表温度，减弱热岛。植物配置由此同时承担海绵与降温功能，一块地办两件事。"},{"h":"7. 动态管理，顺应演替","t":"配置不是一次成景的静态图纸：预留生长空间、按目标密度控制初植、明确演替阶段的管理动作，并建立长期监测以调整。可持续性的检验标准是——十年之后这块绿地是否还需要年年补植。"}],"pit":"只答植物种类，不答立地、乡土、复层、生物多样性、低维护。"},{"id":"344-b-34","title":"简述《园冶》的主要造园思想","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 造园总纲","t":"计成《园冶》是我国古代重要的造园专著，全书以“虽由人作，宛自天开”为总纲，主张人工与自然相融，于人工经营中见天然之趣，反对刻板模仿与过分雕饰，是文人造园经验的系统总结。"},{"h":"2. 因借体宜","t":"提出“巧于因借，精在体宜”：因者随基势高下、依形取势，借者收园外远近之景，使内外一体、虚实相生；又强调“三分匠、七分主人”，园主识见决定园之品格，要之皆在因地成景、因景成境。"},{"h":"3. 相地立基","t":"主张先相地后立基，按山林、城市、村庄、郊野、江湖五类分别处置，因地制宜确定布局、规模与要素，使园与基地相称，于有限基地生出无穷景致，做到虽由人作而宛若天成。"},{"h":"4. 要素意境","t":"掇山、理水、建筑、植物、铺地各得其所，山贵有脉、水贵有源；又以景名、匾额、楹联点题，使诗画入园、情景相生，形成含蓄隽永的文人审美意境，使有限之园具无穷之趣。"}],"pit":"只背两句口号；不答相地、要素、意境。"},{"id":"344-b-35","title":"简述宋代皇家园林艮岳的特点","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 选址格局","t":"艮岳初名万岁山，为宋徽宗所建，位于汴京宫城东北，以人工筑山为主，山环水抱，形成完整山水骨架，是宋代皇家园林代表作，也是叠山艺术的高峰，其规模与气象均超越前代。"},{"h":"2. 叠山艺术","t":"叠山土石结合，峰峦洞壑、悬崖蹬道、瀑布山涧俱全，并广收江南奇石，即“花石纲”所运；山势雄奇而路径幽深，山顶设亭，可登临俯瞰全园；山腹藏洞，蹬道上下贯通。"},{"h":"3. 理水花木","t":"理水使池沼溪涧相连，水随山转，聚分有致，动静结合，水石相激成声；园中荟萃奇花异木、珍禽走兽，四时皆有可观，兼具游赏、养殖与物产之用，水口、瀑布的处理尤见巧思。"},{"h":"4. 建筑命运","t":"建筑亭台楼阁因景而设，移步换景，兼有朝寝、游赏与礼佛之用；靖康之难后园毁于兵火，然其叠山理水成就对后世影响深远，为写意山水园所效法，遂成中国园林史上之绝响。"}],"pit":"只答“皇家园林”；不答叠山、花石纲、命运。"},{"id":"344-b-36","title":"简述意大利台地园的特点","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 选址台地","t":"多建于山坡丘陵地带，依山就势分层筑台，以台阶、挡土墙、栏杆联系上下，形成鲜明的高低层次与多处观景平台，园外风光尽收眼底，空间随高差展开，台地之间以绿廊、剧场相连。"},{"h":"2. 轴线几何","t":"全园以中轴对称，几何式花坛、笔直园路与绿篱图案强调秩序，植物修剪成规整形体，体现人工对自然的控制，轴线尽端常以喷泉或雕像收束，树篱高与人齐，形成绿色屏障。"},{"h":"3. 水景","t":"喷泉、瀑布、水链、水池依高差层层布置，动静结合，兼得水声、清凉与视觉焦点，水景成为全园生气所在，也借水音掩去尘嚣，水池与雕塑结合，成为构图中心。"},{"h":"4. 植物透视","t":"修剪绿篱、造型植物与盆栽强调人工美，借地形与轴线组织深远透视，使园景层层退晕；埃斯特庄园、兰特庄园为代表作，其手法影响欧洲各国，并延续至巴洛克园林。"}],"pit":"只答“台地”；不答轴线、水景、透视。"},{"id":"344-b-37","title":"简述法国古典主义园林的特点","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 中轴统摄","t":"以强烈中轴统摄全园，并向城市延伸，形成放射状道路与节点，全园服从统一秩序，气势恢宏，集中体现中央集权与王权威严，其轴线成为城市结构的骨架，统领城市空间。"},{"h":"2. 几何布局","t":"图案式花坛、对称丛林、笔直园路与修剪绿篱，以规则几何体现理性主义与唯理美学，构图严整而一览无余，显示对自然的绝对支配，丛林园内设剧场、迷宫与喷泉，供游赏之用。"},{"h":"3. 水景","t":"运河、水池、喷泉强化反射与透视，水面成为轴线的延伸，兼收天光云影，使园景辽阔而明净，兼具排水与观赏功能，大运河长达数里，成为全园轴线的高潮，游船可通。"},{"h":"4. 尺度王权","t":"尺度宏大开阔，行列树显示驾驭自然的气魄，象征王权与秩序；凡尔赛宫苑及造园家勒诺特为代表，其模式为欧洲宫廷园林所仿效，成为规则式园林的典范。"}],"pit":"只答“对称”；不答轴线、水景、王权。"},{"id":"344-b-38","title":"简述英国自然风景园的特点","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 崇尚自然","t":"反对规则几何与修剪，追求起伏草地、树丛、蜿蜒水面与自然式园路，宛若郊野，摒弃轴线与围墙，使园林回归自然风貌，如一幅展开的风景画，几不见人工痕迹，建筑隐于树丛之后。"},{"h":"2. 如画理念","t":"受风景画影响，讲究构图、光影与层次，以废墟、庙宇、点景建筑入景，富于画意，寄托怀古与田园理想，景随步移而如展画卷，前景、中景、远景层层推远，虚实相生。"},{"h":"3. 要素手法","t":"缓坡草地、孤植树、树丛、曲折水面为基本要素，边界以隐垣、沟壑处理，视线通透，空间开敞，园内外连成一片，形成无明显边界的大景观，水面曲折有致，时隐时现，与草地相接。"},{"h":"4. 人物影响","t":"肯特、布朗、雷普顿相继推动其成熟，并传播至欧洲，成为现代风景园林的重要源头，其自然观与如画趣味影响至今，作品以草地、树丛与曲折水面见长。"}],"pit":"只答“自然”；不答如画、人物、影响。"},{"id":"344-b-39","title":"简述中国古典园林的分期","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 生成期","t":"先秦至汉，囿、台、苑由生产游猎转向游赏，园居与狩猎、通神相结合，皇家园林雏形初具，出现“一池三山”的山水格局，奠定模拟仙境的传统，台、榭、池、沼的组合已见匠心。"},{"h":"2. 转折期","t":"魏晋南北朝，文人参与造园，自然山水园兴起，寺观园林随之发展，造园由模仿自然转向自觉表现山水之美，园林由帝王专有转向士人普遍参与，题材日广，山水诗画与造园相互渗透。"},{"h":"3. 全盛期","t":"隋唐，宫苑与私家园林并盛，诗画入园，造园技艺与审美趋于成熟，并影响日本等邻国，形成完整园林体系，皇家园林规模宏大，私家园林则以小中见长，气度雍容而不失法度。"},{"h":"4. 成熟集大成","t":"宋代叠山理水成熟，艮岳为代表，文人园林兴盛；明清类型齐备、理论总结，《园冶》问世，中国古典园林臻于集大成，由写实走向写意，形成北方与江南两大风格。"}],"pit":"分期时间写错；只答朝代不答特征。"},{"id":"344-b-40","title":"简述文人园林的特点","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 造园主体","t":"文人、士大夫参与甚至亲自设计，以造园寄托隐逸情怀，园以人传，重文化修养而轻财势炫耀，园名景名多由主人自定，园中一石一木皆经推敲，处处见其学养与性情。"},{"h":"2. 审美取向","t":"求雅致、简远、疏朗、自然，反对富丽繁缛与过度雕饰，重韵味、重留白而轻排场，以少胜多，以淡为贵，陈设花木皆求清雅不俗，一花一木皆有寄托，以意境取胜。"},{"h":"3. 手法","t":"借景、框景、对景灵活运用，诗画入园，以景名、匾额、楹联点题，使全园富于书卷气，景与文相互生发，耐人寻味，入园如入画，景物皆可成图，处处有题可咏，游者因题而会心，余韵悠长。"},{"h":"4. 意境代表","t":"以梅兰竹菊、松竹梅比德象征，寓人格理想，小中见大；拙政园、网师园为代表，为文人写意园之典型，园以人名，人以园传，遂成江南文人园林之典范，为后世园林所宗法。"}],"pit":"只答“文人”；不答审美、手法、意境。"},{"id":"344-b-41","title":"简述寺观园林的特点","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 选址","t":"多择山林名胜、清幽之地，依山傍水，既利修行静养，也便香客朝礼，形成“仙山”环境，远离市井，山门隐于林间，自成“深山藏古寺”的意境，钟磬与松风相和，尘虑顿消。"},{"h":"2. 布局","t":"中轴与自由布局结合，香道、放生池、山门、殿宇次第展开，由俗入圣，渐入宗教境界，钟鼓楼、大雄宝殿依次排布，石阶曲折而上，两侧古木参天，步步生幽，引人入胜。"},{"h":"3. 要素","t":"古树名木、山泉、石刻、佛塔与摩崖造像，共同烘托宗教氛围，兼有园林游赏与休憩功能，形成独特的宗教景观，塔为全园制高点，钟声、香火添其气氛，林木尤见苍古。"},{"h":"4. 氛围代表","t":"宗教肃穆与自然野趣相融，兼供游览与民俗活动；灵隐寺、青城山为代表，山水环境与寺观建筑相得益彰，道教宫观多依山就势，佛教寺院多重轴线，各具特色，与山林泉石融为一体。"}],"pit":"只答“寺庙”；不答选址、布局、氛围。"},{"id":"344-b-42","title":"简述公园城市的内涵","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 以人为本","t":"以人民为中心，把宜居、宜业、宜游统一起来，使市民就近享有绿色空间、公共生活与良好生态，提升获得感与幸福感，公园与社区、街巷相连，形成连续的绿色游憩网络，全龄友好。"},{"h":"2. 城园融合","t":"城市与自然交融，公园不再是城中孤岛，而是城市结构的有机组成，形成城在园中、园在城中的空间格局，城市建成区与生态空间相互渗透，形成有机整体，蓝绿空间连续贯通。"},{"h":"3. 生态优先","t":"保护蓝绿空间，构建生态网络，把生态承载与生态价值纳入城市发展决策，生态成为城市基础设施而非装饰，以生态容量约束开发强度，守住自然生态安全边界。"},{"h":"4. 价值转化","t":"以公园体系、绿道网络、场景营造推动生态价值转化，催生新经济、新场景与新生活，绿色成为竞争力，新业态使生态优势转化为发展优势，惠及市民日常。"}],"pit":"只答“多建公园”；不答人城境业、价值转化。"},{"id":"344-b-43","title":"简述城市绿地系统规划的内容","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 现状与指标","t":"调查绿地、人口、生态条件与存在问题，确定绿地率、人均公园绿地、绿化覆盖率等指标，作为规划目标与考核依据，并分析绿地分布与服务水平的差距，明确补齐重点，指标分解到区县。"},{"h":"2. 布局结构","t":"点线面结合、分级配置，按服务半径均衡布局，以绿道和生态廊道连接城乡，使居民出门即可达绿，缩小服务盲区，形成“综合公园—社区公园—游园”的分级体系，兼顾城乡过渡地带。"},{"h":"3. 分类与专项","t":"公园、防护、附属、区域绿地分类规划，并做绿道、树种、防灾、生物多样性等专项，明确规模、定位与建设标准，并对古树名木保护、植物配置与设施配套提出要求。"},{"h":"4. 实施保障","t":"与总规、控规衔接，落实用地与分期建设，明确管理主体、资金渠道与实施机制，保证指标可落地、可考核，建立绿地信息系统，实行动态监测、定期评估与修编。"}],"pit":"只答指标；不答布局、分类、实施。"},{"id":"344-b-44","title":"简述以国家公园为主体的自然保护地体系","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 体系构成","t":"以国家公园为主体，由国家公园、自然保护区、自然公园三类构成，统一设置、分级管理，实现整体保护与统一监管，各类保护地功能互补、空间衔接，保护强度分级设定。"},{"h":"2. 国家公园","t":"保护大面积、原真性与完整性强的自然生态系统，实行最严格保护，是体系的主体，兼具科研、教育与游憩功能，由中央政府批准设立，实行统一事权、分级管理，游憩利用须特许经营。"},{"h":"3. 自然保护区","t":"保护典型生态系统、珍稀濒危物种及其栖息地，兼顾科研监测与科普教育，禁止不符合保护目标的开发活动，严格限制人为干扰与开发强度，开展生态监测与修复。"},{"h":"4. 自然公园与管控","t":"自然公园保护自然遗迹与风景资源，兼顾游憩；各类保护地划入生态保护红线，分区差别化管控，核心保护区原则上禁止人为活动，允许适度开展科普、游憩与自然教育。"}],"pit":"三类名称写错；不答分区管控。"},{"id":"344-b-45","title":"简述乡村振兴中风景园林的作用","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 生态宜居","t":"整治人居环境，修复水系与山林，治理垃圾污水，提升村落环境品质与防灾能力，使乡村望得见山、看得见水，清理闲置宅基地与废弃坑塘，恢复乡土植被，重塑林盘式的田园景观。"},{"h":"2. 产业融合","t":"以观光农业、民宿、绿道串联资源，把景观优势转化为产业与村民收益，带动就业，促进一二三产融合，把田园与村落连成一体，形成观光、研学、民宿产业链，让村民分享增值收益。"},{"h":"3. 文化传承","t":"保护传统村落、乡土景观与非物质遗产，延续地域风貌与场所记忆，避免同质化，增强文化辨识度，修复祠堂、古桥、水口林等乡土要素，留存村落格局，活化利用闲置民居。"},{"h":"4. 治理生活","t":"以共同缔造推动村民参与和长效维护，完善公共空间与设施，提升宜居水平，实现共建共治共享，建立村民共管机制，明确管护责任与经费来源，实现长效运营。"}],"pit":"只答“美化”；不答产业、文化、治理。"},{"id":"344-b-64","title":"中国古典园林的类型及其风格特点。","type":"简答","category":"了解","score":10,"source":"（母题：2020 中国古典园林特点）","full":[{"h":"1. 皇家园林","t":"规模大、真山真水、富丽堂皇，如颐和园、避暑山庄。"},{"h":"2. 私家园林","t":"规模小、小中见大、精巧雅致，如拙政园、留园。"},{"h":"3. 寺观园林","t":"宗教氛围与自然山水结合，清幽出世，如香山寺、灵隐寺。"},{"h":"4. 风景名胜区","t":"以自然山水为主体、人文点景，供大众游赏。"},{"h":"5. 三者互通","t":"皇家仿私家、私家取寺观意境，共享同一美学标准。"}],"pit":""},{"id":"344-b-65","title":"中国古典园林的造园要素及其组景作用。","type":"简答","category":"了解","score":10,"source":"（母题：2020 中国古典园林特点）","full":[{"h":"1. 叠山","t":"土石堆叠模拟真山，是全园骨架与主景。"},{"h":"2. 理水","t":"聚散有致、曲折有源，聚则开朗、分则幽深。"},{"h":"3. 建筑","t":"亭台楼阁榭舫，点景、观景、分隔空间、组织游线。"},{"h":"4. 植物","t":"自然式配置，重姿态与意境（松竹梅、荷柳）。"},{"h":"5. 关系","t":"山为骨、水为脉、建筑为眼、植物为衣，共造意境。"}],"pit":""},{"id":"344-b-66","title":"中国传统园林艺术创作原理。","type":"简答","category":"了解","score":10,"source":"（母题：2026 中英造园理念）","full":[{"h":"1. 造园之始，意在笔先","t":"先有构思与立意。"},{"h":"2. 相地合宜，构园得体","t":"考察地形地貌，因地制宜。"},{"h":"3. 巧于因借，精在体宜","t":"借园外之景，得体合宜。"},{"h":"4. 欲扬先抑，柳暗花明","t":"入口障景，渐入佳境。"},{"h":"5. 起结开合，步移景异","t":"组织游线与节奏。"},{"h":"6. 小中见大，咫尺山林；虽由人作，宛自天开","t":"以有限造无限。"}],"pit":""},{"id":"344-b-67","title":"中国园林造景手法体系。","type":"简答","category":"了解","score":10,"source":"（母题：借景·框景类名解）","full":[{"h":"1. 主景与配景","t":"以位置、体量、色彩、视线交汇突出主景。"},{"h":"2. 对景与夹景","t":"轴线两端互为对景，两侧夹峙强化景深。"},{"h":"3. 障景与抑景","t":"欲扬先抑，入口常用山石影壁。"},{"h":"4. 框景与漏景","t":"以门窗洞框取画面，漏窗半遮半露。"},{"h":"5. 借景","t":"远借、邻借、仰借、俯借、应时而借（《园冶》）。"},{"h":"6. 添景与点景","t":"以小品植物补足构图，匾联点题。"}],"pit":""},{"id":"344-b-68","title":"规则式园林与自然式园林的比较。","type":"简答","category":"了解","score":10,"source":"（母题：2026 中英造园理念差异）","full":[{"h":"1. 构图","t":"规则式以轴线对称为骨架；自然式以自由曲线、不对称均衡为骨架。"},{"h":"2. 地形与水","t":"规则式平地为主、水池几何形；自然式起伏地形、自然水岸。"},{"h":"3. 植物","t":"规则式行列修剪、花坛花境；自然式丛植群植、模拟自然群落。"},{"h":"4. 代表","t":"凡尔赛（规则式）／中国古典园林与英国自然风景园（自然式）。"},{"h":"5. 适用","t":"规则式宜纪念性轴线空间；自然式宜休憩游赏与生态绿地。"}],"pit":""},{"id":"344-b-69","title":"日本园林与中国园林的异同。","type":"简答","category":"了解","score":10,"source":"（母题：2026 中英造园理念差异）","full":[{"h":"1. 相同","t":"同源于中国园林，重自然、重意境、以小见大。"}],"pit":""},{"id":"344-b-70","title":"园林意境的创造手法。","type":"简答","category":"了解","score":10,"source":"（母题：2020 三远·2023 园林美）","full":[{"h":"1. 借景生情","t":"以景物触发联想。"},{"h":"2. 景名与匾联点题","t":"以文字点出景外之意。"},{"h":"3. 象征与比德","t":"松竹梅喻品格，荷喻清廉。"},{"h":"4. 空间序列与抑扬","t":"以曲折开合强化情绪转折。"},{"h":"5. 虚实相生","t":"水面、粉墙、漏窗形成虚实与倒影。"},{"h":"6. 时相变化","t":"四季晨昏雨雪引发不同意境。"}],"pit":""},{"id":"344-b-71","title":"历史名园（遗产园林）保护与利用的原则。","type":"简答","category":"了解","score":10,"source":"（母题：2024 三山五园）","full":[{"h":"1. 真实性","t":"保护原构、原材料、原工艺与历史信息。"},{"h":"2. 完整性","t":"保护整体格局、山水骨架与周边风貌。"},{"h":"3. 分级分类保护","t":"文保单位、历史建筑、风貌协调区分层管控。"},{"h":"4. 最小干预与可逆性","t":"以加固为主，新增设施可逆。"},{"h":"5. 合理利用","t":"以展示游赏教育为主，控制容量、收益反哺保护。"}],"pit":""},{"id":"344-b-72","title":"现代风景园林的发展趋势。","type":"简答","category":"了解","score":10,"source":"（母题：2026 数字化·低碳·可持续）","full":[{"h":"1. 生态化","t":"从造景走向生态修复与生物多样性支持。"},{"h":"2. 低碳可持续","t":"全生命周期减排增汇、低维护设计。"},{"h":"3. 数字化","t":"GIS、参数化、BIM、数字孪生与智慧运维。"},{"h":"4. 人本与健康","t":"康复景观、全龄友好、公共健康导向。"},{"h":"5. 区域与国土尺度","t":"公园城市、国家公园、绿道网络、流域治理。"},{"h":"6. 文化与遗产并重","t":"地域特色与历史文脉的保护性设计。"}],"pit":""},{"id":"344-b-73","title":"公园城市理念的内涵及实现途径。","type":"简答","category":"了解","score":10,"source":"（母题：2026 热点）","full":[{"h":"1. 内涵","t":"以生态文明为引领，把城市建成大公园，实现城园融合、公共空间与生态价值优先。"},{"h":"2. 空间","t":"以绿道与蓝绿网络为骨架，公园与城市功能混合布局。"},{"h":"3. 形态","t":"破除围墙公园，开放边界、街区即景区。"},{"h":"4. 生态","t":"生态廊道连通、通风廊道、雨洪管理、生境营造。"},{"h":"5. 价值","t":"生态价值转化与场景营造，带动产业与社区活力。"},{"h":"6. 成都例","t":"天府绿道＋环城生态区＋公园城市示范区（2018 提出、2020 明确示范区）。"}],"pit":""},{"id":"344-b-74","title":"城市绿地的分类及各类绿地的功能。","type":"简答","category":"了解","score":10,"source":"（母题：2021 绿地系统规划原则）","full":[{"h":"1. 公园绿地（G1）","t":"向公众开放、以游憩为主，兼具生态美化防灾功能。"},{"h":"2. 防护绿地（G2）","t":"卫生隔离、防风固沙、安全防护。"},{"h":"3. 广场用地（G3）","t":"集散、纪念、市民活动与景观展示。"},{"h":"4. 附属绿地（G4）","t":"居住、公共设施、道路与工业附属绿地，改善微环境。"},{"h":"5. 区域绿地（G5）","t":"风景名胜、水源保护、生态保育等区域生态空间。"}],"pit":""},{"id":"344-b-75","title":"城市绿地主要指标的意义与局限。","type":"简答","category":"了解","score":10,"source":"（母题：2022/2024/2025 绿地评价）","full":[{"h":"1. 绿地率","t":"绿地面积占用地总面积比例，反映总量。"},{"h":"2. 绿化覆盖率","t":"乔灌木树冠投影覆盖比例，反映绿量，可大于绿地率。"},{"h":"3. 人均公园绿地面积","t":"公园绿地面积／人口，反映享有水平。"},{"h":"4. 公园绿地服务半径覆盖率","t":"反映可达性与分布均衡。"},{"h":"5. 局限","t":"只反映数量，不反映质量、结构与连通性，须与格局和生态功能指标并用。"}],"pit":""},{"id":"344-b-76","title":"城市绿地系统规划的内容与步骤。","type":"简答","category":"了解","score":10,"source":"（母题：2021 绿地系统规划原则）","full":[{"h":"1. 现状调查与评价","t":"绿地资源、指标、格局与问题诊断。"},{"h":"2. 确定目标与指标","t":"与国家标准及先进城市对比，定总量与人均指标。"},{"h":"3. 布局结构","t":"确定环、楔、廊、园、网结构与各类绿地布局。"},{"h":"4. 分类规划","t":"公园、防护、附属、区域绿地分别落实用地。"},{"h":"5. 植物与特色","t":"树种规划、生物多样性保护、风貌特色。"},{"h":"6. 实施保障","t":"分期建设、用地落实、资金与管理机制。"}],"pit":""},{"id":"344-b-77","title":"公园绿地选址原则与服务半径。","type":"简答","category":"了解","score":10,"source":"（母题：2026 论述 公园绿地布局）","full":[{"h":"1. 必要性、可能性、整体性","t":"需求、用地条件与系统关系兼顾。"},{"h":"2. 按服务对象定服务半径","t":"综合公园 2000—3000m，社区公园 500—1000m，游园 300—500m。"}],"pit":""},{"id":"344-b-78","title":"公园功能分区与出入口设计原则。","type":"简答","category":"了解","score":10,"source":"（母题：2026 论述 公园绿地布局）","full":[{"h":"1. 分区原则","t":"保护利用自然、满足功能、避免干扰、布局高效。"},{"h":"2. 典型分区","t":"游览休息、文化娱乐、体育活动、儿童活动、安静休息、管理区。"},{"h":"3. 出入口分级","t":"主入口、次入口、专用入口。"},{"h":"4. 位置","t":"与城市道路直接连接，与游人方向流量相适应，便于集散。"},{"h":"5. 设计","t":"内外广场、停车、无障碍、识别性与特色。"}],"pit":""},{"id":"344-b-79","title":"居住区绿地规划原则与定额指标。","type":"简答","category":"了解","score":10,"source":"（母题：绿地指标类）","full":[{"h":"1. 分级配置","t":"居住区公园、小区游园、组团绿地、宅旁绿地。"},{"h":"2. 定额","t":"居住区公共绿地占总用地7.5%—18%，小区5%—15%，组团3%—6%。"},{"h":"3. 人均","t":"居住区＞1.5㎡/人，小区＞1㎡/人，组团＞0.5㎡/人。"}],"pit":""},{"id":"344-b-80","title":"城市道路绿地设计要点。","type":"简答","category":"了解","score":10,"source":"（母题：绿地系统规划类）","full":[{"h":"1. 断面形式","t":"一板二带、二板三带、三板四带、四板五带。"},{"h":"2. 分车绿带","t":"控制宽度与植物高度，保证行车视距与安全。"},{"h":"3. 行道树","t":"分枝点高、干直、耐修剪、抗污染、深根性，株距按冠幅定。"},{"h":"4. 与管线协调","t":"避开架空线与地下管线，保证净距。"},{"h":"5. 功能兼顾","t":"遮阴、降噪、滞尘、导向与景观。"}],"pit":""},{"id":"344-b-81","title":"竖向设计的内容与作用。","type":"简答","category":"了解","score":10,"source":"（母题：2019 园林地形功能）","full":[{"h":"1. 内容","t":"确定场地标高、坡度、台地、水体常水位与驳岸、道路与构筑物标高。"},{"h":"2. 土方平衡","t":"就地平衡、减少外运，控制造价。"},{"h":"3. 排水组织","t":"径流路径、汇水分区、雨水口与溢流口。"},{"h":"4. 空间塑造","t":"以高程变化划分空间、控制视线与观景层次。"},{"h":"5. 衔接","t":"出入口坡道与无障碍坡度（不大于1:12）。"},{"h":"6. 安全防护","t":"边坡稳定、挡土墙、护栏。"}],"pit":""},{"id":"344-b-82","title":"园路布局原则与线形坡度设计。","type":"简答","category":"了解","score":10,"source":"（母题：2019 园林地形功能）","full":[{"h":"1. 因地制宜","t":"与地形、水体、植被配合。"},{"h":"2. 主次分明","t":"分主园路、次园路、游步道，宽度与功能有别。"},{"h":"3. 通达成环","t":"形成环路，避免走回头路。"},{"h":"4. 密度适宜","t":"按功能分区与游人量定路网密度。"},{"h":"5. 线形","t":"综合公园多用自由曲线；山地园路与等高线斜交形成缓坡。"},{"h":"6. 坡度","t":"纵坡一般小于8%，特殊地段设台阶并配无障碍通道。"},{"h":"7. 与建筑关系","t":"园路一般不穿越建筑，交叉处设小广场。"}],"pit":""},{"id":"344-b-83","title":"园林植物种植设计的原则与群落式配置。","type":"简答","category":"了解","score":10,"source":"（母题：2026 景观可持续性植物配置）","full":[{"h":"1. 适地适树","t":"以乡土植物为主，珍贵驯化种为辅。"},{"h":"2. 满足功能","t":"遮阴、分隔、防护、观景兼顾。"},{"h":"3. 符合美学","t":"统一与变化、主从与均衡、季相与色彩。"},{"h":"4. 生态合理","t":"复层结构、生态位错位、多样性、避免相克组合。"},{"h":"5. 经济可行","t":"抗逆性强、病虫害少、养护成本低。"},{"h":"6. 群落式配置","t":"以建群种加伴生种构成稳定群落，提高抗逆性与景观持续性。"}],"pit":""},{"id":"344-b-84","title":"生态驳岸与水体景观设计要点。","type":"简答","category":"了解","score":10,"source":"（母题：2022 湿地公园·2026 海绵城市）","full":[{"h":"1. 驳岸类型","t":"自然缓坡、石笼、木桩、生态挡墙，替代硬质直立驳岸。"},{"h":"2. 恢复水陆过渡带","t":"挺水—湿生—陆生植物带，形成生境与自净界面。"},{"h":"3. 形态设计","t":"宜曲不宜直，聚散有致，形成深浅与岛屿。"},{"h":"4. 水质保障","t":"补水与循环、湿地净化、控制面源污染。"},{"h":"5. 亲水与安全","t":"亲水平台、栏杆、警示与防滑，水深分级。"},{"h":"6. 枯水与丰水兼顾","t":"常水位、防洪标高与季节性水位变化设计。"}],"pit":""},{"id":"344-b-13","title":"论述中日传统园林的异同及成因","type":"论述","category":"重点","score":15,"source":"2019","full":[{"h":"1. 总述","t":"中日传统园林同源于自然山水、诗画和禅宗，都重借景、象征和意境，但因地理、宗教、社会与审美不同，形成“同源异流”的两种风格。二者都把自然视为审美对象，而不是征服对象。"},{"h":"2. 自然观相同","t":"都以自然山水为蓝本，反对纯几何规则，强调人工与自然相融，追求“虽由人作，宛自天开”的境界。借景、框景、象征是共同的空间语言。"},{"h":"3. 手法相通","t":"都运用借景、框景、象征，以有限空间表达无限意境；都重视水石、植物和建筑的关系。禅宗的静观传统在两国园林中都有体现。"},{"h":"4. 文化同源","t":"都受山水诗画和禅宗影响，强调静观、内省和象外之旨，园林不只是游赏空间，也是精神空间。中国园林更强调可游可居，日本园林更强调静观。"},{"h":"5. 尺度与建筑不同","t":"中国园林尺度较大、建筑较多，强调可游可居；日本园林尺度较小，建筑少而精，更重静态观赏。中国叠山理水、曲径通幽；日本枯山水、茶庭、露地。"},{"h":"6. 造景与审美不同","t":"中国重叠山理水、曲径通幽，重诗画意境和生活情趣；日本重枯山水、茶庭、白砂石组、苔藓和露地，重极简、静观和禅意。两国园林都受中国山水画和禅宗影响，但日本更早走向极简。"},{"h":"7. 成因","t":"地理环境、宗教与社会结构、审美理想和造园匠人不同，使两国园林走向不同方向。地理、宗教、社会结构和审美理想共同作用。"},{"h":"8. 结论","t":"二者同源异流，中国园林偏写意与生活，日本园林偏静观与禅意，共同构成东方园林的两种典范。因此比较研究要放在文化系统中看。"}],"pit":"只答差异不答共同源头；成因只写“文化不同”太虚。"},{"id":"344-b-14","title":"从风景园林角度论述“城市双修”及现实作用","type":"论述","category":"重点","score":15,"source":"2019","full":[{"h":"1. 内涵","t":"城市双修包括生态修复和城市修补：修复山体、水体、棕地和绿地，修补设施、空间和文脉。"},{"h":"2. 背景","t":"城市病、存量更新和人民对美好生活的需求，使城市从增量扩张转向存量提质。"},{"h":"3. 风景园林作用","t":"构建生态网络、修复水系、增补绿地、更新公共空间、保护历史文脉。"},{"h":"4. 主要措施","t":"山体修复、黑臭水体治理、棕地再生、老旧小区改造、街道更新、口袋公园。"},{"h":"5. 案例","t":"成都天府绿道、三亚双修、徐州采煤塌陷区修复。"},{"h":"6. 结论","t":"城市双修让城市更生态、更宜居、更有文化，是风景园林参与城市治理的重要路径。"},{"h":"7. 实施保障","t":"城市双修需要规划、园林、市政、水利、社区多方协同，建立项目库、资金机制和后期运维，避免一次性工程。"},{"h":"8. 应用提示","t":"答题要落到风景园林抓手：绿地网络、水系修复、棕地再生、公共空间更新。"}],"pit":"只写生态修复，漏“城市修补”；不答风景园林具体抓手。"},{"id":"344-b-15","title":"试述西蜀园林的特点及其研究意义","type":"论述","category":"重点","score":15,"source":"2020","full":[{"h":"1. 地域基础","t":"西蜀园林以成都平原为中心，依托都江堰水系和川西林盘，融合蜀文化、道教文化和移民文化，形成独特的地方园林体系。都江堰水系为园林理水提供了稳定水源。这种水源条件使西蜀园林普遍重视水景经营。"},{"h":"2. 因水成园","t":"水系发达，园林多引水、理水，形成灵动自然的水景，水与山石、建筑、花木相互映衬。水景多与山石、建筑、花木组合，形成自然水口。水口、驳岸、桥亭的处理多顺应自然，少用规则式。"},{"h":"3. 自然朴野、布局自由","t":"不强求中轴对称，因地制宜，风格自然质朴，少雕琢，多野趣。布局顺应地形，少用轴线，空间自由灵活。自由布局与四川盆地湿润气候、丘陵地形相适应。"},{"h":"4. 祠庙园林多","t":"纪念性、公共性强，如杜甫草堂、武侯祠等，兼具祭祀、游憩和文化功能。祠庙园林兼具祭祀、游憩、教育功能。祠庙园林也是地方公共活动和文化记忆的载体。"},{"h":"5. 文人参与、乡土花木","t":"诗酒文化浓厚，文人参与造园和品题；多用乡土花木，具有地方生活气息。乡土花木如竹、梅、海棠、银杏等使用普遍。乡土花木适应本地气候，养护成本低，地方识别性强。"},{"h":"6. 代表与意义","t":"代表有望江楼、杜甫草堂、武侯祠、罨画池；研究可补足中国园林地域类型，保护地方遗产，为当代公园城市和在地性设计提供依据。研究西蜀园林有助于理解中国园林的地域多样性。因此西蜀园林研究对地域遗产保护和当代设计都有价值。"}],"pit":"只答“自然”；不答祠庙、文人、水系；不答当代意义。"},{"id":"344-b-16","title":"论述中国古典园林的类型及其风格特点","type":"论述","category":"重点","score":15,"source":"2021","full":[{"h":"1. 总述","t":"中国古典园林按隶属关系可分为皇家园林、私家园林、寺观园林和风景名胜区四类，类型不同，功能、规模和风格也不同。四类园林的服务对象不同，审美取向也不同。分类的目的是说明不同园林在社会功能上的差异。"},{"h":"2. 皇家园林","t":"规模大、轴线强、富丽，功能齐全，集朝寝、理政、游憩于一体，代表颐和园、避暑山庄。皇家园林以轴线、体量和装饰显示权威。皇家园林的宏大与礼制秩序密切相关。"},{"h":"3. 私家园林","t":"规模小、精致自由，重文人意境，常用借景、框景、叠山理水，代表拙政园、留园。私家园林以小巧、曲折、借景表现文人趣味。私家园林的精致与文人隐逸生活密切相关。"},{"h":"4. 寺观园林","t":"依托山林，宗教氛围浓，布局中轴与自由结合，代表灵隐寺、青城山。寺观园林以山林环境和宗教氛围为特色。寺观园林的选址和布局服务于宗教活动。"},{"h":"5. 风景名胜区","t":"自然人文复合，范围大，以自然山水为主体，代表西湖、峨眉山。风景名胜区以自然山水为主体，人工点缀为辅。风景名胜区更多体现自然保护与公共游赏。"},{"h":"6. 地域与结论","t":"北方雄浑、江南秀丽、岭南务实、西蜀朴野，四类园林与地域风格共同构成中国园林体系。地域风格使中国园林呈现“多样统一”的格局。地域风格是自然条件和文化传统长期作用的结果。"}],"pit":"分类不全；只答风格不答服务对象/布局。"},{"id":"344-b-17","title":"论述城市湿地公园总体规划内容和各功能分区的保护要求","type":"论述","category":"重点","score":15,"source":"2022","full":[{"h":"1. 总规内容","t":"包括现状调查、目标定位、规模容量、功能分区、水系治理、交通游线、植物、设施和分期建设。"},{"h":"2. 保育区","t":"严格保护，禁止游人进入，只允许监测和科研，维护湿地原真性。"},{"h":"3. 恢复重建区","t":"退耕还湿、拆除违建、修复植被和水系，限制进入，促进生态恢复。"},{"h":"4. 合理利用区","t":"开展科普、游憩、观鸟等活动，控制容量和线路，减少干扰。"},{"h":"5. 管理服务区","t":"集中布置游客中心、停车、环卫等设施，便于管理。"},{"h":"6. 保障措施","t":"建立水质、生态和容量监测，鼓励社区参与，实行动态管理。"},{"h":"7. 实施保障","t":"规划要与国土空间规划、水系规划衔接，明确用地边界、资金和分期；建成后持续监测水质、生境和游憩影响。"},{"h":"8. 结论","t":"湿地公园的核心是“保护优先、适度利用”，分区管理是把保护落到实处的手段。"},{"h":"9. 应用提示","t":"成都活水公园、西溪湿地都可作为“保护+科普+游憩”的案例。"}],"pit":"分区名称写错；只答“保护”不答各分区具体行为。"},{"id":"344-b-18","title":"论述儿童公园的设计特点","type":"论述","category":"重点","score":15,"source":"2022","full":[{"h":"1. 安全第一","t":"设施无尖角，铺装软质，视线通透，家长可看护，避免深水、陡坡和危险植物。"},{"h":"2. 尺度适宜","t":"设施、道路、厕所、座椅按儿童尺度设计，方便使用。"},{"h":"3. 年龄分区","t":"幼儿、学龄前、学龄儿童分区，动静分离，避免大龄儿童冲撞幼儿。"},{"h":"4. 游憩与教育","t":"设置游戏、攀爬、沙水、自然认知和科普活动，寓教于乐。"},{"h":"5. 植物与色彩","t":"选用无毒无刺、季相丰富的植物，色彩明快，夏季有遮阴。"},{"h":"6. 案例","t":"成都儿童公园、社区儿童活动场，强调自然、互动和全龄共享。"},{"h":"7. 使用后评价","t":"建成后要观察儿童使用行为、看护便利性和设施安全，持续调整分区、设施和植物。"},{"h":"8. 结论","t":"儿童公园不是“缩小版成人公园”，而是以儿童尺度、安全、游戏和自然教育为核心的空间。"},{"h":"9. 应用提示","t":"可结合社区儿童公园说明“安全、尺度、年龄分区、自然教育”如何落地。"}],"pit":"只答“游乐设施”；不答安全、尺度、分区、植物。"},{"id":"344-b-19","title":"论述色彩的感觉在园林中的应用","type":"论述","category":"重点","score":15,"source":"2023","full":[{"h":"1. 色彩基本感觉","t":"色彩有色相、明度、纯度，产生冷暖、远近、轻重、软硬和情绪联想。"},{"h":"2. 植物色彩","t":"利用花、叶、果、枝的季相变化，组织春华秋实、四季有景。"},{"h":"3. 建筑与小品","t":"墙面、屋顶、亭廊、雕塑控制主色调，形成统一或对比。"},{"h":"4. 铺装与水体","t":"材料色彩、倒影和夜景灯光丰富空间层次。"},{"h":"5. 构图原则","t":"运用对比调和、节奏韵律、主次和统一，避免杂乱。"},{"h":"6. 案例","t":"杭州西湖、成都公园城市、秋色叶景区，均以色彩组织游赏。"},{"h":"7. 夜景与材料","t":"夜景灯光、铺装材料和建筑色彩会改变白天构图，设计要统一考虑昼夜效果。"},{"h":"8. 结论","t":"色彩设计要服从整体主色调和空间氛围，不能只追求“花哨”，而要用色彩组织视线和情绪。"},{"h":"9. 应用提示","t":"可结合西湖秋色、成都蓝花楹、夜景灯光说明色彩的季相和情绪作用。"}],"pit":"只写“红色热情”这类套话；不答具体载体和构图。"},{"id":"344-b-20","title":"试述中国古典园林植物造景的特点","type":"论述","category":"重点","score":15,"source":"2024","full":[{"h":"1. 自然式配置","t":"仿自然群落，采用孤植、对植、丛植、群植，不排图案，强调自然姿态。"},{"h":"2. 诗画意境","t":"以植物命题、点景，梅兰竹菊、松竹梅，景名与植物相互生发。"},{"h":"3. 比德与象征","t":"植物人格化，荷花出淤泥、竹子虚心、松柏常青，寄托品格。"},{"h":"4. 季相与时空","t":"春华秋实、四时景异，配合建筑题名，形成时间维度。"},{"h":"5. 造景手法","t":"框景、借景、障景、夹景，与山水建筑组合，形成画面。"},{"h":"6. 地域特色","t":"北方松柏、江南桃柳、岭南榕竹、西蜀花木，体现地方风貌。"},{"h":"7. 养护与地域","t":"古典园林植物讲究“因树制宜”，通过修剪、牵引和养护塑造姿态，同时选用适应本地气候的乡土树种。"},{"h":"8. 结论","t":"古典植物造景的核心不是植物列表，而是自然、诗画、比德、季相和手法的综合，形成“景有尽而意无穷”。"},{"h":"9. 应用提示","t":"拙政园、留园的植物配置可作为“自然、诗画、比德、季相”的例证。"}],"pit":"只答“种树”；不答比德、季相、手法。"},{"id":"344-b-21","title":"试述我国康复景观的设计","type":"论述","category":"重点","score":15,"source":"2025","full":[{"h":"1. 概念与对象","t":"康复景观是以促进身心康复为目标的室外环境，借助自然要素与专业活动辅助治疗。其对象包括老年人、儿童、病患、残障人士及长期处于高压状态的职业人群，体力、感知与心理需求差异明显，须先明确使用主体，再确定空间内容与活动强度。"},{"h":"2. 目标与机制","t":"设计目标为恢复生理机能、缓解精神压力、促进社会交往与自然接触。其作用机制在于注意力恢复与应激缓解：柔和的自然刺激降低心理疲劳，可参与的园艺与散步带来掌控感，公共空间又为陪护者与病友提供交流机会。"},{"h":"3. 选址与可达","t":"选址宜安静、向阳、避风，远离噪声与污染源，并靠近病房、住区或社区服务中心，缩短出行距离。场地应平缓无障碍，入口与主园路满足轮椅回转，设置扶手、座椅与清晰标识，保证体弱者能够独立到达并安全返回。"},{"h":"4. 空间组织","t":"按使用强度分区：近端设安静休憩与私密交谈空间，中部设散步环道与园艺操作区，远端设轻度活动与社交广场。各区以植物、地形柔和分隔，视线可及而互不干扰，形成由静到动、由私密到公共的过渡序列。"},{"h":"5. 五感与园艺","t":"五感设计是核心手段：视觉取柔和色彩与季相变化，听觉借水声鸟鸣掩蔽噪声，嗅觉选芳香植物，触觉设可触摸的质感材料，味觉结合可食植物。园艺疗法通过栽植、修剪、采收训练肢体与认知，须在专业人员指导下开展。"},{"h":"6. 评估与维护","t":"建成后应开展使用后评价，记录使用频率、停留时间、活动类型与使用者反馈，并结合量表观测情绪与康复指标。据此调整设施与植物配置，同时建立低维护、少农药的养护制度，明确管理主体与安全责任，保证长期有效运行。"}],"pit":"只答“种花种草”；不答对象、无障碍、评估。"},{"id":"344-b-22","title":"试述中国传统园林艺术创作原理","type":"论述","category":"重点","score":15,"source":"2025","full":[{"h":"1. 总纲","t":"传统园林创作以“虽由人作，宛自天开”为最高准则，以“巧于因借，精在体宜”为方法总纲。前者要求人工造景不留斧凿痕迹，后者强调顺应场地条件、恰如其分地组织景物，二者共同构成由观念到操作的完整体系。"},{"h":"2. 相地","t":"相地即选址与用地分析，按山林、城市、村庄、郊野、江湖分类，辨其高下、水源、植被与视线。计成主张“相地合宜，构园得体”，山地宜台、水边宜榭，因高堆山、就低凿池，使布局从场地中生长出来，而非套用固定程式。"},{"h":"3. 立意","t":"立意先于布局，园主以诗画命题确定全园格调与情感基调，如归隐、清逸、旷达。立意通过景名、匾额、楹联与主景树石表达，使山水建筑共同服务于一个主题，做到景不徒设、必有缘由，避免堆砌景物而无主旨。"},{"h":"4. 布局","t":"布局以山水为骨架，先定山池关系，再安顿建筑。常用手法为曲折幽深、虚实开合、主次分明：以假山粉墙遮挡，使空间欲露先藏；以水面洞门开敞，形成收放节奏；以主峰主厅统摄全局，其余景点环拱呼应。"},{"h":"5. 手法","t":"借景为最重要手法，分远借、邻借、仰借、俯借、应时而借，把园外塔影山色纳入园中。配合框景、对景、障景、夹景、漏景控制视线，使游人在行进中不断获得新画面，形成步移景异、小中见大的空间体验。"},{"h":"6. 要素","t":"叠山理水、建筑点景、植物季相与铺装小品共同成景。叠山讲求峰峦洞壑与皴法纹理，理水讲求聚散与源流，建筑以亭廊桥榭点景观景，植物以孤植丛植写意并承担比德象征，各要素统一于同一意境之下而不各自为政。"}],"pit":"只背两句口号；不答相地、布局、手法。"},{"id":"344-b-23","title":"论述城市公园绿地布局的方式、内容及管理参与","type":"论述","category":"重点","score":15,"source":"2026","full":[{"h":"1. 布局模式","t":"常见布局模式有点状、带状、环状、放射状与网络状。点状依托独立地块，服务集中；带状沿河湖道路展开，串联性强；环状与放射状以绿道连接中心与外围；网络状以廊道把各级绿地织成系统，是公园城市倡导的方向。"},{"h":"2. 分级与内容","t":"按规模与服务范围分综合公园、社区公园、专类公园与游园。综合公园功能齐全、内容综合；社区公园贴近日常，以休憩健身为主；专类公园突出主题，如儿童、体育、纪念；游园规模小、分布广，四类互补形成层级。"},{"h":"3. 数量与分布","t":"数量分布以服务半径、人均公园绿地面积、绿地率与可达性控制。居住区级公园按步行可达布点，消除服务盲区；老城区增补小微绿地，新区预留弹性用地。均衡性还应以人口密度与年龄结构校核，避免指标达标而使用不便。"},{"h":"4. 空间与游线","t":"布局须与城市结构衔接，依托山水、道路与绿道组织游线，使公园与住区、学校、公交站点便捷联系。园内以主环路串联各功能区，次路深入景点，出入口与城市界面开放，边界以植物软化，提高可视性与进入意愿。"},{"h":"5. 管理参与","t":"管理环节应引入公众参与：规划阶段公示方案、听取居民意见；建设阶段鼓励社区共建；运营阶段发展志愿者与社区共治，明确养护责任。并建立使用后评价机制，依据使用强度与投诉调整设施，使公园从建成走向用好。"},{"h":"6. 案例与结论","t":"成都以天府绿道串联各级公园，形成绿道、公园与社区一体的网络；上海以口袋公园补足高密度城区的服务盲区；深圳推行社区公园共建共管。其共同经验是把布局、指标与治理统一起来，由有没有转向去得到、用得好。"}],"pit":"只答布局模式；不答数量、管理、参与。"},{"id":"344-b-24","title":"论述城市棕地景观再生设计的原则与策略并结合案例","type":"论述","category":"重点","score":15,"source":"2026","full":[{"h":"1. 概念与原则","t":"棕地指因工业、采矿等活动受损、存在污染或长期闲置的土地。再生设计遵循生态优先、最小干预、污染治理、文化记忆与公众参与五项原则：先治污后利用，尽量保留场地肌理与构筑物，使工业记忆成为景观资源。"},{"h":"2. 污染治理","t":"土壤修复依污染类型采用客土、固化稳定化、植物修复与微生物降解；水体治理以控源截污、生态驳岸、人工湿地与曝气增氧组合，重建水生态系统。治理须经检测验收后方可开放，并保留长期监测点位以跟踪风险。"},{"h":"3. 遗存利用","t":"工业遗存包括厂房、高炉、筒仓、铁轨与构筑物，宜以保留、改造、加建三种方式再利用：厂房转为展陈与剧场，筒仓改为观景塔，铁轨转为步道。新旧材料并置形成时间层次，避免仿古重建与全部拆除两种极端。"},{"h":"4. 空间与游憩","t":"空间组织以开放空间为骨架，用慢行系统串联节点，形成连续的公共领域。危险区设安全隔离与解说，低干扰区恢复植被，活动区植入运动、科普与休憩功能；边界以地形、植被与围栏处理，兼顾安全与景观连续。"},{"h":"5. 案例","t":"上海辰山植物园矿坑花园保留采石崖壁与深潭，以栈道、浮桥和瀑布组织游线，变创伤为景观；北京首钢园保留高炉与冷却塔，植入冬奥场馆与公共空间；成都东郊记忆以旧厂房群转型文创街区，延续工业记忆。"},{"h":"6. 评估与结论","t":"评估应覆盖生态、社会与经济效益：监测土壤水体、植被恢复与生物多样性，统计使用人数与满意度，核算改造投入与带动效益。棕地再生不是推平重建，而是修复与再生并重，使受损土地重新进入城市公共生活。"}],"pit":"只答“改公园”；不答污染治理、遗存利用、监测。"},{"id":"344-b-46","title":"论述中国古典园林的发展历程及各时期成就","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 生成期","t":"先秦至汉为生成期，以囿、台、苑为代表。帝王圈占山林川泽畜养禽兽，筑高台以观天象、通神明，后发展为宫苑。汉武帝建章宫开凿太液池、堆筑三山，形成一池三山格局，奠定皇家园林山水骨架的基本范式。"},{"h":"2. 转折期","t":"魏晋南北朝为转折期。社会动荡使文人寄情山水，隐逸思想与玄学、佛教盛行，私家园林与寺观园林兴起。造园由摹拟仙境转向再现自然山水，文人参与品评与设计，山水诗画开始与园林相互渗透。"},{"h":"3. 全盛期","t":"隋唐为全盛期。国力强盛、对外交流频繁，宫苑规模宏大，私家园林普及于官僚士大夫。长安、洛阳、扬州园林荟萃，诗画入园成为自觉追求，王维辋川别业以山水画意造园，写意倾向初步显现，影响深远。"},{"h":"4. 成熟期","t":"宋代为成熟期。城市经济繁荣，文人园林成为主流，叠山理水技艺精进；艮岳以土石结合、花石纲搜罗奇石，代表叠山艺术高峰。园林与诗、书、画、茶、香结合，意境营造趋于细腻，造园理论开始萌发。"},{"h":"5. 集大成","t":"明清为集大成期。皇家园林如颐和园、避暑山庄规模宏大、兼收并蓄；私家园林以苏州拙政园、留园为代表，布局自由、工艺精雅；寺观与风景名胜园林同步发展。计成《园冶》系统总结造园经验，标志理论成熟。"},{"h":"6. 结论","t":"总体看，中国古典园林经历了由模仿自然到写意自然、由皇家独占向文人私家普及、由经验积累到理论总结的演进。其成就集中于山水骨架的营造、建筑与自然的融合以及诗画意境的表达，形成独树一帜的写意体系。"}],"pit":"只罗列朝代；不答各期特征和成就。"},{"id":"344-b-47","title":"论述《园冶》的造园思想及其现代启示","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 地位与总纲","t":"《园冶》为明代计成所著，是我国第一部系统造园专著。其总纲为“虽由人作，宛自天开”，强调人工与自然相融、不见斧凿；又提出“巧于因借，精在体宜”，把顺应场地与恰当得体作为方法与评价标准。"},{"h":"2. 相地","t":"书中分山林、城市、村庄、郊野、江湖五类相地，主张先相地后立基，视场地高下、水源、植被与视线定布局。因高堆山、就低凿池，使园从场地中生长，反对不顾条件套用程式，这一思路与现代场地分析完全一致。"},{"h":"3. 因借","t":"因指沿用场地既有条件，借指收纳园外景物。借景因视点与时节而有远借、邻借、仰借、俯借、应时之借之别，把塔影山色与四季纳入园中；配合框景、对景、障景控制视线，在小空间中扩展景深，是精在体宜的具体落实。"},{"h":"4. 要素","t":"掇山、理水、建筑、植物、铺地各得其宜。掇山讲主次、皴法与洞壑，理水讲聚散与源流，建筑随宜布置以点景观景，植物取姿态与季相，铺地重纹样与材料。各要素服从整体立意，以意境统摄全局，不炫技、不堆砌。"},{"h":"5. 意境","t":"《园冶》强调诗画入园与文人审美，以景名、匾额、楹联点题，使景物承载情感与典故。意境不在繁复，而在以少胜多、以虚衬实，通过留白与联想使有限空间生出无穷意味，这是中国园林区别于西方园林的核心。"},{"h":"6. 现代启示","t":"其现代启示有四：尊重场地文脉的在地性设计；保护优先、最小干预的生态态度；以因借体宜组织空间与视线的设计方法；以意境营造提升公共空间的文化品质。对今天防止景观同质化与过度人工化仍有直接价值。"}],"pit":"只背口号；不答现代启示。"},{"id":"344-b-48","title":"论述中国、英国、法国古典园林的差异及文化根源","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"中国、英国、法国古典园林分别代表写意自然、如画自然与规则秩序三种传统。三者都以水、石、植物、建筑为要素，但因自然观、政治制度与审美理想不同，形成曲折幽深、开敞疏朗、轴线统摄三种空间性格。"},{"h":"2. 中国","t":"中国园林以天人合一为哲学基础，追求虽由人作、宛自天开。布局以山水为骨架，曲径通幽、欲露先藏，借景框景对景组织视线，建筑与诗画匾联共同点题。拙政园以水为中心，亭榭错落，体现文人写意与可游可居。"},{"h":"3. 英国","t":"英国自然风景园反对几何规则，追求如画风景。以缓坡草地、孤植树丛、蜿蜒水面为要素，点缀废墟、庙宇与岩洞，营造感伤怀旧的情调。肯特、布朗推动其成熟，斯托海德园以环湖游线组织画面，深受风景画与浪漫主义影响。"},{"h":"4. 法国","t":"法国古典主义园林以理性与王权为根基。凡尔赛宫苑以强烈中轴统摄全园并延伸至城市，花坛、道路、水池严格对称，运河与喷泉强化透视，植物修剪成几何形体。勒诺特把自然纳入秩序，以宏大尺度彰显君主权威。"},{"h":"5. 文化根源","t":"差异源于自然观与政治：中国以儒道禅与文人文化为本，重意境与隐逸；英国经验主义与浪漫主义盛行，尊重自然生成与个人情感；法国笛卡尔理性主义与中央集权结合，强调秩序与控制。地理条件亦影响尺度与要素选择。"},{"h":"6. 交流与结论","t":"十八世纪中国风影响英国自然风景园，丘园建中国塔即为明证；法国规则式园林则随近代化影响各国。三者本质是三种自然观：中国写意、英国如画、法国秩序，共同构成世界园林体系的多元图景，无高下之分。"}],"pit":"只答形式；不答文化根源。"},{"id":"344-b-49","title":"论述公园城市理论内涵与成都实践","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 内涵","t":"公园城市不是城市加公园，而是把公园形态与城市功能有机融合，实现人、城、境、业统一。以人民为中心，以生态为基底，以公园体系与绿道网络为骨架，把生态价值转化为生活品质与发展动能，形成城园相融的空间格局。"},{"h":"2. 价值","t":"其价值体现在生态、美学、经济、生活与文化五方面：修复生态网络、提升环境容量；塑造城景相融的风貌；带动生态旅游与文创等新经济；提供可达的休闲交往场所；延续地域文脉、增强认同。价值转化是关键环节。"},{"h":"3. 路径","t":"实现路径包括构建分级公园体系、连通区域绿道网络、营造多元生活场景、创新社区治理。规划上以蓝绿空间为底、组团式布局；建设上增补口袋公园与金角银边；运营上引入市场与社会力量，使公园成为日常生活的组织者。"},{"h":"4. 成都实践","t":"成都以天府绿道为骨架，建设锦城绿道、锦江绿道与区域绿道，串联各级公园与社区；推进公园城市示范区、未来社区与川西林盘保护，把绿道变为通勤、休闲与消费的复合空间，形成绿道加公园加场景的实践模式。"},{"h":"5. 挑战","t":"实践中仍存在指标与品质不匹配、重建设轻运营、空间分布不均、生态保护压力大等问题。部分绿道使用率不高，维护成本与资金平衡困难，需以使用后评价校正布局，以社区参与降低运维压力，以红线管控守住生态底线。"},{"h":"6. 结论","t":"公园城市的核心是从在城市中建公园转向在公园中建城市，把生态优势转化为发展优势与生活品质。其成败不取决于公园数量，而取决于体系是否连通、场景是否可用、治理是否持续，这也是对风景园林综合能力的检验。"}],"pit":"只答“多建公园”；不答价值转化、治理。"},{"id":"344-b-50","title":"论述城市绿地系统规划的层次与内容","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"城市绿地系统规划按市域、城区、分区、详细四个层次逐级深化，上级定结构，下级定用地，形成层级衔接、指标落地的体系。各层次内容侧重不同，但都围绕生态网络、绿地布局、指标控制与实施管理展开。"},{"h":"2. 市域层次","t":"市域层次侧重生态网络与区域协调，划定生态保护红线与各类保护区，统筹风景名胜、森林公园、湿地与区域绿地，布局绿道与生态廊道，控制城镇开发边界，构建山水林田湖城一体的格局，为下层提供约束条件。"},{"h":"3. 城区层次","t":"城区层次确定绿地结构、总量指标与布局形态，明确绿地率、人均公园绿地面积、公园绿地服务半径覆盖率等指标，按点线面结合组织各级绿地，衔接城市功能分区与交通骨架，解决分布不均与服务盲区问题。"},{"h":"4. 分区层次","t":"分区层次落实各类绿地的定位、规模与范围，包括公园绿地、防护绿地、广场用地、附属绿地与区域绿地，明确服务半径与建设标准，处理与其他用地的边界关系，为控制性详细规划提供用地依据与控制要求。"},{"h":"5. 详细与专项","t":"详细层次确定地块边界、出入口、竖向、设施与植物配置，直接指导方案设计。专项规划涵盖绿道、树种、防灾避险、生物多样性与古树名木保护，是把系统意图落到空间与工程的关键环节，不可缺项。"},{"h":"6. 实施与结论","t":"实施层面需与国土空间规划、控规衔接，落实用地与资金，分期建设并建立动态维护与评估机制。成都以天府绿道串联市域与城区绿地，上海以分级公园体系补足服务盲区，均体现了层级衔接与指标落地的要求。"}],"pit":"层次不清；只答指标。"},{"id":"344-b-51","title":"论述以国家公园为主体的自然保护地体系","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 体系构成","t":"自然保护地体系以国家公园为主体、自然保护区为基础、自然公园为补充。三者按保护对象和保护强度分工，统一设置、分级管理，形成覆盖典型生态系统和自然遗迹的完整网络，是国土生态安全的空间载体。"},{"h":"2. 改革背景","t":"过去保护地破碎化、一地多牌、多头管理，保护与发展矛盾突出，交叉重叠和历史遗留问题不少。改革后统一设置、分级行使、分区管控，把分散的各类保护地整合成一套体系，实现从抢救性保护到系统性保护的转变。"},{"h":"3. 国家公园","t":"国家公园是体系主体，保护大面积、原真性、完整性的大尺度自然生态系统，由国家批准设立、中央直接管理。大熊猫国家公园跨川陕甘三省，把分散栖息地连成整体，是旗舰案例。"},{"h":"4. 保护区与自然公园","t":"自然保护区保护典型生态系统和珍稀物种，实行严格管理，禁止随意开发；自然公园保护自然遗迹和风景资源，可适度开展科普与游憩。二者一严一活，补上国家公园之外的空白，体系才完整。"},{"h":"5. 分区与管控","t":"国家公园分核心保护区和一般控制区：核心区原则上禁止人为活动，只留监测和科研；一般控制区限制开发强度，可开展有限游憩。配套生态保护红线、差别化管控和特许经营，把强度真正管住。"},{"h":"6. 社区共管","t":"原住民生计是保护难点。以生态补偿、公益岗位、特许经营让居民受益，推行社区共管、共建协议，把保护从“赶人”变成“共管”，矛盾少了，体系才能长期稳定运行，红线也才守得住，保护才有社会基础。"}],"pit":"只答“建国家公园”；不答分区、管控。"},{"id":"344-b-52","title":"论述乡村振兴中风景园林的介入路径","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 问题判断","t":"乡村普遍空心化、老龄化、风貌同质、生态退化、设施不足，照搬城市做法往往越做越假。风景园林介入不是“涂脂抹粉”，而是以空间整治带动生态、产业和治理，先看清问题再动手，不能上来就画广场，先弄明白谁来用、用多久。"},{"h":"2. 修复生态基底","t":"先修生态：保护山林、修复水系、整治垃圾和污水，恢复田、林、水、宅的关系。川西林盘是林、田、水、宅一体的乡土生态单元，整治时要保住林盘肌理和水系格局，不能一味拆并上楼，保住林盘才有民宿和研学的底子。"},{"h":"3. 乡土景观","t":"景观用本地材料、本地树种，保留老树、晒坝、井台、石阶和原有巷道走向。避免把城市广场、彩色铺装、大树进城那套搬进村，风貌同质正是这样来的，钱花了还丢了乡愁，用旧料、旧工法反而更省钱。"},{"h":"4. 公共空间","t":"村口、祠堂前、晒场是乡村的公共客厅。整理这些节点，加座椅、遮阴、照明和小舞台，既方便村民日常交往、办红白事，也能承接游客停留，投入不大而见效快，是介入的首选切口，白天老人用、傍晚孩子用。"},{"h":"5. 产业融入","t":"用绿道把田园、果园、民宿、研学点串起来，观光农业和民宿才有客流，农产品才有销路。风景变成可消费的场景，村民才有维护动力，否则建成即荒废，只剩一次性的形象工程，产业收益要能反哺养护投入。"},{"h":"6. 共同缔造","t":"设计、施工、维护都要村民参与：先议事再画图，用本地工匠，留出自建和菜园的空间。设计师做协调者而非主导者，成果才留得住，才能从“美化”转向“产业+生态+治理”的长效路径，一次建设、长期共管。"}],"pit":"只答“画墙”；不答产业、治理。"},{"id":"344-b-53","title":"论述数字技术对风景园林的影响","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总体判断","t":"数字技术改变了风景园林的全流程：调查靠数据、设计靠模型、施工靠扫描、管理靠平台。它提高了效率和精度，也带来新问题，但技术始终是工具，核心仍是人的空间和场地的真实条件，数据不会自己提出问题。"},{"h":"2. 调查与规划","t":"GIS、遥感和手机信令大数据可叠加地形、生态、交通、人群热力，做适宜性评价、选址和容量测算。过去靠经验判断，现在能算清楚，规划依据更硬，也便于事后校核和动态调整，避免拍脑袋选址、凭感觉定规模。"},{"h":"3. 设计与推敲","t":"BIM 建三维模型，参数化调地形、坡度和种植，VR、AR 让人戴上头显看空间和视线。方案可以反复比较，甲方和公众提前看见效果，减少施工阶段的返工和变更，也方便多专业协同，但建模不等于设计本身。"},{"h":"4. 施工与建造","t":"无人机航测、三维扫描和智慧工地用于土方平衡、进度与质量管控。地形复杂或改造项目，扫描比对能及时发现问题，减少返工、材料浪费和工期延误，隐蔽工程也有据可查，验收和结算也少了扯皮。"},{"h":"5. 运营管理","t":"智慧公园接入客流监测、土壤湿度、灌溉和养护巡检，按需浇水施肥，节水节能。养护从定期改为按需，人力用在该用的地方，管理从经验走向台账，长期成本反而下降，但设备更新也要算进去。"},{"h":"6. 公众参与与风险","t":"可视化平台和互动小程序降低了参与门槛，居民能标问题、投票选方案、跟踪进度。但要警惕技术炫技、数据伦理和“模型好看落地难”，技术不能替代价值判断和现场经验，也要防止数字鸿沟和隐私泄露。"}],"pit":"只列技术；不答应用场景和风险。"},{"id":"344-b-54","title":"论述城市更新背景下口袋公园的设计策略","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 背景定位","t":"城市进入存量更新，大块绿地难找，口袋公园利用边角地补服务盲区。它不是缩小版综合公园，而是高频率、短停留的日常空间，讲究就近、好用、待得住，几十平方米也要能用，方寸之地也要有坐处、有树荫。"},{"h":"2. 选址补盲","t":"优先边角地、闲置地、桥下空间、街角，按服务半径找盲区，步行五到十分钟可达。成都“金角银边”就是把街角空地改成口袋公园，补的是老城最缺的那一块，成本低、见效快，选址往往比设计更决定成败。"},{"h":"3. 空间处理","t":"小尺度要通透、可达、少拆少建，用微更新代替大动土。边界打开、视线能看见里面，人才敢进；无障碍、照明、排水要一次做到位，避免反复开挖，把有限的钱花在看得见的地方，微更新不是不设计，而是精准设计。"},{"h":"4. 功能配置","t":"按人群和时段配置：老人晨练要平整场地和树荫，儿童放学要沙坑和看护座椅，上班族午休要安静角落。动静分区、错时使用，休憩、交往、健身都能找到位置，不必贪多求全，设施宁可少而耐用，不要多而难养。"},{"h":"5. 植物设施","t":"选乡土、耐荫、低维护、有季相的植物，少用大草坪和时令花坛。座椅、遮阴、照明、直饮水、垃圾桶按使用强度配置，数量要够，位置比造型重要，维护成本要在设计时就想到，养护跟不上就迅速衰败。"},{"h":"6. 治理机制","t":"设计阶段就请社区参与，建成后共建共管，定期做使用后评价。上海的口袋公园由街镇养护、居民认领，比一次性建成、无人管理更管用，也更省钱，还能减少破坏，共管协议要写清责任和经费。"}],"pit":"只答“小公园”；不答选址、治理。"},{"id":"344-b-55","title":"论述低碳园林的内涵与实现路径","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 内涵界定","t":"低碳园林是在全生命周期内低能耗、低排放、高碳汇、低维护的园林。算碳要覆盖规划、材料、建造、养护到拆除，不能只看种了多少树，也不能只算建设期，养护期往往才是大头，建设期的土方一次就抵几十年碳汇。"},{"h":"2. 规划布局","t":"布局紧凑，保留现状大树、水体和地形，减少土方和外运。近自然、少硬化，让绿地自己形成小气候，从源头减碳，比后期加设备更划算，也少了一笔运行电费，避免大填大挖破坏原有水文和表土。"},{"h":"3. 材料选择","t":"用乡土石材、再生砖、木竹等低碳材料，就地取材减少运输。少用水泥、钢材和异型构件，这些材料的隐含碳最高，拆改时又变成建筑垃圾，全生命周期算下来最不划算，运输距离本身就是碳成本。"},{"h":"4. 植物碳汇","t":"乔灌草复层种植，以大冠幅乔木为主，碳汇高、遮阴好、降温明显。少种大草坪、少修剪、少施肥，草坪和时令花卉的养护碳排放其实很高，观赏期却短，性价比低，落叶就地还田比清运更省碳。"},{"h":"5. 运维管理","t":"雨水收集回用、太阳能照明、枝叶堆肥还田，养护按需而非定期。低维护不是不维护，而是把水、肥、人力用在关键处，减少无谓的重复投入，也让养护单位养得起，设备选型不只看初投资。"},{"h":"6. 案例与误区","t":"成都低碳社区用透水铺装和雨水花园，兼顾减排与景观。常见误区是把低碳等同于多植树，忽视材料、土方和长期养护的排放，结果账越算越亏，指标好看而碳没减，低碳要能算得清、看得见。"}],"pit":"只答“种树”；不答材料、运维。"},{"id":"344-b-56","title":"论述世界园林三大体系及交流","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 三大体系","t":"世界园林大致分中国、西亚、欧洲三大体系，分别对应东亚、伊斯兰和基督教文化圈。划分依据是自然观、水法与几何秩序的不同取向，而不只是看形式，背后是宗教和哲学，地理和气候是更深的底子。"},{"h":"2. 中国体系","t":"中国园林本于自然、高于自然，诗画入园，重意境。拙政园以水为中心，借景、框景、曲径并用，追求可游可居的写意山水，是文人审美的集中体现，也是东方自然观的样本，一园之内可游、可居、可赏。"},{"h":"3. 西亚体系","t":"西亚干旱少水，园林以水为贵：十字水渠、几何花坛、围墙遮阴、浓香植物。阿尔罕布拉宫的庭院就靠水的声与影营造清凉，是“水、荫、香”的典型，也是干旱区的生存智慧，水法也是教义的空间表达。"},{"h":"4. 欧洲体系","t":"欧洲从古希腊罗马庭院，到意大利台地园，到法国规则式，再到英国自然风景园。凡尔赛以中轴和运河体现王权，斯托海德以如画风景反规则，一路都在变，变的是自然观，英国转向如画与浪漫。"},{"h":"5. 交流互鉴","t":"交流一直存在：中国风在18世纪影响英国自然风景园，丘园建了中国塔；近代欧洲规则式又随租界公园传入中国，改变了城市公园的面貌和造园观念，交流从来是双向的，今天的生态设计仍在互相借用。"},{"h":"6. 结论","t":"三大体系多元并存、相互影响，交流多经贸易、传教、旅行和画册传播。今天做设计，既要懂源流、识谱系，也要避免符号拼贴和假古董，从传统中取方法而非取样式，交流的前提是先认清自己的谱系。"}],"pit":"只答中国；不答三大体系。"},{"id":"344-b-57","title":"论述风景园林学科的内涵与人居环境科学的关系","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 学科内涵","t":"风景园林是保护、规划、设计、管理室外境域的学科，核心是人与自然在土地上的关系。从国土到庭院，凡室外空间都在其视野之内，既管保护也管营造，兼具科学、艺术与工程，不是单纯的绿化美化。"},{"h":"2. 人居环境科学","t":"吴良镛提出人居环境科学，以自然、人、社会、建筑、网络五要素，分全球、区域、城市、社区、建筑五层次，研究聚居环境的建设规律，强调系统综合，反对单打一，核心是协调人与聚居环境的关系。"},{"h":"3. 三大学科","t":"建筑、城市规划、风景园林是人居环境科学的三大支柱：建筑管单体，规划管布局，风景园林管室外境域，三者并列而非从属，缺一不可，共同支撑聚居环境的质量，共同回答聚落如何建设。"},{"h":"4. 绿色基础","t":"风景园林为人居环境提供生态基底、游憩空间和景观品质。绿地系统、绿道、公园是城市的自然骨架，也是人居环境质量最直观的体现，还是公共健康的基础设施，也是城市韧性的组成部分。"},{"h":"5. 相互支撑","t":"人居环境科学给风景园林尺度观和问题导向，避免只做场地美化；风景园林的实践又反馈到区域生态和城市结构，充实人居理论，两者互相支撑，不是谁包含谁，尺度越大越需要理论支撑。"},{"h":"6. 实践与结论","t":"实践覆盖国土、区域、城市、社区、场地五个尺度，如公园城市、乡村振兴、社区微更新。风景园林是综合、问题导向的学科，不能简化成种树造园，也不能只谈形式美学，更不是图纸上的构图游戏。"}],"pit":"只答“种树造园”；不答学科体系。"},{"id":"344-b-25","title":"热点 1　公园城市（最高频，建议整篇背）","type":"综合","category":"重点","score":35,"source":"2026热点","full":[{"h":"1. 政策由来","t":"2018 年 2 月视察天府新区提出“突出公园城市特点”；同年首都义务植树提出“整个城市就是一个大公园”；2020 年 1 月中央财经委第六次会议明确支持成都建设践行新发展理念的公园城市示范区。"},{"h":"2. 概念","t":"把城乡绿地系统和公园体系、公园化的城乡生态格局与风貌作为城乡发展的基础性、前置性配置要素，把“市民—公园—城市”三者关系的优化和谐作为创造美好生活的重要内容，通过提供更多优质生态产品满足人民需求的新型人居环境建设理念与理想城市建构模式（人城境业和谐统一）。"},{"h":"3. 城市背景","t":"生态退化严重、生态产品供给不足、自然文化风貌减弱、城乡二元结构明显、发展模式亟待升级。"},{"h":"4. 五大特征","t":"以人为本共享发展、生态筑基绿色发展、城乡并举协调发展、美丽引领创新发展、多元共生开放发展。"},{"h":"5. 概念辨析","t":"田园城市（霍华德《明日的田园城市》，兼有城乡优点的理想城）；园林城市（按国家园林城市标准评出）；森林城市（以森林植被为主体、城乡一体）；生态园林城市（园林城市的升级版）；公园城市是生态文明时代的升级版，强调公共产品属性与人城境业统一。"},{"h":"6. 建设方法","t":"基底塑造（天人合一，用山水林田格局构建生态基底）—空间构建（以绿色基底约束城市形态）—设施与产业（文化创新、业态升级）—人居环境（城在园中建、人在城中居）。"},{"h":"7. 成都五大着力点","t":"创新（产业生态圈创新生态链）、协调（以水定人、以底定城、以能定业、以气定形，增存并重国土空间规划）、绿色（全域增绿增景）、开放（成渝双城经济圈、全球资源）、共享（治理体系现代化）。"},{"h":"8. 意义","t":"优化城乡关系、完善城市格局、提升城市风貌与竞争力、满足美好生活需要；根本目的是实现城市与自然和谐共生。"}],"pit":""},{"id":"344-b-26","title":"热点 2　城市双修与城市荒野","type":"综合","category":"重点","score":35,"source":"2026热点","full":[{"h":"1. 政策","t":"2015 年中央城市工作会议提出“加强城市设计，提倡城市修补”“大力开展生态修复，让城市再现绿水青山”；2017 年住建部《关于加强生态修复、城市修补工作的指导意见》把生态修复分为山体修复、水体治理、修复利用废弃地、完善绿地系统四方面。"},{"h":"2. 概念","t":"生态修复——用再生的理念修复城市中被破坏的自然环境和地形地貌、改善生态环境质量；城市修补——用更新织补的理念拆除违章建筑、修复城市设施与空间环境、景观风貌，提升城市特色和活力。"},{"h":"3. 内容","t":"生态修复四项（山体、水体、废弃地、绿地系统）；城市修补五项（填补基础设施、增加公共空间、改善出行条件、改造老旧小区、保护塑造历史文化与时代风貌）。"},{"h":"4. 意义","t":"恢复生态网络系统、重塑人工与自然平衡；催化调整城市产业人口空间结构、转变增长模式；尊重传承历史文化、彰显城市精神；遵循以人为本公众参与、完善法规与监督机制。"},{"h":"5. 城市荒野概念","t":"城市中残留的自然保护地、修复过的自然生态系统、废弃荒地以及人工设计的荒野景观；最突出特征是处于人类活动密集区却不受或较少受人类干预、保留自然原貌并发生自然演替。"},{"h":"6. 荒野特征与营造","t":"自然过程主导、具野性无序表征、有野生动植物保育与稀缺自然体验功能；营造三模式——移植（片段转移）、模拟（建完整可循环生态系统）、放任（最低干预、动态营造）。"},{"h":"7. 风景园林落点","t":"绿地系统是双修载体，棕地/废弃地再生是抓手，口袋公园与老旧小区微更新是修补手段。"}],"pit":""},{"id":"344-b-27","title":"热点 3　雨洪管理（海绵城市·雨水花园·绿色基础设施·弹性城市）","type":"综合","category":"重点","score":35,"source":"2026热点","full":[{"h":"1. 海绵城市","t":"城市像海绵一样，在适应环境变化和应对自然灾害等方面具有良好弹性，下雨时吸水、蓄水、渗水、净水，需要时将蓄存水释放利用；建设遵循生态优先，自然途径与人工措施结合，在确保排水防涝安全前提下最大限度实现雨水积存、渗透和净化。"},{"h":"2. 六字诀与设施","t":"渗（透水铺装、屋面地面）、滞（植草沟、植被缓冲带、微地形）、蓄（下沉式绿地）、净（土壤渗透与植物水体净化）、用（景观用水、洗车、冲厕）、排（竖向与管网、超标雨水排放）；目标 70% 降雨就地消纳。"},{"h":"3. 雨水花园","t":"自然形成或人工挖掘的浅凹绿地，用于汇聚吸收屋顶或地面雨水，通过植物、土壤综合作用净化并渗入土壤、涵养地下水，或补给景观用水与中水；五部分——蓄水层、覆盖层、种植土层、人工填料层、砾石层。"},{"h":"4. 雨水花园功能","t":"削减洪峰与外排、净化雨水减少污染、涵养地下水与回用、为鸟类昆虫提供食源栖息地。"},{"h":"5. 绿色基础设施","t":"由绿道、湿地、雨水花园、林地等开放空间与自然区域及其连接网络组成，是控制径流、减少洪涝、保护水环境的主要供给者；水质调节分物理（沉降、过滤、挥发）、化学（吸附、絮凝、沉淀、光解）、生物（植物藻类摄取）三过程。"},{"h":"6. 弹性城市","t":"系统能较快恢复到原有状态并保持系统结构和功能的能力；建设路径是识别内外压力冲击、模拟可能的伤害、调整优化建设策略。"},{"h":"7. 绿地设计落点","t":"竖向与下凹、透水铺装、雨水湿地与湿塘、耐淹植物选择（如大花萱草）、与管网衔接的溢流口。"}],"pit":""},{"id":"344-b-28","title":"热点 4　疫情与康复景观","type":"综合","category":"重点","score":35,"source":"2026热点","full":[{"h":"1. 应对传染病的四点作用","t":"天人合一的自然观有利于荒野与自然原真性保护、避免病原暴露；绿色基础设施提供洁净空气与水等生态服务；城乡绿地格局形成通风廊道；康养花园与园艺疗法助隔离与康复。"},{"h":"2. 疫情期功能","t":"接触绿色环境快速舒缓压力；公园是抵御灾害、疏散避难与临时安置的场所；空间开敞易于保持安全距离。"},{"h":"3. 非疫情期功能","t":"滞尘降噪、改善温湿与热舒适；吸引中等强度锻炼；恢复主动注意力、缓解精神疲劳；创造户外交往、形成社会纽带；公共健康可转化为经济效益与新兴服务业。"},{"h":"4. 康复性景观","t":"指与治疗或康复相关的物质、心理和社会的环境所包含的场所，以使身体、精神与心灵康复而闻名。"},{"h":"5. 康养植物选择四原则","t":"①安全——无毒无刺不易过敏，病房周围避免飞絮植物（柳、杨、悬铃木），选能杀菌驱虫的松、柏、杉、香樟、核桃；②按保健功效四类配置——杀菌消毒、提神醒脑、通经活络、润肺养心；③可选可食植物（樱桃、山楂、柿、无花果）；④提高三维绿量以增加空气负离子。"},{"h":"6. 规划启示","t":"社区级绿地与 15 分钟生活圈优先；把健康绩效纳入绿地评价；平灾结合配置避难与康养功能。"}],"pit":""},{"id":"344-b-29","title":"热点 5　“双碳”与低碳园林（2026 已考简答）","type":"综合","category":"重点","score":35,"source":"2026热点","full":[{"h":"1. 概念与承诺","t":"碳达峰——2030 年前二氧化碳排放不再增长、达峰后逐步下降；碳中和——企业团体或个人在一定时间内直接或间接产生的温室气体排放总量，通过植树造林、节能减排等形式抵消，实现二氧化碳“零排放”，我国力争 2060 年前实现。"},{"h":"2. 政策五方面目标","t":"构建绿色低碳循环发展的经济体系、提升能源利用效率、提高非化石能源消费比重、降低二氧化碳排放水平、提升生态系统碳汇能力。"},{"h":"3. 响应两条线","t":"一方面提高绿地碳汇效益，另一方面认清园林建设本身是人工工程、要在设计与施工中减排。"},{"h":"4. 固碳群落配置","t":"选高固碳树种（竹类、榆、柳、松柏、悬铃木、香樟、桂花、石楠、紫薇、红豆杉等）；单位面积固碳能力常绿灌木＞落叶乔木＞常绿乔木＞落叶灌木，宜落叶乔木＋常绿灌木搭配；幼龄植株吸收强、老龄植株储存稳，宜老幼结合；速生与慢生搭配、加入彩叶、优先乡土树种。"},{"h":"5. 低碳园林六条","t":"选碳友好低维护材料；用太阳能风能生物能与 LED；配置固碳植物组群；妥善处置并再利用建设废弃物；延长园林使用年限；发挥低碳教育展示功能。"},{"h":"6. 节约型园林六节约","t":"节约用地（屋顶花园、墙面绿化等立体绿化）、节约用土（土方就地平衡、表土回填）、节约用水（雨水与中水回用、耐旱植物、减少输水损失）、节约能源（可再生能源、反光荧光材料小品）、节约材料（循环利用）、节约型植物设计（多层次多结构多功能近自然群落）。"}],"pit":""},{"id":"344-b-30","title":"热点 6　国家公园与自然保护地体系","type":"综合","category":"重点","score":35,"source":"2026热点","full":[{"h":"1. 自然保护地概念","t":"由各级政府依法划定或确认，对重要的自然生态系统、自然遗迹、自然景观及其所承载的自然资源、生态功能和文化价值实施长期保护的陆域或海域；是生态建设核心载体，包括国家公园、自然保护区、自然公园三大类。"},{"h":"2. 国家公园概念","t":"以保护具有国家代表性的自然生态系统为主要目的，实现自然资源科学保护和合理利用的特定陆域或海域；是我国自然生态系统最重要、自然景观最独特、自然遗产最精华、生物多样性最富集的部分。"},{"h":"3. 内涵","t":"坚持生态保护第一（原真性、完整性、世代传承）；明确国家代表性定位（纳入生态保护红线、最严格保护，兼具科研教育游憩功能）；确定空间布局与设立标准；优化完善以国家公园为主体的自然保护地体系。"},{"h":"4. 意义","t":"把最该保护的地方完整留给子孙后代；储备地球自然场域、保护生物多样性与可持续利用自然资源；推动生态文明与绿色发展，关系每个公民利益。"},{"h":"5. 十处试点","t":"三江源、大熊猫、东北虎豹、湖北神农架、浙江钱江源、湖南南山、福建武夷山、北京长城、海南热带雨林、云南普达措。"},{"h":"6. 与风景园林的关系","t":"风景名胜区纳入自然公园管理；保护与游憩平衡、分区管控（核心保护区禁止人为活动）；社区共建、生态产品价值实现。"}],"pit":""},{"id":"344-b-31","title":"热点 7　乡村景观·川西林盘·乡村振兴（2026 综合题方向）","type":"综合","category":"重点","score":35,"source":"2026热点","full":[{"h":"1. 总要求","t":"产业兴旺、生态宜居、乡风文明、治理有效、生活富裕。"},{"h":"2. 川西林盘","t":"成都平原特有的乡村聚落形态，由林、田、水、宅等要素组成，宅院隐于竹林林木之中；是生产、生活、生态、景观四位一体的复合系统，也是公园城市乡村表达的载体与地方素材。"},{"h":"3. 现状问题","t":"格局破碎（林盘被侵占）、风貌同质、设施欠账、产业单一、人口外流。"},{"h":"4. 介入路径","t":"本底保护（林盘肌理、水系、农田格局）—公共空间微更新（村口、晒场、塘堰）—乡土材料与植物（竹、川西乡土树种）—产业与游线（农文旅、绿道串联）。"},{"h":"5. 与公园城市的关系","t":"城乡并举、协调发展，用公园化手法表达乡村价值，而非把乡村做成城市公园。"}],"pit":""},{"id":"344-b-32","title":"热点 8　数字景观与国土空间规划（了解级，可作辨析素材）","type":"综合","category":"重点","score":35,"source":"2026热点","full":[{"h":"1. 数字景观/智慧园林","t":"以 GIS、BIM、参数化设计与数字孪生支持场地分析、方案比选、施工与养护监测，提高精度与效率，但不能替代对场地自然过程的判断。"},{"h":"2. 国土空间规划","t":"五级三类四体系，“三区三线”（生态、农业、城镇空间；生态保护红线、永久基本农田、城镇开发边界），双评价（资源环境承载能力与国土空间开发适宜性）。"},{"h":"3. 风景园林角色","t":"绿地系统专项规划纳入国土空间规划体系，城市绿线与生态保护红线衔接，绿道网络承担区域连通功能。"}],"pit":""},{"id":"344-b-33","title":"试述风景园林与乡村振兴结合的意义和具体措施，并结合实际案例加以说明。（2026 真题 · 综合题 35 分）","type":"综合","category":"重点","score":35,"source":"2026综合","full":[{"h":"1. 意义","t":"为什么要结合·修复生态本底：乡村是区域生态安全的基底。风景园林以山水林田湖草系统治理的思路修复受损山体、水系、林盘与土壤，把碎片化生态斑块重新连成网络，既改善人居环境，也为城市提供生态屏障。"},{"h":"2. 意义","t":"为什么要结合·提升人居环境：通过村口、晒坝、村道、水塘、小微绿地整治，解决农村公共空间缺失、设施落后、雨天泥泞的问题。这是村民最容易感知的获得感，也是“生态宜居”要求的落地抓手。"},{"h":"3. 意义","t":"为什么要结合·转化产业价值：田园景观化、农业景观化，把稻田、果园、林盘、竹林变成可观赏、可体验、可消费的场景，支撑休闲农业、乡村旅游、康养与文创，让风景变成收益，实现生态价值的市场化转化。"},{"h":"4. 意义","t":"为什么要结合·传承地域文化：聚落形态、川西林盘院落、祠堂、堰塘、古树与农耕习俗是地域文化的载体。风景园林通过保护性更新而非推倒重建，把文化记忆留在原址，避免千村一面。"},{"h":"5. 意义","t":"为什么要结合·支撑治理与人才：共同缔造、村民参与、以奖代补等机制，使规划从替村民做转为和村民一起做，同时培育乡村工匠与管护队伍，形成长效运维能力。"},{"h":"6. 具体措施","t":"怎么做·规划先行、多规合一：在县域村庄分类基础上编制实用性村庄规划，先划生态保护红线、永久基本农田与建设用地边界，再落绿地系统、公共空间与游线，做到不占田、不填塘、不砍树。"},{"h":"7. 具体措施","t":"怎么做·生态修复优先：治理面源污染与小微黑臭水体，恢复塘堰沟渠的生态驳岸与净化功能；保护修复川西林盘，维持林—田—宅—水的复合结构；用乡土植物重建近自然群落，提高抗逆性与自维护能力。"},{"h":"8. 具体措施","t":"怎么做·公共空间织补：以村口、村委会前广场、晒坝、水塘边、古树下为节点建小微公园与活动场地，用绿道和田间路把节点串成线，形成节点—廊道—片区的乡村公共空间体系，满足老人休憩、儿童活动与节庆集会。"},{"h":"9. 具体措施","t":"怎么做·产业景观化设计：不改变农用地性质的前提下，用田埂、水渠、林网、观景平台组织农业景观，配套停车、驿站、卫生设施与标识系统，使农业空间兼有生产、观光与科普功能，避免把乡村公园化、城市化。"},{"h":"10. 具体措施","t":"怎么做·乡土材料与低维护：使用竹、木、石、夯土、青瓦等本地材料，采用低技术低造价工法；植物以乡土种为主，减少大草坪与时令花坛，把养护成本控制在村集体可承受范围内。"},{"h":"11. 具体措施","t":"怎么做·机制与运维：推行共同缔造：规划阶段入户访谈与方案公示，建设阶段村民投工投劳，建成后由村集体加村民认领管护；建立以奖代补与后期管护经费，避免建得起、养不起。"},{"h":"12. 案例","t":"成都实践·川西林盘保护修复：成都以林盘+为抓手，对都江堰、崇州、郫都、蒲江的林盘分类保护：保留院落肌理与竹木林盘，整治院落环境与污水，植入民宿、书院、手工作坊。林盘从空心化的旧院落变成可游可住的空间，既守住川西田园形态，又带来经营收益。"},{"h":"13. 案例","t":"成都实践·崇州白头镇五星村：以稻田景观为本底，整治沟渠与林盘，配套绿道、驿站与观景平台，发展休闲农业与乡村旅游，形成农业加景观加社区的复合，村民通过经营与就业分享收益。"},{"h":"14. 案例","t":"成都实践·蒲江明月村：以陶艺文创为核心，保留原有村落格局与民居，改造闲置院落为工作室与展陈空间，配套竹林步道与环境整治。要点是轻介入、重内容，用文化内容激活空间，而非大拆大建。"},{"h":"15. 案例","t":"成都实践·郫都战旗村：以集体经济组织为平台，整治村庄环境、建设公共空间与田园景观，把景观提升与产业经营绑定，形成可分配收益机制，解决谁来建、谁来养的问题。"},{"h":"16. 结论与易错点·结论","t":"两者结合的本质，是把生态修复、空间整治、文化保护与产业经营放在同一系统里统筹：以规划定边界，以修复保本底，以空间聚人气，以产业养活空间，以机制保长效。风景园林提供的是空间组织与环境品质的专业能力，而非单纯的画图种树。"},{"h":"17. 结论与易错点·易错点","t":"①只答景观美化，不答产业、治理与机制，得分上不去；②把乡村当城市公园做，大广场、大草坪、大硬质铺装，破坏田园肌理；③只答理念不答案例，综合题必须落到具体项目；④忽略用地性质与农民主体地位，措施无法实施。"}],"pit":""}]},"857":{"terms":[{"id":"857-t-1","subject":"857","term":"生态因子","answer":"★★  第章  ①定义：构成环境的各个要素中，能对生物生长发育和分布有直接或间接影响作用的因子。②要点：分为气候因子、土壤因子、地形因子、生物因子、人为因子。③落点：任一因子超出耐受范围即成限制因子。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-2","subject":"857","term":"光补偿点","answer":"★★  第章  ①定义：在低光照条件下，植物光合作用较弱，当光合作用产物恰好与呼吸作用消耗相等时，此时的光照强度称为光补偿点。②要点：植物在光补偿点时不能积累干物质，因此可以作为判断植物在低光照度条件下能否生长的标志。③落点：耐阴性判据，据此选林下植物。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-3","subject":"857","term":"乡土植物","answer":"★★★  第章  ①定义：长期自然分布于本地、与当地气候和土壤条件高度适应、抗逆性强、养护成本低的植物种类。③落点：作绿地骨干树种。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-4","subject":"857","term":"生态型","answer":"★★  第章  ①定义：同一物种的不同个体或群体，长期生存在不同生态环境条件下发生趋异适应，遗传分化后形成的形态、生理和生态特性不同的基因型类群。③落点：引种选同一生态型。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-5","subject":"857","term":"光周期现象","answer":"★★  第章  ①定义：植物的生长发育对日照长度规律性变化的反应称为光周期现象。②要点：长日照植物：指日照长度超过某一数值才能开花的植物，当日照长度不够时，只进行营养生长，不能形成花芽。短日照植物：指日照长度短于某一数值才能开花的植物，通常需要8~12h日照中日照植物：指花芽形成需经中等日照时间的植物。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-6","subject":"857","term":"生态幅","answer":"★★  第章  ①定义：每个物种对每一种生态因子都有耐受范围的上限和下限，上下限之间就是生物对这种生态因子的耐受范围。②要点：每个物种对生态因子适应范围的大小称为生态幅。③落点：广生态幅种易栽培。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-7","subject":"857","term":"趋异适应","answer":"★★★  第章  ①定义：同种生物在不同环境条件下，为适应各自环境而分化出不同形态、生理或行为特征的现象。③落点：结果是形成生态型。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-8","subject":"857","term":"春化作用","answer":"★★  第章  ①定义：某些植物在花芽分化前必须经历一定时间的低温处理才能开花的现象，是温度对植物发育的典型影响。③落点：二年生花卉需越冬低温。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-9","subject":"857","term":"植物修复","answer":"★★  第章  ①定义：是利用绿色植物来转移、容纳或转化污染物使其对环境无害。②要点：植物修复的对象是重金属、有机物或放射性元素污染的土壤及水体。研究表明，通过植物的吸收、挥发、根滤、降解、稳定等作用，可以净化土壤或水体中的污染物，达到净化环境的目的，因而植物修复是一种很有潜力、正在发展的清除环境污染的绿色技术。③落点：原位、低成本、不破坏景观。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-10","subject":"857","term":"冻举","answer":"★★  第章  ①定义：又称冻拔，气温下降，引起土壤结冰，同质量的冰的体积比水大，这使得土壤体积增大，随着冻土层的不断加厚、膨大，会使得树木上举。②要点：解冻时，土壤下陷，树木留于原处，根系裸露地面，严重时倒伏死亡的现象。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-11","subject":"857","term":"长日照植物","answer":"★★  第章  ①定义：日照长度超过某一临界值才能开花的植物；②要点：日照不足时只进行营养生长，不能形成花芽。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-12","subject":"857","term":"趋同适应","answer":"①定义：不同物种因长期适应相似环境而表现出相似形态、生理或生态特征的现象，其结果是形成生活型。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-13","subject":"857","term":"最小因子定律","answer":"★★  第章  ①定义：当某一特定因子的存在量低于某种生物的最小需要量时，便成为决定该物种生存或分布的根本因素，该定律称为最小因子定律","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-14","subject":"857","term":"萎蔫系数","answer":"★★  第章  ①定义：土壤水分减少到植物发生永久萎蔫、即使灌水也不能恢复时的土壤含水量。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-15","subject":"857","term":"春化与层积","answer":"★★  第章  ①定义：春化是低温诱导植物花芽分化的过程；②要点：层积是湿沙低温处理种子，打破休眠、促进萌发的方法。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-16","subject":"857","term":"生理干旱","answer":"★★  第章  ①定义：土壤中虽有水分，但因低温、盐渍、通气不良等生理原因，植物不能吸水而表现出的干旱。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-17","subject":"857","term":"环境因子","answer":"①定义：构成环境的各个因素称为环境因子；其中能对生物的生长、发育和分布产生直接或间接影响的因子称为生态因子。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-18","subject":"857","term":"生态环境","answer":"★★  第章  ①定义：影响生物生存和发展的各种生态因子的总和，包括生物因子和非生物因子。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-19","subject":"857","term":"土壤微生物","answer":"★★  第章  ①定义：生活在土壤中的细菌、真菌、放线菌等微小生物的总称。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-20","subject":"857","term":"土壤动物","answer":"★★  第章  ①定义：在土壤中度过全部或部分生活史的动物，如蚯蚓、线虫、昆虫等。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-21","subject":"857","term":"土壤质地","answer":"★★  第章  ①定义：土壤中不同大小矿质颗粒的粗细组合，如砂土、壤土、黏土。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-22","subject":"857","term":"土壤结构","answer":"★★  第章  ①定义：土壤颗粒的排列组合方式、团聚体形态及孔隙状况。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-23","subject":"857","term":"相对湿度","answer":"★★  第章  ①定义：空气中实际水汽压与同温度下饱和水汽压之比。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-24","subject":"857","term":"日中性植物","answer":"★★  第章  ①定义：开花对日照长度不敏感，只要温度等条件合适就能开花的植物。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-25","subject":"857","term":"垂直地带性","answer":"★★  第章  ①定义：随海拔升高，气候、土壤和植被呈垂直方向有规律分异的现象。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-26","subject":"857","term":"寒害","answer":"★★  第章  ①定义：0℃以上低温对植物造成的伤害，如叶片变黄、花芽受冻、生长受阻。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-27","subject":"857","term":"重力水","answer":"★★  第章  ①定义：土壤中受重力作用向下移动、可排出土体的水分。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-28","subject":"857","term":"盐碱土","answer":"★★  第章  ①定义：可溶性盐或交换性钠含量过高、影响植物正常生长的土壤。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-29","subject":"857","term":"驯化","answer":"★★  第章  ①定义：植物在自然或人工条件下调整其对某些生态因子耐受范围的过程。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-30","subject":"857","term":"光饱和点","answer":"★★  第章  ①定义：光照强度增加到一定程度后，光合速率不再继续增加时的光照强度。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-31","subject":"857","term":"物候现象","answer":"★★  第章  ①定义：植物长期适应一年中气候节律变化而形成的周期性生长发育现象。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-32","subject":"857","term":"限制因子","answer":"★★  第章  ①定义：在诸多生态因子中，接近或超过生物耐受范围、限制生物生长发育甚至造成死亡的因子。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-33","subject":"857","term":"温周期现象","answer":"★★  第章  ①定义：植物对昼夜温度周期性变化的反应。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-34","subject":"857","term":"春化效应","answer":"★★★  第章  ①定义：某些植物在花芽分化前必须经历一定时间的低温处理才能开花的现象。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-35","subject":"857","term":"乡土树种","answer":"★★★  第章  ①定义：长期自然分布于本地、与当地气候和土壤条件高度适应、抗逆性强、养护成本低的树种。","chapter":"族：植物与环境适应（35 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-36","subject":"857","term":"生态位","answer":"★★  第章  ①定义：在n维空间中一个物种能存活和繁殖的范围，不仅包括生物占有的物理空间，还包括了其在生物群落中的地位和角色(如营养位置等),以及温度、湿度、PH、土壤和其他生活条件的环境变化梯度中的位置。②要点：不仅决定物种在哪里生活，也决定他们如何生活，以及如何受到其他生物的约束。③落点：生态位分化是竞争共存与混植依据。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-37","subject":"857","term":"化感作用","answer":"★★  第章  ①定义：很多生物个体彼此之间在化学上可能引起相互作用，在微生物之间，动物与植物之间，不同植物之间，甚至同种植物的不同个体之间都广泛存在这种作用，称为化感作用。②要点：植物的化感作用就是植物通过向环境释放化学物质，对其他植物产生直接或间接作用，包括促进或抑制作用。③落点：避免相克树种混植。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-38","subject":"857","term":"竞争排斥原理","answer":"★★  第章  ①定义：两个对同一资源产生竞争的种，不能长期共存，最终导致一个种占优势，另一个种被淘汰，这种现象即为竞争排斥原理。③落点：生态位分化才能共存。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-39","subject":"857","term":"生态交错区","answer":"★★  第章  ①定义：也称生态脆弱区，是指两种不同类型的生态系统的交界过渡区域。②要点：主要特征有：1)系统抗干扰能力弱2)对全球气候变化敏感3)时空波动性强4)边缘效应显著5)环境异质性高我国三大生态交错区：西北干旱及沙漠化地区、西南山地及石漠化地区、青藏高寒复合侵蚀地区③落点：我国三大交错区是常考。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-40","subject":"857","term":"边缘效应","answer":"★★  第章  ①定义：群落交错区种的数目以及一些种的密度增大的趋势。③落点：交错区物种数增多。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-41","subject":"857","term":"种间联结","answer":"★★  第章  ①定义：不同物种在空间分布上的相互关联性，分正联结、负联结、无联结；②要点：常用关联系数与显著性检验。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-42","subject":"857","term":"斑块形状指数","answer":"★★  第章  ①定义：斑块周长与同面积圆周长之比；②要点：值越大，形状越复杂、边缘效应越强。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-43","subject":"857","term":"抽彩式竞争","answer":"★★  第章  ①定义：竞争结果具有随机性，先占据资源或空间的个体获胜，而不是完全由竞争力决定。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-44","subject":"857","term":"种内关系","answer":"★★  第章  ①定义：同种生物个体之间的相互关系，包括种内竞争、互助、领域行为等。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-45","subject":"857","term":"种间关系","answer":"★★  第章  ①定义：不同物种个体之间的相互关系，包括竞争、捕食、寄生、互利共生等。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-46","subject":"857","term":"互利共生","answer":"★★  第章  ①定义：两种生物长期共同生活、相互受益的种间关系。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-47","subject":"857","term":"协同进化","answer":"★★  第章  ①定义：两个或多个物种在长期相互作用中相互选择、相互适应、共同进化的过程。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-48","subject":"857","term":"生态位泛化","answer":"★★  第章  ①定义：资源不足或竞争强烈时，物种扩大资源利用范围、食性或生境利用范围的现象。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-49","subject":"857","term":"生态位特化","answer":"★★  第章  ①定义：资源充足或竞争较弱时，物种缩小资源利用范围、向专化方向发展的现象。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-50","subject":"857","term":"他感植物","answer":"★★  第章  ①定义：能向环境释放化感物质、对其他植物产生抑制或促进作用的植物。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-51","subject":"857","term":"似然竞争","answer":"★★  第章  ①定义：两个物种通过共同捕食者或共同资源产生的间接相互影响。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-52","subject":"857","term":"群落交错区","answer":"★★  第章  ①定义：两个不同生态系统或群落之间的交界过渡区域，边缘效应明显。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-53","subject":"857","term":"他感作用","answer":"★★  第章  ①定义：植物通过向环境释放化学物质，对其他植物产生促进或抑制作用的化感现象。","chapter":"族：种间关系与生态位（18 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-54","subject":"857","term":"种群","answer":"★★  第章  ①定义：在一定空间中同种植物个体的组合，是物种存在、繁殖和进化的基本单位。③落点：物种存在繁殖进化的基本单位。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-55","subject":"857","term":"生态对策","answer":"★★  第章  ①定义：指生物经进化而形成的适应环境的对策或策略。又称生活史对策。②要点：有利于内禀增长率的选择为r一对策，有利于竞争能力增强的为k一对策。r一对策：自然界中的种群通过提高瞬时增长率来保护种群的增加和繁殖的生态对策。k一对策：自然界中的种群通过提高坏境容量来保护种群的增加和繁殖的生态对策。C一对策将能量主要分配给生长，生存环境相对稳定。竞争能力强，容易成为优势种群。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-56","subject":"857","term":"r-对策","answer":"★★★  第章  ①定义：以高繁殖率、短寿命、快速发育、后代多、竞争力弱为特征，适应不稳定环境的生活史策略。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-57","subject":"857","term":"密度效应","answer":"★★  第章  ①定义：种群个体数增加时，邻接个体间相互影响增强的现象。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-58","subject":"857","term":"动态生命表","answer":"★★  第章  ①定义：又称为同生群生命表或特定年龄生命表，是由同生群的个体从出生到最后一个个体死亡的数据构成的，反映了各龄级个体在经历相同环境条件下的同生群种群数量动态情况。②要点：(动态生命表主要适用于一二年生或短命植物的种群统计)。③落点：适用一二年生植物。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-59","subject":"857","term":"静态生命表","answer":"★★  第章  ①定义：又称特定时间生命表，它是根据某一特定时间调查获得的种群各龄级的个体数编制成的。②要点：(静态生命表适用于寿命较长的木本植物)。由于各种群各年龄阶段经历了不同的条件，因此该表综合了出生率和死亡率。③落点：适用长寿木本。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-60","subject":"857","term":"复合种群","answer":"★★  第章  ①定义：由空间上相互隔离、但个体间有迁移和交流的局部种群组成的种群系统。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-61","subject":"857","term":"种群年龄结构","answer":"★★  第章  ①定义：种群中各龄级个体数量所占的比例，影响种群的出生率、死亡率和未来发展趋势。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-62","subject":"857","term":"自疏原则","answer":"★★  第章  ①定义：种群密度增加时，个体间竞争加剧，导致部分个体死亡、密度下降的规律。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-63","subject":"857","term":"出生率","answer":"★★  第章  ①定义：单位时间内种群新出生个体数占种群总个体数的比例。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-64","subject":"857","term":"年龄结构","answer":"★★  第章  ①定义：种群中各年龄级个体数量所占的比例。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-65","subject":"857","term":"内禀增长率","answer":"★★  第章  ①定义：在理想条件下，种群不受资源限制时的最大瞬时增长率。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-66","subject":"857","term":"r对策","answer":"★★  第章  ①定义：以高繁殖率、短寿命、快速发育、后代多、竞争力弱为特征，适应不稳定环境的生活史对策。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-67","subject":"857","term":"k-对策","answer":"★★  第章  ①定义：以低繁殖率、长寿命、竞争力强、后代少为特征，适应稳定环境的生活史对策。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-68","subject":"857","term":"自疏法则","answer":"★★  第章  ①定义：种群密度增加时，个体间竞争导致部分个体死亡、密度下降的规律。","chapter":"族：对策与种群增长（15 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-69","subject":"857","term":"生物多样性","answer":"★★  第章  ①定义：指生命有机体及其赖以生存的生态综合体的多样化和变异性，即指生命形式的多样化，各种生命形式之间及其与环境之间的多种相互作用，以及各种生物群落、生态系统及其生境与生态过程的复杂性。③落点：四层次是采分点。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-70","subject":"857","term":"生态园林","answer":"★★  第章  ①定义：以生态学原理为指导，以植物为主体，模拟自然群落结构，建设结构合理、功能高效、关系协调的园林绿地系统的理论与实践。③落点：复层、乡土、自我维持。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-71","subject":"857","term":"演替","answer":"★★  第章  ①定义：一定地域的植物群落发生变化，形成其他植物群落并被其取代的过程；②要点：由低级到高级、由简单到复杂，一个群落代替另一个群落的自然演变现象。③落点：分原生/次生、进展/逆行。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-72","subject":"857","term":"生境","answer":"★★  第章  ①定义：是指植物体或植物群落所居住的地方，是具体的某一特定地段上对植物起作用的生态因子的总和。②要点：在生态学中常用这个词表示包括生物因子在内的环境。③落点：生境异质性支撑多样性。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-73","subject":"857","term":"种子雨","answer":"★★  第章  ①定义：植物种子从母株向地面扩散、降落的过程及其数量，是种群更新、植被恢复和群落演替的重要种源。③落点：近自然恢复留母树。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-74","subject":"857","term":"生态系统","answer":"★★  第章  ①定义：在一定时间和空间内，由生物群落与其环境组成的一个整体；②要点：各成员借助能量流动、物质循环和信息传递相互联系、相互依存，并具有自我调节功能。③落点：四要素是采分点。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-75","subject":"857","term":"原生演替","answer":"★★  第章  ①定义：在裸岩、裸地等从未有植被或植被被彻底消灭的基质上开始的演替。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-76","subject":"857","term":"优势种","answer":"★★★  第章  ①定义：一种对群落结构和群落环境的形成起主要作用的植物。②要点：通常个体数量最多，投影盖度大，生物量高，体积较大，生活能力较强。③落点：决定群落外貌。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-77","subject":"857","term":"生活型","answer":"★★  第章  ①定义：生物对外界环境适应所形成的外貌形态。②要点：它是不同生物在同一环境条件下的趋同适应。同一生活型的物种，不但体型相似，而且其适应特点也是相似的。③落点：趋同适应结果。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-78","subject":"857","term":"重要值","answer":"★★  第章  ①定义：衡量某物种在群落中地位和作用的综合数量指标。③落点：相对密度＋频度＋优势度。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-79","subject":"857","term":"自然群落","answer":"★★  第章  ①定义：在一定空间内自然形成的植物、动物和微生物种群的组合，具有特定的结构、功能和动态。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-80","subject":"857","term":"植物群落波动","answer":"★★  第章  ①定义：植物群落的个体数量和组成在短期内的变化，围绕平均状态波动，不涉及群落的根本更替。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-81","subject":"857","term":"生物学特征","answer":"★★  第章  ①定义：生物个体或群落在形态、生理、生长、繁殖等方面表现出的特征。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-82","subject":"857","term":"顶级群落","answer":"★★  第章  ①定义：群落演替达到相对稳定、能自我维持的最终阶段，结构和功能与环境相适应。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-83","subject":"857","term":"根际效应","answer":"★★  第章  ①定义：植物根系活动改变根际土壤的理化性质和微生物群落，使根际与非根际土壤产生明显差异。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-84","subject":"857","term":"植被型","answer":"★★  第章  ①定义：建群种生活型相同或相似、对水热条件要求一致的植物群落的联合。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-85","subject":"857","term":"群落稳定性","answer":"★★  第章  ①定义：群落抵抗外界干扰、保持结构和功能相对稳定，并在受干扰后恢复的能力。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-86","subject":"857","term":"宫胁法","answer":"★★  第章  ①定义：用乡土树种幼苗或容器苗多树种混植，模拟自然演替，快速恢复近自然森林的生态修复方法。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-87","subject":"857","term":"进展演替","answer":"★★  第章  ①定义：群落由简单到复杂、由不稳定到稳定、由低级到高级的演替过程。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-88","subject":"857","term":"逆行演替","answer":"★★  第章  ①定义：群落受到干扰后结构简化、功能退化、稳定性下降的演替过程。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-89","subject":"857","term":"盖度","answer":"★★  第章  ①定义：植物地上部分垂直投影面积占样地面积的比例。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-90","subject":"857","term":"次生演替","answer":"★★  第章  ①定义：原有植被遭到破坏后，在次生裸地上发生的群落演替。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-91","subject":"857","term":"伴生种","answer":"★★  第章  ①定义：群落中常见但数量和作用不及优势种、建群种的植物。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-92","subject":"857","term":"建群种","answer":"★★  第章  ①定义：群落中决定群落外貌、结构和环境的主要优势种。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-93","subject":"857","term":"层片","answer":"★★  第章  ①定义：群落中生活型相同或相似、生态要求一致的植物组合。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-94","subject":"857","term":"群落演替","answer":"★★  第章  ①定义：一定地域的植物群落随时间发生变化，被另一群落取代的过程。","chapter":"族：群落结构与演替（26 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-95","subject":"857","term":"生态平衡","answer":"★★  第章  ①定义：指在一定时间和相对稳定的条件下，生态系统各部分与功能处于相互适应与协调的动态平衡之中的稳定状态。②要点：判断一个生态系统是否平衡，可以从以下几方面判断：1)生物与其生存环境的协调性2)物质与能量的输入与输出3)内部结构的稳定性4)负熵增加③落点：平衡是动态的，超阈值即失调。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-96","subject":"857","term":"生态金字塔","answer":"★★  第章  ①定义：生态系统中的能量流动是单向的，植物将接收到的小部分太阳能固定成化学能，能量沿食物链流动，最后以热能形式返回到环境中或储存在生态系统中。②要点：由于通过各营养级的能量是逐渐减少的，如果把各营养级的能流量，由低到高画成图，就成为一个金字塔形，称为生态金字塔。③落点：能量金字塔恒正立。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-97","subject":"857","term":"生物地球化学循环","answer":"★★  第章  ①定义：环境中各种元素沿着特定的路线运动，由周围环境进入生物体，最后回到环境中，各种元素运动路线所包含着的活有机体的有机阶段和由各元素基本化学性质所决定的、无生命的阶段所组成的循环运动过程，称为生物地球化学循环。③落点：分气相型与沉积型。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-98","subject":"857","term":"水体富营养化","answer":"★★  第章  ①定义：指水体中氮、磷、钾等营养物质过多，致使水中的浮游植物过度繁殖，导致大量有机物残体分解和浮游植物呼吸消耗，水体溶氧量明显减少，水体浑浊，某些有毒水生藻类分解产生毒素，通过食物链毒害动物甚至人类。③落点：控源截污＋湿地净化。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-99","subject":"857","term":"物质循环","answer":"★★  第章  ①定义：生态系统从大气、水体和土壤等环境中获得营养物质，通过绿色植物吸收进入生命系统，被其他生物重复利用，最后归还于环境的过程。③落点：分气相型与沉积型。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-100","subject":"857","term":"能量流动","answer":"★★  第章  ①定义：指能源在满足城市多种功能过程中在城市生态系统内外的传递、流通和耗散过程。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-101","subject":"857","term":"食物链","answer":"★★  第章  ①定义：生物之间通过取食与被取食关系形成的链状营养联系。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-102","subject":"857","term":"食物网","answer":"★★  第章  ①定义：多条食物链相互交织形成的网状营养关系。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-103","subject":"857","term":"抵抗力","answer":"★★  第章  ①定义：生态系统受到外界干扰时，保持原有结构和功能不变的能力。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-104","subject":"857","term":"生态系统物质循环","answer":"★★  第章  ①定义：物质从环境进入生物体，沿食物链传递，最后被分解者归还环境的过程。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-105","subject":"857","term":"能量金字塔","answer":"★★  第章  ①定义：把各营养级的能量、生物量或个体数量由低到高排列成金字塔形的图解。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-106","subject":"857","term":"生物地理化学循环","answer":"★★★  第章  ①定义：环境中各种元素沿特定路线由环境进入生物体，最后又回到环境，包含有机阶段和无机阶段的循环过程。","chapter":"族：生态系统功能（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-107","subject":"857","term":"生态足迹","answer":"★★  第章  ①定义：在一定的技术条件下，支持一定地区的人口所需要的具备生物生产能力和吸纳这些人口所产生的废弃物的土地面积之和。②要点：生态足迹如果小于区域的承载能力，则表现为生态盈余，如果超过了，就表现为生态赤字。③落点：超承载力即生态赤字。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-108","subject":"857","term":"生态福","answer":"★★  第章  ①定义：生态承载力与生态足迹的差值。②要点：差值为正称生态盈余，为负称生态赤字。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-109","subject":"857","term":"光污染","answer":"★★  第章  ①定义：指环境中过量光辐射对人类及其他生物正常生存和生产环境造成不良影响的现象。②要点：具体包括：人造白昼污染：城市夜景照明使城市夜空亮度增加，由此对人和生物造成危害的现象。白亮污染：由于强烈人工光和玻璃幕墙反射光、聚焦光产生，而造成的危害现象。彩光污染：由各种黑光灯、荧光灯、霓虹灯、灯箱广告等彩光污染源带来的既损害生理功能又损害心理健康的危害现象。③落点：三类：人造白昼、白亮、彩光。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-110","subject":"857","term":"生态系统服务","answer":"★★  第章  ①定义：指生态系统通过其生态过程，提供给人类维持生命和社会经济发展所需要的产品和服务。②要点：产品是指市场上可用货币表现的商品，包括供给服务、调节服务、文化服务和支持服务。③落点：四类服务是采分点。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-111","subject":"857","term":"生态盈余","answer":"★★★  第章  ①定义：区域生态承载力大于生态足迹时出现的盈余状态，表示资源供给大于消费，是可持续性的重要指标。③落点：与生态赤字相对。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-112","subject":"857","term":"生态安全格局","answer":"★★  第章  ①定义：为维护区域生态安全、保护关键生态过程与功能，由关键生态源地、廊道和节点构成的空间格局。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-113","subject":"857","term":"水体污染","answer":"★★  第章  ①定义：进入水体的污染物质超过水体自净能力，使水的组成和性质发生变化，影响水生生物和人体健康的现象。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-114","subject":"857","term":"环境污染","answer":"★★  第章  ①定义：人类活动排放的污染物超过环境容量，使环境质量下降、生态系统和人体健康受到危害的现象。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-115","subject":"857","term":"生态系统健康","answer":"★★  第章  ①定义：生态系统结构完整、功能正常、具有自我维持和抗干扰能力的状态。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-116","subject":"857","term":"园林生态学","answer":"★★  第章  ①定义：研究园林空间范围内居民、生物与环境之间相互作用关系的科学，以园林植物和城市环境为主要研究对象，以建设健康人居环境为目的。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-117","subject":"857","term":"土壤污染","answer":"★★  第章  ①定义：进入土壤的有害物质超过土壤自净能力，使土壤结构、功能和肥力下降，影响动植物和人体健康的现象。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-118","subject":"857","term":"大气污染","answer":"★★  第章  ①定义：人类活动排放的污染物超过大气自净能力，使大气质量下降、危害生态系统和人体健康的现象。","chapter":"族：服务与承载力（12 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-119","subject":"857","term":"热岛效应","answer":"★★  第章  ①定义：指城市温度高于郊区气温的现象，且这种增温现象影响范围可到达周围郊区。③落点：增绿增水、留通风廊道、垂直绿化。","chapter":"族：城市气候与环境（10 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-120","subject":"857","term":"温室效应","answer":"★★  第章  ①定义：大气中的CO₂、CH₄等温室气体吸收地面长波辐射，使地表温度升高的现象；②要点：人类活动增强其强度，导致全球变暖。③落点：增汇、减排、适应。","chapter":"族：城市气候与环境（10 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-121","subject":"857","term":"指示植物","answer":"★★  第章  ①定义：对特定环境条件（如大气污染、土壤性质、气候）反应敏感、可用来指示环境状况的植物。③落点：用于环境监测。","chapter":"族：城市气候与环境（10 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-122","subject":"857","term":"城市峡谷风效应","answer":"★★  第章  ①定义：城市建筑密集，自然风穿过建筑间通道时风速增大、方向改变的现象。","chapter":"族：城市气候与环境（10 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-123","subject":"857","term":"城市干岛效应","answer":"★★  第章  ①定义：城市空气湿度低于郊区的现象；②要点：主要由不透水地面多、蒸散少、排水快造成。","chapter":"族：城市气候与环境（10 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-124","subject":"857","term":"环境问题","answer":"★★  第章  ①定义：人类活动引起的环境质量下降、生态破坏，并对人类生存和发展产生不利影响的现象。","chapter":"族：城市气候与环境（10 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-125","subject":"857","term":"干岛效应","answer":"★★  第章  ①定义：城市空气湿度低于郊区，主要由不透水地面多、蒸散少、排水快造成。","chapter":"族：城市气候与环境（10 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-126","subject":"857","term":"城市峡谷效应","answer":"★★  第章  ①定义：街道两侧建筑形成类似峡谷的空间，使风速、温度、湿度和污染物扩散发生改变的现象。","chapter":"族：城市气候与环境（10 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-127","subject":"857","term":"城市环境管理","answer":"★★  第章  ①定义：运用行政、法律、经济和技术手段，对城市环境质量、污染源和环境行为进行管理。","chapter":"族：城市气候与环境（10 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-128","subject":"857","term":"酸沉降","answer":"★★  第章  ①定义：大气中的二氧化硫、氮氧化物与水汽结合形成酸性物质，以降水等形式降落到地面、pH 小于 5.6 的现象。","chapter":"族：城市气候与环境（10 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-129","subject":"857","term":"生物入侵","answer":"★★  第章  ①定义：外来物种传入新环境后，在缺乏天敌等自然控制的情况下大量繁殖、扩散，并对本地生物多样性和生态系统造成危害的现象。③落点：检疫＋清除＋替代。","chapter":"族：多样性与入侵（3 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-130","subject":"857","term":"外来物种","answer":"★★  第章  ①定义：通过自然或人为途径传入其自然分布范围以外地区的物种；②要点：外来物种不一定造成生物入侵。","chapter":"族：多样性与入侵（3 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-131","subject":"857","term":"生态入侵","answer":"★★★  第章  ①定义：外来物种传入新环境后，在缺乏天敌等自然控制的情况下大量繁殖、扩散，并对本地生物多样性和生态系统造成危害的现象。","chapter":"族：多样性与入侵（3 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-132","subject":"857","term":"景观","answer":"★★★  第章  ①定义：小范围内，由不同类型的生态系统以某种空间组织方式组成的异质性地理空间单元。②要点：从广义上看是由不同土地单元组成的具有明显视觉特征的地理实体。城市景观就是以城市建成区为主体，由城市街区、道路、公园、绿地、林地及近郊城郊型农田等景观要素构成，以人类活动为主导，发挥城市功能的地域实体。③落点：斑块—廊道—基质是分析基本模型。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-133","subject":"857","term":"景观生态流","answer":"★★  第章  ①定义：在景观各空间组分之间物质、能量、物种和其他信息的流动。③落点：廊道决定生态流是否通畅。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-134","subject":"857","term":"斑块","answer":"★★  第章  ①定义：景观中内部属性、结构、功能、外貌特征相对一致，与周围景观要素有明显区别的块状空间地域实体或地段。②要点：按起源可以分为干扰斑块、残存斑块、环境资源斑块和引入斑块。③落点：大斑块保育、小斑块踏脚石。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-135","subject":"857","term":"廊道","answer":"★★  第章  ①定义：廊道是斑块的一种特殊形式，是指与两边的景观要素或本底有明显区别的带状地块。②要点：分为干扰廊道、残余廊道、环境资源廊道和种植廊道③落点：绿道即廊道。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-136","subject":"857","term":"景观异质性","answer":"★★  第章  ①定义：景观中景观要素在属性、结构、形态和空间等方面的变异程度，由景观要素类型的数量，景观要素分布和空间相互关系决定的。③落点：适度异质性增多样性。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-137","subject":"857","term":"景观生态过程","answer":"★★  第章  ①定义：景观中物质、能量、物种和信息的流动与转化过程，以及景观格局形成、维持和演变的动力学过程。③落点：以格局优化调控过程。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-138","subject":"857","term":"蓝绿空间","answer":"★★  第章  ①定义：城市中蓝色空间（河流、湖泊、湿地等水体）与绿色空间（林地、草地、公园等）的统称，强调生态网络协同。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-139","subject":"857","term":"尺度效应","answer":"★★  第章  ①定义：随尺度的增大，景观出现不同类型的最小斑块，最小斑块面积逐渐增大，而景观的多样性指数随尺度的增大而减小。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-140","subject":"857","term":"景观规划","answer":"★★  第章  ①定义：是以人为中心，将各种土地利用方式有机结合起来，以构成和谐有序的地表空间的人类活动方式，是景观管理的重要手段和景观生态学的有机组成部分，体现景观生态学的应用价值。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-141","subject":"857","term":"景观格局","answer":"★★  第章  ①定义：景观要素在空间上的排列组合和配置方式，包括斑块、廊道、基质的数量、大小、形状和连通性。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-142","subject":"857","term":"植物浮床","answer":"★★  第章  ①定义：利用水生或湿生植物在浮体上生长，通过根系吸收和微生物作用净化水体、营造生境的生态技术。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-143","subject":"857","term":"边际效应","answer":"★★  第章  ①定义：景观边缘部分受外围环境影响，生态特征与中心部分明显不同的现象。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-144","subject":"857","term":"种群空间格局","answer":"★★  第章  ①定义：种群个体在空间上的分布方式，主要有均匀分布、随机分布和聚集分布三种类型。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-145","subject":"857","term":"景观生态学","answer":"★★  第章  ①定义：研究景观结构、功能、动态和尺度特征，以及人类活动与景观相互关系的交叉学科。","chapter":"族：景观格局与规划（14 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-146","subject":"857","term":"环境容量","answer":"★★  第章  ①定义：指某一环境在自然结构、生态结构和正常功能不受损害、人类生存环境质量不下降的前提下，能容纳的污染物的最大量。②要点：既包括了环境本身的自净能力，也包括环保设施对污染物的处理能力。③落点：污染物总量控制依据。","chapter":"族：生态评价与修复（4 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-147","subject":"857","term":"植物监测","answer":"★★  第章  ①定义：利用植物对污染物的敏感反应、伤害症状或体内污染物含量，监测和评价环境质量的方法。","chapter":"族：生态评价与修复（4 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-148","subject":"857","term":"城市生态管理","answer":"★★  第章  ①定义：运用生态学原理和方法，对城市生态系统的结构、功能、过程和人类活动进行调控和管理。","chapter":"族：生态评价与修复（4 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-149","subject":"857","term":"恢复力","answer":"★★  第章  ①定义：生态系统受到干扰后恢复到原来状态的能力。","chapter":"族：生态评价与修复（4 条）","note":"","category":"重点","level":"重点"},{"id":"857-t-150","subject":"857","term":"杀菌素","answer":"①定义：高等植物体内含有的对病原菌有杀害作用的化学物质。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-151","subject":"857","term":"古树名木","answer":"①定义：树龄在100年以上的古树，以及具有重要历史、文化、科研、纪念意义或稀有珍贵树种的名木。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-152","subject":"857","term":"生长富集","answer":"①定义：生物在生长发育过程中从环境中吸收并积累某些元素或污染物，使其体内浓度高于环境浓度的现象。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-153","subject":"857","term":"环境本底","answer":"①定义：未受或很少受人类活动影响的环境原始状态/背景值；","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-154","subject":"857","term":"残遗种","answer":"①定义：古代广泛分布、后因地质变迁大量灭绝，现存仅局限于狭小区域的物种。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-155","subject":"857","term":"生态习性","answer":"①定义：植物长期适应某一环境条件所形成的生长发育规律和对环境的要求。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-156","subject":"857","term":"适应组合","answer":"①定义：生物对某一特定环境条件所形成的一系列相互协调的适应特征。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-157","subject":"857","term":"群聚","answer":"①定义：同种个体或不同种群在空间上成群、成簇分布的现象。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-158","subject":"857","term":"皮烧（日灼伤）","answer":"①定义：强光高温使树皮、果实表面组织灼伤，出现变色、开裂甚至坏死。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-159","subject":"857","term":"根茎灼伤","answer":"①定义：地表高温灼伤植物根颈和茎基部，导致树势衰弱甚至死亡。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-160","subject":"857","term":"干扰状况","answer":"①定义：干扰的类型、频率、强度、尺度、时间和空间分布等的综合特征。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-161","subject":"857","term":"迁入率","answer":"①定义：单位时间内迁入种群的个体数占种群总个体数的比例。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-162","subject":"857","term":"干燥度","answer":"①定义：可能蒸发量与降水量之比，用于衡量气候干燥程度。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-163","subject":"857","term":"中日照植物","answer":"①定义：花芽形成需要中等日照长度的植物。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-164","subject":"857","term":"水平地带性","answer":"①定义：随纬度或经度变化，植被呈水平方向有规律分异的现象。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-165","subject":"857","term":"遗传漂变","answer":"①定义：小种群中由于随机抽样导致基因频率发生随机波动的现象。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-166","subject":"857","term":"适合度","answer":"①定义：生物个体存活、繁殖并将基因传递给后代的相对能力。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-167","subject":"857","term":"环境","answer":"①定义：生物个体或群体外的一切因素的总和，包括自然环境和社会环境。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-168","subject":"857","term":"生态学特征","answer":"①定义：生物与环境相互作用中表现出的生态适应、分布和功能特征。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"},{"id":"857-t-169","subject":"857","term":"黄化现象","answer":"①定义：植物在黑暗条件下不能合成叶绿素、叶片发黄的现象。","chapter":"二、名词解释（20 条 · 认得即可）","note":"","category":"了解","level":"了解"}],"bigs":[{"id":"857-b-1","title":"简述城市土壤的特点","type":"简答","category":"重点","score":10,"source":"2021","full":[{"h":"1. 总述","t":"城市土壤受人类活动影响，物理、化学和生物特性均与自然土壤有较大差异，主要表现在："},{"h":"2. 土壤污染","t":"物理、化学、生物污染物进入土壤并超过土壤自净能力，使土壤自然功能失调、肥力下降，影响植物生长发育，污染物还可在植物体内积累，通过食物链危害人体健康。"},{"h":"3. 土壤坚实","t":"紧实度明显大于郊区，一般愈近地表愈大；紧实使土壤空气减少、通气性下降、氧气不足，抑制根系呼吸等生理活动，严重时根组织窒息死亡。"},{"h":"4. 土壤贫瘠化","t":"枯枝落叶被作为垃圾清除，养分循环中断，有机质含量降低；渣土养分少且难被植物吸收；封闭地面阻碍大气与土壤的气体交换，有机质分解和养分释放减少。"},{"h":"5. 土壤含水量低","t":"地面硬化铺装使降水后土壤水分补给减少，热岛效应又加剧土壤水分蒸发，故含水量偏低。"}],"pit":""},{"id":"857-b-2","title":"简述温度对植物的生态作用","type":"简答","category":"重点","score":10,"source":"2021","full":[{"h":"1. 总述","t":"温度是植物重要的环境因子，其对园林植物的生态作用表现在："},{"h":"2. 对生理活动的影响","t":"影响促进光合、呼吸等生化反应的酶活性，影响CO₂和O₂在细胞中的溶解度，影响根系吸收水分和矿物质的能力；温度改变空气水汽压差并影响叶温与气孔开闭，从而影响蒸腾，蒸腾过快而吸水不足时植物萎蔫甚至枯死。"},{"h":"3. 对种子萌发的影响","t":"变温能提高种子萌发率，部分阔叶树种子需经低温层积处理才能提高发芽率。"},{"h":"4. 对生长的影响","t":"在最适温度范围内变温促进生长，通常变温幅度越大生长越快。"},{"h":"5. 对开花结实及品质的影响","t":"温差大有利于开花结实和同化物积累，果实品质好；金盏菊、金鱼草等需经低温春化才能开花。"},{"h":"6. 极端温度的危害","t":"低温造成寒害、冻害、霜害、冻举（冻拔）、冻裂和生理干旱；高温造成皮烧和根茎灼伤。"}],"pit":""},{"id":"857-b-3","title":"简述K－对策和r－对策的特征","type":"简答","category":"重点","score":10,"source":"2021","full":[{"h":"1. 总述","t":"生态对策是生物经进化形成的适应环境的对策；逻辑斯谛模型中，有利于增大内禀增长率r的选择为r－对策，有利于增强竞争能力、提高环境容纳量K的选择为K－对策。"},{"h":"2. r－对策者","t":"出生率高、死亡率高且死亡率与密度无关；个体小、寿命短；缺乏保护后代的机制，子代死亡率高；扩散能力强；种群密度很不稳定，很少达到K；适应严酷而不稳定的环境，是新生境的开拓者、先锋植物，属机会主义者。"},{"h":"3. K－对策者","t":"出生率低、死亡率低且死亡多由密度相关因素引起；个体大、寿命长；具有完善的后代保护机制；竞争能力强但扩散能力差；种群稳定，密度常处于K值附近；适应良好而稳定的环境，属保守主义者。"},{"h":"4. 要点","t":"二者是两种极端策略，多数生物处于r－K连续谱的中间类型。"}],"pit":""},{"id":"857-b-4","title":"简述生态因子作用的一般特征","type":"简答","category":"重点","score":10,"source":"2021/2023","full":[{"h":"1. 综合性","t":"生态环境是多个生态因子组合而成的综合体，对植物起综合作用；各因子相互影响、相互制约，任一因子的变化都会引起其他因子的变化。"},{"h":"2. 非等价性","t":"各因子对植物的作用不是等价的，其中必有起决定性作用的主导因子。"},{"h":"3. 不可替代性和互补性","t":"光、热、水分、空气、无机盐等是植物必需因子，不可替代；但某一因子数量不足时，可由另一因子的加强得到调剂或补偿。"},{"h":"4. 阶段性","t":"植物不同生长发育阶段需要不同的生态因子或不同的因子强度。"},{"h":"5. 直接作用与间接作用","t":"区分因子的直接作用和间接作用，是分析植物生长发育与分布原因的重要依据。"},{"h":"6. 总述","t":"此外，任一因子接近或超过植物的耐受范围时即成为限制因子。"}],"pit":""},{"id":"857-b-5","title":"简述热岛效应产生的原因","type":"简答","category":"重点","score":10,"source":"2021/2022","full":[{"h":"1. 总述","t":"城市热岛效应是指城市气温高于郊区气温的现象，其形成原因主要有："},{"h":"2. 下垫面反射率小","t":"城市绿地面积小，大量使用建筑材料，反射率低于植被，吸收的太阳辐射多。"},{"h":"3. 下垫面热容量和热导率大","t":"建筑材料白天吸收积聚大量辐射热，地面温度高，供给大气的热量比郊区多。"},{"h":"4. 大气保温作用强","t":"城市CO₂和空气污染物含量高，形成覆盖层，强烈吸收地面长波辐射，大气逆辐射大于郊区，热量散失少。"},{"h":"5. 人为热释放多","t":"各种燃烧过程和人类活动产生大量热量，可接近甚至超过太阳辐射热量。"},{"h":"6. 通风与蒸发散热弱","t":"建筑物密集、通风不良，热量不易扩散；不透水面积大、排水系统发达，蒸发蒸腾消耗的热量少。"}],"pit":""},{"id":"857-b-6","title":"简述园林植物对水分的调节作用","type":"简答","category":"重点","score":10,"source":"2022","full":[{"h":"1. 增加空气湿度","t":"园林树木有较强的遮阳庇荫和降低风速作用，同时蒸腾作用强，可显著提高空气湿度。"},{"h":"2. 涵养水源、保持水土","t":"林冠截留降水，减少和延缓地表径流；枯枝落叶和地被层吸水，使水分缓慢下渗形成地下潜流，枯水期补给河流；绿地特别是森林土壤入渗率高，减少地表径流量、增加植物可利用水，防止水土流失；绿地覆盖有利于融雪水下渗，减弱地表径流。"},{"h":"3. 净化水体","t":"植物可吸收、富集水体中的溶解物质，富集浓度可达水中浓度的几十至几千倍，从而减轻水体污染、净化水质。"}],"pit":""},{"id":"857-b-7","title":"简述城市环境的特征并分析其形成原因","type":"简答","category":"重点","score":10,"source":"2022","full":[{"h":"1. 高度人工化特征","t":"城市是人口最集中、社会经济活动最频繁的地方，人类对自然的影响最强烈。除大气环流和大地貌基本保持原状外，地貌、水文、气候、植被、动物等自然因素都发生不同程度且往往不可逆的变化。"},{"h":"2. 空间上的平面和立面特征","t":"城市环境各要素在城市平面和高度上有形地表现。平面上表现为用地形态，可用位置、距离、方向描述，常见方形、圆形、星形、长条形；立面上表现为城市轮廓、人造地貌。原因是城市用地扩展和建设发展具有方向性和距离衰减特点。"},{"h":"3. 地域层次特征","t":"城市环境是地域综合体，以不同活动为中心形成居住环境、工业环境、商业环境等地域子环境，并可细分到具体用地。原因是不同功能活动的物质环境存在地域分异，人工化程度不同。"},{"h":"4. 污染特征","t":"与自然环境相比，城市环境在组成、结构和影响因素上变化很大，表现为热岛效应、干岛效应、径流量增加、大气与水体污染等。原因是下垫面改变、人为热与污染物集中排放、植被覆盖减少。"}],"pit":""},{"id":"857-b-8","title":"简述城市绿地系统质量评价的内容","type":"简答","category":"重点","score":10,"source":"2022/2024/2025","full":[{"h":"1. 总述","t":"城市绿地系统评价是应用生态学原理和方法，遵循以人为本和可持续发展思想，对绿地系统结构的合理性、景观环境的宜人性、生态过程的连续性与稳定性等作出评价，内容包括四个方面："},{"h":"2. 绿地系统整体格局的合理性","t":"从城市整体水平收集图件，借助地理信息技术分析整体绿化状况与绿地指标，并与国家有关标准和绿化先进城市比较；分析景观结构和空间格局、绿地布局是否合理，主要绿色廊道分布是否有利于缓解热岛效应和其他城市环境问题，空间连接度和生态连通性如何，城市内部绿地与周边绿地关系是否密切，各类公园绿地与居民区等人口集中区的空间关系是否体现以人为本。"},{"h":"3. 绿色廊道和绿地斑块的结构分析","t":"绿地比例是否达标，植物搭配和带状空间配置是否合理；分析各项绿地指标的服务半径、内部结构与配置、植物种类及生长状况、群落演替与群落结构等。"},{"h":"4. 生物多样性的分析","t":"分析植物种类的组成与分类、树木与其他植物的组成结构；确定主要绿化树种并分析其生长状况和绿化效果；分析当地特色和珍稀种类的数量、分布与生长状态。"},{"h":"5. 各类绿地及绿化管理评价","t":"分别对公共绿地、道路绿化、居住区绿化、单位绿化等进行分析，从绿地空间配置、种类组成、群落结构、生长状况、管护情况及园林建设与管理等方面总结优点和经验，分析问题与不足，提出改进措施。"}],"pit":""},{"id":"857-b-9","title":"简述光周期现象在园林培育中的应用","type":"简答","category":"重点","score":10,"source":"2023","full":[{"h":"1. 总述","t":"光周期现象是植物生长发育对日照长度规律性变化的反应，在园林植物培育中应用广泛："},{"h":"2. 花期调控","t":"短日照植物可通过遮光缩短光照使其提前开花，如一品红8月上旬开始遮光，每天给光约8～10小时，经45～55天即可提前开花；菊花同样通过遮光提前至目标花期。长日照植物则可通过人工补光延长光照促其开花，或对短日照植物夜间补光以推迟花期，实现“不时之花”。"},{"h":"3. 引种驯化","t":"引种前须明确植物的光周期类型，判断其在本地日照条件下能否正常开花结实，避免盲目引种造成只长不开花。"},{"h":"4. 育苗与营养生长调控","t":"利用长日照促进营养生长、短日照促进加粗和养分积累的特性，控制苗木高生长和株形，培育优质壮苗。"},{"h":"5. 休眠与抗性调控","t":"短日照可诱导芽进入休眠、枝条成熟木质化，提高苗木越冬抗寒能力，用于苗木贮藏和抑制萌芽。"},{"h":"6. 杂交育种","t":"通过光照处理调节父母本花期，使花期相遇，便于杂交授粉。"}],"pit":""},{"id":"857-b-10","title":"简述城市光环境的特点","type":"简答","category":"重点","score":10,"source":"—","full":[{"h":"1. 光照度减弱","t":"城市大气中悬浮颗粒物和污染物多，削弱太阳辐射；加上建筑遮挡，城市光照度一般低于郊区。"},{"h":"2. 光照分布不均","t":"建筑高度与街道宽度之比（街道狭窄指数N=H/D）越大，街道接收的太阳辐射越弱；建筑物附近树木受光量不均匀，易造成偏冠；不同下垫面反射率差异也造成光环境差异。"},{"h":"3. 光污染严重","t":"包括人造白昼污染（夜景照明使夜空亮度增加）、白亮污染（强烈人工光和玻璃幕墙反射、聚焦光）和彩光污染（黑光灯、霓虹灯、灯箱广告等）。"},{"h":"4. 人工照明干扰光周期","t":"夜间照明延长了有效光照时间，影响短日照植物的花芽分化和开花，也干扰昆虫、鸟类等生物的昼夜节律。"},{"h":"5. 总述","t":"第二部分　第 11—20 题　简答进阶"}],"pit":""},{"id":"857-b-11","title":"简述城市植被与自然植被的区别","type":"简答","category":"重点","score":10,"source":"2022/2024","full":[{"h":"1. 总述","t":"城市植被是在城市化过程中受人类活动强烈影响而形成的植被，与自然植被相比主要区别在于："},{"h":"2. 生境的变化","t":"城市化改变了城市植被的生境。受城市废弃物、建筑物、城市气候及人为活动影响，城市土壤的物理、化学性质与自然状况下发育的土壤差异很大，生境破碎化加剧。"},{"h":"3. 植物区系成分的变化","t":"城市植被区系与原生植被有较大相似性，尤其是残存或受保护的原生植被片断，但灌木、草本和藤本植物远较原生植被少；城市化一方面使乡土植物种类减少，另一方面使人工栽培的人布植物增多。"},{"h":"4. 群落类型与分布格局的变化","t":"城市植被在自然与人为因子共同作用下，其分布格局与城市的同心圈层结构相重叠，并以观赏型等人工植物群落为主，种类组合取决于人的喜好。"},{"h":"5. 演替过程的变化","t":"城市中残存自然植被多呈小面积孤岛状分布，其维持机理和演替过程与地带性自然植被不同；种子散布能力和种源母树影响孤岛群落的种群动态，左右演替进程；并具有能迅速入侵林内、到达林冠层的顶级先锋种。"}],"pit":""},{"id":"857-b-12","title":"什么是“碳中和”“碳达峰”？简述二者的关系","type":"简答","category":"重点","score":10,"source":"2024","full":[{"h":"1. 碳达峰","t":"指碳排放量达到峰值，即二氧化碳排放量由增转降的历史拐点。碳排放量在一定程度上反映发展速度，争取早日碳达峰即争取早日完成建设任务。"},{"h":"2. 碳中和","t":"指企业、团体或个人测算在一定时间内直接或间接产生的温室气体排放总量，通过植树造林、节能减排等形式，抵消自身产生的二氧化碳排放量，实现二氧化碳“零排放”，推动绿色生活、生产，实现全社会绿色发展。"},{"h":"3. 二者关系","t":"碳达峰是碳中和的前提和必经阶段，碳中和是碳达峰的最终目标。先达峰、后中和，时间上前后衔接；达峰峰值越低、达峰时间越早，碳中和的压力越小、实现越容易；碳中和又反过来要求达峰后排放量持续快速下降。"},{"h":"4. 对园林绿化的意义","t":"城市绿地通过植物固碳、节能减排发挥碳汇作用，是低成本实现碳中和的重要途径。"}],"pit":""},{"id":"857-b-24","title":"简述生态系统物质循环的类型与特点","type":"简答","category":"重点","score":10,"source":"专题","full":[{"h":"1. 总述","t":"物质循环：生态系统从大气、水体和土壤等环境中获得营养物质，经绿色植物吸收进入生命系统，被其他生物重复利用，最后归还于环境的过程。元素沿特定路线在环境与生物体之间往返运动，称为生物地球化学循环。"},{"h":"2. 总述","t":"类型："},{"h":"3. 水循环","t":"水在气、液、固三态间转化，主要蓄库为大气、海洋和陆地水体，具有全球性，循环速率快，是其他物质循环的载体和动力。"},{"h":"4. 气体型循环","t":"以碳、氮、氧为代表，主要蓄库是大气和海洋，具有全球性，循环速度快，易受人类活动干扰（如CO₂升高引起温室效应）。"},{"h":"5. 沉积型循环","t":"以磷、硫、钾、钙为代表，主要蓄库是岩石和土壤，多具局部性，循环速度慢，元素易在土壤中积累而难以被利用。"},{"h":"6. 总述","t":"特点："},{"h":"7. 要点","t":"循环往复、可被反复利用，物质不灭，与能量流动的单向递减不同；"},{"h":"8. 要点","t":"不同元素周转速率差异极大，如CO₂约1年，大气中氮约100万年；"},{"h":"9. 要点","t":"生物是循环的动力和枢纽，生产者吸收、消费者传递、分解者归还；循环速度受元素性质、生物生长速率、有机物质腐烂速率和人类活动影响；"},{"h":"10. 要点","t":"人类活动强烈改变循环的速率和方向，如化石燃料燃烧加速碳循环、化肥施用改变氮磷循环。"}],"pit":""},{"id":"857-b-48","title":"城市土壤环境具有哪些特点？如何治理土壤污染？","type":"简答","category":"重点","score":10,"source":"2018·2019·2021","full":[{"h":"1. 总述","t":"（一）城市土壤的特点：城市土壤受人类活动影响，物理、化学和生物特性均与自然土壤有较大差异。"},{"h":"2. 土壤污染","t":"物理、化学、生物污染物超过土壤自净能力，使土壤功能失调、肥力下降，并可通过食物链危害健康。"},{"h":"3. 土壤坚实","t":"紧实度明显大于郊区，愈近地表愈大；土壤空气减少、通气性下降，抑制根系呼吸，严重时根组织窒息死亡。"},{"h":"4. 土壤贫瘠化","t":"枯枝落叶被清除使养分循环中断，有机质降低；渣土养分少难吸收；封闭地面阻碍气体交换，有机质分解和养分释放减少。"},{"h":"5. 土壤含水量低","t":"地面硬化使降水补给减少，热岛效应加剧蒸发。"},{"h":"6. 总述","t":"（二）土壤污染的治理："},{"h":"7. 排土与客土改良","t":"挖去污染土层，用清洁土壤改造污染土壤，效果好但投入大。"},{"h":"8. 施用化学改良剂","t":"使重金属转化为难溶性物质，如对镉污染土壤施用石灰中和酸性，使镉沉淀而难被植物吸收。"},{"h":"9. 植物修复","t":"以植物能忍耐和超量积累某些化学元素为基础，通过植物及共存微生物的吸收、挥发、根滤、降解、稳定等作用清除污染物，成本低、应用方便，是很有潜力的绿色治理技术。"}],"pit":""},{"id":"857-b-49","title":"温度对园林植物的生态作用有哪些？","type":"简答","category":"重点","score":10,"source":"2021","full":[{"h":"1. 总述","t":"温度是植物重要的环境因子，其对园林植物的生态作用表现在："},{"h":"2. 对生理活动的影响","t":"影响促进光合、呼吸等生化反应的酶活性，影响CO₂和O₂在细胞中的溶解度，影响根系吸收水分和矿物质的能力；温度改变空气水汽压差并影响叶温与气孔开闭，从而影响蒸腾，蒸腾过快而吸水不足时植物萎蔫甚至枯死。"},{"h":"3. 对种子萌发的影响","t":"变温能提高种子萌发率，部分阔叶树种子需经低温层积处理才能提高发芽率。"},{"h":"4. 对生长的影响","t":"在最适温度范围内变温促进生长，通常变温幅度越大生长越快。"},{"h":"5. 对开花结实及品质的影响","t":"温差大有利于开花结实和同化物积累，果实品质好；金盏菊、金鱼草等需经低温春化才能开花。"},{"h":"6. 极端温度的危害","t":"低温造成寒害、冻害、霜害、冻举（冻拔）、冻裂和生理干旱；高温造成皮烧和根茎灼伤。"}],"pit":""},{"id":"857-b-50","title":"k－对策和r－对策的植物各有什么特征？","type":"简答","category":"重点","score":10,"source":"2021","full":[{"h":"1. 总述","t":"生态对策是生物经进化形成的适应环境的对策；逻辑斯谛模型中，有利于增大内禀增长率r的选择为r－对策，有利于增强竞争能力、提高环境容纳量K的选择为K－对策。"},{"h":"2. r－对策者","t":"出生率高、死亡率高且与密度无关；个体小、寿命短；缺乏保护后代的机制，子代死亡率高；扩散能力强；种群密度很不稳定，很少达到K；适应严酷而不稳定的环境，是新生境的开拓者、先锋植物，属机会主义者。"},{"h":"3. K－对策者","t":"出生率低、死亡率低且死亡多由密度相关因素引起；个体大、寿命长；具有完善的后代保护机制；竞争能力强但扩散能力差；种群稳定，密度常处于K值附近；适应良好而稳定的环境，属保守主义者。"},{"h":"4. 要点","t":"二者是两种极端策略，多数生物处于r－K连续谱的中间类型。"}],"pit":""},{"id":"857-b-51","title":"城市环境的特征及其形成原因。","type":"简答","category":"重点","score":10,"source":"2022","full":[{"h":"1. 高度人工化特征","t":"城市是人口最集中、社会经济活动最频繁的地方，人类对自然的影响最强烈。除大气环流和大地貌基本保持原状外，地貌、水文、气候、植被、动物等自然因素都发生不同程度且往往不可逆的变化。"},{"h":"2. 空间上的平面和立面特征","t":"城市环境各要素在城市平面和高度上有形地表现。平面上表现为用地形态，可用位置、距离、方向描述，常见方形、圆形、星形、长条形；立面上表现为城市轮廓、人造地貌。原因是城市用地扩展和建设发展具有方向性和距离衰减特点。"},{"h":"3. 地域层次特征","t":"城市环境是地域综合体，以不同活动为中心形成居住环境、工业环境、商业环境等地域子环境，并可细分到具体用地。原因是不同功能活动的物质环境存在地域分异，人工化程度不同。"},{"h":"4. 污染特征","t":"与自然环境相比，城市环境在组成、结构和影响因素上变化很大，表现为热岛效应、干岛效应、径流量增加、大气与水体污染等。原因是下垫面改变、人为热与污染物集中排放、植被覆盖减少。"}],"pit":""},{"id":"857-b-52","title":"城市绿地系统质量评价包括哪些内容？","type":"简答","category":"重点","score":10,"source":"2022·2024·2025","full":[{"h":"1. 总述","t":"城市绿地系统评价是应用生态学原理和方法，遵循以人为本和可持续发展思想，对绿地系统结构的合理性、景观环境的宜人性、生态过程的连续性与稳定性等作出评价，内容包括四个方面："},{"h":"2. 绿地系统整体格局的合理性","t":"从城市整体水平收集图件，借助地理信息技术分析整体绿化状况与绿地指标，并与国家有关标准和绿化先进城市比较；分析景观结构和空间格局、绿地布局是否合理，主要绿色廊道分布是否有利于缓解热岛效应和其他城市环境问题，空间连接度和生态连通性如何，城市内部绿地与周边绿地关系是否密切，各类公园绿地与居民区等人口集中区的空间关系是否体现以人为本。"},{"h":"3. 绿色廊道和绿地斑块的结构分析","t":"绿地比例是否达标，植物搭配和带状空间配置是否合理；分析各项绿地指标的服务半径、内部结构与配置、植物种类及生长状况、群落演替与群落结构等。"},{"h":"4. 生物多样性的分析","t":"分析植物种类的组成与分类、树木与其他植物的组成结构；确定主要绿化树种并分析其生长状况和绿化效果；分析当地特色和珍稀种类的数量、分布与生长状态。"},{"h":"5. 各类绿地及绿化管理评价","t":"分别对公共绿地、道路绿化、居住区绿化、单位绿化等进行分析，从绿地空间配置、种类组成、群落结构、生长状况、管护情况及园林建设与管理等方面总结优点和经验，分析问题与不足，提出改进措施。"}],"pit":""},{"id":"857-b-53","title":"光周期现象在园林植物培育中的应用。","type":"简答","category":"重点","score":10,"source":"2023","full":[{"h":"1. 总述","t":"光周期现象是植物生长发育对日照长度规律性变化的反应，在园林植物培育中应用广泛："},{"h":"2. 花期调控","t":"短日照植物可通过遮光缩短光照使其提前开花，如一品红8月上旬开始遮光，每天给光约8～10小时，经45～55天即可提前开花；菊花同样通过遮光提前至目标花期。长日照植物则可通过人工补光延长光照促其开花，或对短日照植物夜间补光以推迟花期，实现“不时之花”。"},{"h":"3. 引种驯化","t":"引种前须明确植物的光周期类型，判断其在本地日照条件下能否正常开花结实，避免盲目引种造成只长不开花。"},{"h":"4. 育苗与营养生长调控","t":"利用长日照促进营养生长、短日照促进加粗和养分积累的特性，控制苗木高生长和株形，培育优质壮苗。"},{"h":"5. 休眠与抗性调控","t":"短日照可诱导芽进入休眠、枝条成熟木质化，提高苗木越冬抗寒能力，用于苗木贮藏和抑制萌芽。"},{"h":"6. 杂交育种","t":"通过光照处理调节父母本花期，使花期相遇，便于杂交授粉。"}],"pit":""},{"id":"857-b-54","title":"碳中和与碳达峰的关系。","type":"简答","category":"重点","score":10,"source":"2024","full":[{"h":"1. 碳达峰","t":"指碳排放量达到峰值，即二氧化碳排放量由增转降的历史拐点。碳排放量在一定程度上反映发展速度，争取早日碳达峰即争取早日完成建设任务。"},{"h":"2. 碳中和","t":"指企业、团体或个人测算在一定时间内直接或间接产生的温室气体排放总量，通过植树造林、节能减排等形式，抵消自身产生的二氧化碳排放量，实现二氧化碳“零排放”，推动绿色生活、生产，实现全社会绿色发展。"},{"h":"3. 二者关系","t":"碳达峰是碳中和的前提和必经阶段，碳中和是碳达峰的最终目标。先达峰、后中和，时间上前后衔接；达峰峰值越低、达峰时间越早，碳中和的压力越小、实现越容易；碳中和又反过来要求达峰后排放量持续快速下降。"},{"h":"4. 对园林绿化的意义","t":"城市绿地通过植物固碳、节能减排发挥碳汇作用，是低成本实现碳中和的重要途径。"},{"h":"5. 总述","t":"第三部分　第 21—30 题　简答与论述"}],"pit":""},{"id":"857-b-55","title":"简述园林植物对高温的适应","type":"简答","category":"重点","score":10,"source":"2026","full":[{"h":"1. 总述","t":"园林植物对高温的适应主要表现在形态和生理两方面："},{"h":"2. 密生茸毛和鳞片","t":"植物体表面生有密集的茸毛、鳞片，能阻挡和反射一部分阳光，减少对热量的吸收。"},{"h":"3. 体色浅、叶面反光","t":"植物体呈白色、银白色，叶片革质发亮，能反射一部分阳光，降低体温。"},{"h":"4. 叶片角度与姿态调节","t":"有些植物叶片角度发生变化，或在高温条件下叶片折叠、卷曲，减少接受阳光的面积。"},{"h":"5. 木栓层隔热","t":"一些树木的树干和根茎有厚的木栓层，具绝热和保温作用，保护形成层免受高温伤害。"},{"h":"6. 总述","t":"（生理适应补充：高温时蒸腾加强以散热降温，水分不足时关闭气孔减少失水；细胞渗透调节提高原生质抗热性；以休眠逃避高温期。）"}],"pit":""},{"id":"857-b-56","title":"简述城市水环境的特征","type":"简答","category":"重点","score":10,"source":"2015·2016·2018·2026","full":[{"h":"1. 城市降水量大","t":"城市热岛形成上升气流，高层建筑阻碍气流产生涡旋堆积，加上污染物提供丰富凝结核，使城市降水多于郊区，形成“雨岛效应”。"},{"h":"2. 城市径流量增加","t":"植被破坏、自然土面少、不透水面积大，降水下渗减少，地表径流迅速形成并被排水系统排走。"},{"h":"3. 城市空气湿度低、云雾多","t":"不透水地面使雨后迅速干燥、植物覆盖少、蒸散量小，空气湿度低于郊区，形成“干岛效应”；同时污染物凝结核多、下垫面粗糙降低风速，利于雾的形成，大气浑浊度高，形成“浑浊岛效应”。"},{"h":"4. 城市水污染严重","t":"污染物排放超过水体自净能力，出现富营养化、有毒物质污染、热污染和需氧物质污染，地下水也受污染。"},{"h":"5. 城市水资源短缺","t":"包括资源性缺水（北方、西北地区水资源本底不足）、水质性缺水（南方城市水源受污染）和工程性缺水。"}],"pit":""},{"id":"857-b-57","title":"判定景观基质（本底）的依据是什么？","type":"简答","category":"重点","score":10,"source":"2014·2026","full":[{"h":"1. 总述","t":"基质（本底）是景观中面积最大、连接度最高、对景观功能控制作用最强的景观要素。判定依据有三："},{"h":"2. 相对面积","t":"一般认为相对面积最大、占景观面积比例最高的景观要素类型即为基质。"},{"h":"3. 连通性","t":"某些组分面积虽不是最大，但在景观中连通程度很高，对景观的物流、能流和物种传输有重要影响，也可视为基质。"},{"h":"4. 动态控制作用","t":"对景观动态变化起控制作用最强、能在很大程度上决定景观整体格局与过程的要素为基质。"},{"h":"5. 总述","t":"三者综合判断，其中相对面积是首要依据。"}],"pit":""},{"id":"857-b-58","title":"斑块大小及形状指数对其生态作用的影响","type":"简答","category":"重点","score":10,"source":"2026","full":[{"h":"1. 总述","t":"（一）斑块大小的影响："},{"h":"2. 要点","t":"斑块越大，内部生境面积越大，结构和功能稳定性越高；斑块内部与周围斑块或基质之间物质、能量、信息的相对交换率低，内部受周围影响越小。"},{"h":"3. 大斑块资源数量多、有效性高，内部生境与边缘带比例大，能容纳更多物种、满足内部种生存需要（岛屿效应","t":"面积越大，容纳物种数越多）。"},{"h":"4. 要点","t":"小斑块边缘效应强、边缘种比例高，内部生境少，易受干扰，但可作为物种迁移的“踏脚石”。"},{"h":"5. 总述","t":"（二）斑块形状的影响："},{"h":"6. 要点","t":"对一定面积的斑块，圆形斑块的周长面积比最小，内部面积最大、边缘面积最小，结构和功能稳定性最高。"},{"h":"7. 要点","t":"形状指数可用 $D=P/(2\\sqrt{\\pi A})$ 表示（P为周长，A为面积），D越接近1越接近圆形，D越大说明形状越狭长复杂、边缘带比例越高、与基质交换越强，有利于物种迁移和边缘种生存，但内部生境减少。"},{"h":"8. 要点","t":"因此规划中核心保护区宜用紧凑圆形大斑块，而生物廊道则利用狭长形状增加连通性。"}],"pit":""},{"id":"857-b-59","title":"日本宫胁昭环境保护林的营建理论基础与步骤","type":"简答","category":"重点","score":10,"source":"2015·2019","full":[{"h":"1. 总述","t":"（一）理论基础：主要是生态学的演替理论。由裸地自然演替到顶级群落需很长时间，但若人工提供顶级群落优势种所需的生境条件，让演替前期群落为后期群落创造适宜环境，经过若干阶段群落的接二连三替代，最后达到顶级群落，就能大大缩短演替时间。其核心是依据当地潜在植被（乡土顶极群落）重建植被，采用改造土壤、收集当地乡土树种种子、营养钵育苗等措施，在较短时间内建立适应当地气候的稳定顶极群落。"},{"h":"2. 总述","t":"（二）步骤："},{"h":"3. 潜在植被类型调查","t":"调查当地残存自然植被和立地条件，确定该地潜在（顶极）植被类型及其优势种。"},{"h":"4. 优势种的选择和群落的重建","t":"选择乡土顶极群落优势种，采集种子、营养钵育苗，改造土壤后按适宜密度和组合栽植，模拟自然群落结构与演替序列。"},{"h":"5. 养护阶段","t":"栽后除草、浇水、防治病虫，保证幼苗成活和群落顺利发育。"},{"h":"6. 总述","t":"（三）意义：利用群落演替原理，可在较短时间内形成结构稳定、自我维持的城市植被，是城市植被恢复重建的重要方法。"}],"pit":""},{"id":"857-b-60","title":"城市生态系统面临的生态环境问题体现在哪些方面？","type":"简答","category":"重点","score":10,"source":"2017·2019","full":[{"h":"1. 生态环境破坏、环境质量下降","t":"自然生境被破坏，植被大面积消失，生境破碎化、片段化，生物多样性下降。"},{"h":"2. 城市气候变化、大气污染严重","t":"热岛效应普遍存在，悬浮颗粒物多使太阳辐射减弱、降水增多；大气污染包括光化学烟雾、酸沉降、汽车尾气污染等。"},{"h":"3. 城市水污染严重、水资源不足","t":"水体富营养化和有毒物质污染严重，地下水受污染；存在资源性、水质性和工程性缺水。"},{"h":"4. 城市土壤退化","t":"土壤污染、紧实、贫瘠化、含水量低，理化性质与自然土壤差异大。"},{"h":"5. 城市绿地不足、生物多样性低","t":"绿地布局不均、绿地隔离、缺乏绿色廊道，不能形成连贯绿地系统，植物种类不丰富。"},{"h":"6. 其他","t":"固体废弃物污染、噪声污染和光污染突出，人口密集、交通拥挤、能源与资源消耗大。"}],"pit":""},{"id":"857-b-13","title":"什么是演替？论述旱生生物群落演替的过程","type":"论述","category":"重点","score":15,"source":"2021","full":[{"h":"1. 总述","t":"（一）演替的概念：演替是在植物群落发展变化过程中，由低级到高级、由简单到复杂，一个阶段接着一个阶段、一个群落代替另一个群落的自然演变现象。群落形成须经迁移、定居、竞争三个过程。"},{"h":"2. 总述","t":"（二）旱生演替：以裸岩等陆生干旱缺水基质为基础发生的演替，称旱生演替，其演替系列为："},{"h":"3. 地衣阶段","t":"裸岩上首先出现壳状地衣，分泌有机酸分解岩石，并积累少量有机质形成薄层土壤，为其他生物定居创造条件；随后出现叶状、叶状地衣，此阶段是整个系列中持续时间最长的过程。"},{"h":"4. 苔藓阶段","t":"地衣积累的薄层土壤上出现苔藓，苔藓能保持水分、加速岩石风化和土壤形成，积累的土壤更多，持续时间也较长。"},{"h":"5. 草本植物阶段","t":"土壤条件改善后草本植物定居，先为一年生、后为多年生，根系和残体使土壤有机质、肥力与保水能力显著提高，形成草本群落。"},{"h":"6. 灌木阶段","t":"草本群落使环境趋于荫蔽湿润，灌木侵入并逐渐占据优势，群落出现层次结构，为耐荫乔木幼苗生长创造条件。"},{"h":"7. 乔木（森林）阶段","t":"乔木种子在灌木层下萌发、生长，逐渐上升至林冠层，最终形成结构复杂、相对稳定的森林群落，达到与当地气候相适应的顶极群落。"},{"h":"8. 总述","t":"（三）实质与意义：整个过程是生物不断改造生境、生境反过来选择生物的过程——土壤由无到有、由薄到厚，群落由矮小简单到高大复杂，对环境的改造作用不断增强，直至形成稳定的顶极群落。掌握该规律可指导困难立地（裸岩、边坡、废弃地）的植被恢复与城市植被重建。"}],"pit":""},{"id":"857-b-14","title":"详述城市绿地系统的生态功能","type":"论述","category":"重点","score":15,"source":"2021","full":[{"h":"1. 总述","t":"城市绿地是城市生态系统的绿色基础设施，其生态功能主要体现在："},{"h":"2. 改善城市环境","t":""},{"h":"3. 总述","t":"a 净化空气：吸收CO₂释放O₂，吸收SO₂、氟化物等有害气体，滞留和吸附粉尘，减少细菌；"},{"h":"4. 总述","t":"b 净化水体与土壤：植物吸收、富集水体中的溶解物质，根系与土壤微生物降解污染物，植物修复可净化污染土壤；"},{"h":"5. 总述","t":"c 改善城市小气候：树冠吸收反射太阳辐射产生减光效应，蒸腾消耗热量实现降温增湿，减弱热岛效应和干岛效应，绿化覆盖率50％以上可基本抵消热岛增温；"},{"h":"6. 总述","t":"d 降低城市噪音：枝叶多层反射和吸收声波，减弱噪声。"},{"h":"7. 涵养水源、保持水土","t":"林冠截留降水，减弱雨水对地表的冲刷；枯枝落叶和地被层吸水，使水分缓慢下渗形成地下潜流，枯水期补给河流；森林土壤入渗率高，减少地表径流，防止水土流失。"},{"h":"8. 保障城市生态安全","t":"防火避灾（隔离带、避难场所）、防风固沙（降低风速、根系固土）、保持水土、防御放射性污染和备战防空。"},{"h":"9. 维护城市生物多样性","t":"多样化的植物种类和复杂的垂直、水平结构为鸟类、昆虫等提供食物来源和栖息地，增强景观稳定性，有利于群落演替顺利进行。"},{"h":"10. 提供生态系统服务","t":"供给、调节、文化、支持四大服务，并具美化环境、休闲游憩、科普教育等社会功能及直接、间接经济效益。"}],"pit":""},{"id":"857-b-15","title":"论述大熊猫国家公园建设应采取的措施","type":"论述","category":"重点","score":15,"source":"2021","full":[{"h":"1. 科学划定功能分区","t":"按核心保护区与一般控制区差别化管理，核心区严格保护、禁止人为干扰，一般控制区允许有限科研、教育和生态旅游。"},{"h":"2. 健全统一管理体制","t":"整合原有分散的自然保护区、林场等，实行统一规划、统一保护、统一管理，明确权责，完善法规与执法监督。"},{"h":"3. 修复栖息地与建设生态廊道","t":"针对栖息地破碎化，退耕还林还草、封山育林，恢复竹林与阔叶林，建设连通孤立种群的生态廊道，保证基因交流。"},{"h":"4. 加强科研监测","t":"建立天空地一体化监测网络与资源数据库，开展大熊猫种群动态、伴生物种、疫源疫病监测和科学研究。"},{"h":"5. 推进社区共建共管","t":"引导当地居民转产转业，发展生态旅游、特许经营和生态补偿，减少资源依赖，实现保护与发展共赢。"},{"h":"6. 严格管控人为干扰","t":"控制道路、采矿、水电等开发建设，限制游客容量，防治环境污染和人为疫病传播。"},{"h":"7. 开展科普教育与社会参与","t":"建设自然教育基地，鼓励志愿者和社会资本参与，加强国际合作与宣传。"}],"pit":""},{"id":"857-b-16","title":"论述城市光环境对园林植物的生态作用","type":"论述","category":"重点","score":15,"source":"—","full":[{"h":"1. 光照度减弱对光合与生长的影响","t":"城市大气悬浮颗粒物削弱太阳辐射，建筑遮挡和树冠自身减光使到达植物群体的光照度降低，光合速率与同化物积累减少，植株生长量下降、枝干细弱，耐阴种类逐渐占优势。"},{"h":"2. 光照分布不均导致形态畸形","t":"建筑高度与街道宽度之比（街道狭窄指数N=H/D）越大，街道接收太阳辐射越弱；建筑物附近树木受光不均匀，向光侧生长快，易造成偏冠、树冠偏斜，影响树形与景观效果。"},{"h":"3. 光质变化影响形态建成","t":"玻璃幕墙反射光、人工光源改变光谱组成；红光有利于糖类合成、促进伸长，蓝紫光抑制伸长、促进花青素形成和矮化，从而影响植物的形态建成、向光性和色素形成。"},{"h":"4. 光污染干扰光周期与物候","t":"人造白昼污染延长夜间有效光照，使短日照植物花芽分化受抑、开花推迟，落叶延迟、枝条不能及时成熟木质化，抗寒性下降，并干扰昆虫传粉等生态关系；白亮污染（眩光、聚焦光）可灼伤叶片。"},{"h":"5. 促使植物分化出不同光照生态类型","t":"植物长期适应不同光照条件形成阳性、中性、阴性植物，城市管理者应据此进行植物配置——阳性植物置于开敞向阳处，阴性植物用于建筑北侧与林下，并减少大功率强光源、增加绿地以改善城市光环境。"},{"h":"6. 总述","t":"第四部分　第 31—40 题　论述题"}],"pit":""},{"id":"857-b-17","title":"论述碳达峰、碳中和目标下风景园林实践的任务和措施","type":"论述","category":"重点","score":15,"source":"2022","full":[{"h":"1. 总述","t":"（一）任务：减轻当前形势下二氧化碳过度排放的问题，缓解城市化带来的生态环境压力，通过园林绿地增强碳汇、降低碳排放，实现城市的可持续发展。这是现代园林的发展方向，也是园林生态学的实践归宿。"},{"h":"2. 总述","t":"（二）措施："},{"h":"3. 节能减耗","t":"设计上尽可能降低对自然资源（水土、植被、材料）的损耗与破坏，实现天然利用，兼顾观赏效果与生态效益。"},{"h":"4. 遵循自然规律","t":"从材料使用、植物选择搭配到整体设计减轻对自然的不良影响，营造健康环保的人居环境。"},{"h":"5. 发展立体绿化","t":"以垂直绿化、立体绿化、屋顶绿化提高空间与土地利用率，增加单位面积绿量从而增加碳汇。"},{"h":"6. 加强碳中和园林设计","t":"完善全生命周期碳排放管控体系，在施工、运行和管理各阶段控制碳排放，实现零排放、促进碳平衡。"},{"h":"7. 提高低碳资源利用率","t":"高效利用清洁自然能源；选择植物时除抗旱性外，重点考量固碳释氧能力。"},{"h":"8. 节水节能技术","t":"借鉴喷灌、滴灌、地膜覆盖与废弃水回收循环利用技术，减少水资源浪费。"},{"h":"9. 总述","t":"（三）小结：以增加碳汇（绿地数量与质量）与减少碳排（设计、施工、养护全过程）两条主线，把“双碳”目标落实在规划、设计、建设与管理的每个环节。"}],"pit":""},{"id":"857-b-18","title":"论述植物在生态系统功能中的作用","type":"论述","category":"重点","score":15,"source":"2023","full":[{"h":"1. 总述","t":"（一）植物是生态系统的生产者，是系统存在的基础。绿色植物通过光合作用固定太阳能、把无机物合成有机物，是生态系统能量流动的起点和物质循环的枢纽，初级生产量决定系统的承载力。"},{"h":"2. 总述","t":"（二）为消费者提供食物与栖息地：植物直接或间接供养草食动物、肉食动物，其层次结构和物种组成决定动物群落的多样性与食物网复杂程度。"},{"h":"3. 总述","t":"（三）调节大气成分、固碳释氧：吸收CO₂释放O₂，维持大气中氧与二氧化碳的平衡，是减缓温室效应的主要途径。"},{"h":"4. 总述","t":"（四）涵养水源、保持水土：林冠截留降水，地被物层吸水，土壤下渗调蓄，并对融雪起调节作用；根系固着土壤，减少雨水冲刷和风蚀。"},{"h":"5. 总述","t":"（五）净化环境：吸收SO₂等有害气体、滞留粉尘、杀灭细菌；吸收富集水体中溶解物质（富集量可达水中浓度的几十至几千倍），代谢解毒并竞争抑制藻类，净化水质；还能降解土壤污染物。"},{"h":"6. 总述","t":"（六）改善小气候：树冠减光、蒸腾降温增湿，减弱热岛与干岛效应，阻挡并降低风速。"},{"h":"7. 总述","t":"（七）活化土壤与养分循环：枯枝落叶归还养分，增加土壤生物，改善土壤理化性质。"},{"h":"8. 总述","t":"（八）维持生物多样性：多样化的植被提供多样生境，保障演替顺利进行，增强群落抗干扰的抵抗力与恢复力。"}],"pit":""},{"id":"857-b-19","title":"根据海绵城市概念，论述海绵城市的意义及措施","type":"论述","category":"重点","score":15,"source":"2023","full":[{"h":"1. 总述","t":"（一）概念：海绵城市是指城市能够像海绵一样，对雨水进行“渗、滞、蓄、净、用、排”，实现雨水的自然积存、自然渗透、自然净化，把快排模式转为“渗滞蓄净用排”结合，从而缓解内涝、削减径流污染、修复水生态的城市建设模式。"},{"h":"2. 总述","t":"（二）意义："},{"h":"3. 削减地表径流、缓解城市内涝","t":"城市径流量大且集中，下凹绿地、透水地面使雨水就地入渗滞蓄，降低峰值流量。"},{"h":"4. 补充地下水、修复水生态","t":"增加下渗量，恢复自然水文循环，缓解地下水位下降。"},{"h":"5. 削减面源污染、改善水质","t":"通过绿地、湿地、植草沟的过滤吸附净化初期雨水，减少污染物入河。"},{"h":"6. 改善城市气候","t":"增加蒸发散与水体面积，缓解干岛效应与热岛效应。"},{"h":"7. 节约水资源","t":"雨水收集回用于绿化浇灌、道路冲洗，缓解资源性与水质性缺水。"},{"h":"8. 降低建设成本、提升景观品质","t":"减少管网与调蓄设施投入，把灰色设施变为绿色景观。"},{"h":"9. 总述","t":"（三）措施："},{"h":"10. 源头减排","t":"下凹式绿地、雨水花园、植草沟、生物滞留设施、透水铺装与透水路面。"},{"h":"11. 过程控制","t":"绿色屋顶、垂直绿化滞蓄雨水；合理竖向设计，引导雨水进入绿地而非直接入管。"},{"h":"12. 末端调蓄","t":"雨水塘、人工湿地、景观水体调蓄与净化，与公园绿地结合。"},{"h":"13. 雨水回用","t":"蓄水池、雨水罐收集用于绿化浇灌与水景补水。"},{"h":"14. 保护自然水系","t":"禁止填埋河道湿地，恢复自然岸线与河湖连通，保留城市周边的调蓄空间。"},{"h":"15. 规划管控","t":"把年径流总量控制率、径流污染削减率纳入绿地系统与排水专项规划；绿地系统布局与汇水分区相衔接。"},{"h":"16. 总述","t":"注：资料中只讲了城市水环境特征（降水大、径流增加、干岛效应、水污染、缺水），“海绵城市”的名词与措施属通用知识补充。"}],"pit":""},{"id":"857-b-20","title":"论述生物多样性及在建设公园城市中的应用","type":"论述","category":"重点","score":15,"source":"2023","full":[{"h":"1. 总述","t":"（一）生物多样性：指生命有机体及其赖以生存的生态综合体的多样化和变异性，包括遗传多样性、物种多样性、生态系统多样性和景观多样性四个层次。"},{"h":"2. 总述","t":"（二）公园城市内涵：以人民为中心、以生态文明为引领的城市建设模式，体现公平性与包容性，载体在“园”（绿色公共空间的数量与质量），落脚点在“城”（发展形态科学、规划合理、有特色），成果体现在“市”（人、自然、城市和谐，人城境业高度统一）；思路上由“产—城—人”转向“人—城—产”，由“城市中建公园”转向“公园中建城市”。"},{"h":"3. 总述","t":"（三）应用："},{"h":"4. 规划层面","t":"把生物多样性保护纳入公园城市规划，构建全域公园体系与绿色生态网络，使绿地由孤立走向系统。"},{"h":"5. 植物配置层面","t":"丰富植物种类，以乡土树种为主，营建近自然植物群落，模拟地带性顶极群落结构与演替序列。"},{"h":"6. 保护小生境斑块","t":"保护城市中具有栖息地作用的生境斑块不被占用，并保护其周边环境及与外界、大斑块的连通性。"},{"h":"7. 要点","t":"保护周边自然景观要素与湿地、河流廊道，建立完整的区域保护体系，保证空间与生态连通性。"},{"h":"8. 要点","t":"建设或恢复大型绿地斑块、增加乔木林地面积，以岛屿生物地理学原理满足内部种对生境面积的需求。"},{"h":"9. 要点","t":"提高景观异质性与食源、蜜源植物配置，为鸟类、昆虫提供栖息与食物，增强景观稳定性与美学效果。"},{"h":"10. 管理层面","t":"制定保护计划、规范与标准，建立监测网络和资源信息数据库，开展示范工程、科普教育与公众参与。"},{"h":"11. 总述","t":"（四）小结：生物多样性既是公园城市建设的生态基础，也是衡量其质量的核心指标；保护与利用结合，才能实现人城境业和谐统一。"}],"pit":""},{"id":"857-b-21","title":"以酸雨为例，论述大气污染对植物的负面影响","type":"论述","category":"重点","score":15,"source":"2024","full":[{"h":"1. 总述","t":"（一）酸雨概念与形成：pH＜5.6的雨、雪、霜、雾等大气降水称酸雨（酸沉降）；主要是工业排放的硫氧化物和氮氧化物与大气中的氧和水分子发生化学反应生成硫酸、硝酸，随降水落到地面的过程，会酸化土壤和水体，腐蚀性强。"},{"h":"2. 总述","t":"（二）直接影响："},{"h":"3. 损害叶片表皮结构","t":"腐蚀角质层和蜡质层，破坏表皮细胞与栅栏细胞，叶面出现伤斑、失绿，光合作用下降，导致整个生态系统能量流动减少、功能降低。"},{"h":"4. 要点","t":"引起叶细胞中毒甚至坏死，同时使蒸发和蒸腾作用异常增强，植物对外界不利因素的敏感性增大。"},{"h":"5. 干扰生理代谢","t":"酶活性受抑、养分流失，个体生长缓慢、产量下降，严重时整株死亡。"},{"h":"6. 总述","t":"（三）间接影响："},{"h":"7. 土壤酸化","t":"盐基离子淋失、铝被活化而毒害根系，磷等养分有效性下降，土壤微生物与固氮活动受抑。"},{"h":"8. 水体酸化","t":"湖泊河流pH下降，鱼类与水生生物减少，水生生态系统退化。"},{"h":"9. 植被生态系统结构与功能破坏","t":"敏感种被淘汰、种类组成简化、群落退化，抗性下降后易暴发病虫害。"},{"h":"10. 总述","t":"（四）与其他大气污染的协同：与SO₂、光化学烟雾（臭氧）、固体颗粒物共同作用，颗粒物堵塞气孔妨碍光合、呼吸和蒸腾，毒性物质溶入叶内加重伤害；伤害程度取决于污染物浓度与接触时间（剂量），超过临界剂量（伤害阈值）即产生可见伤害。"},{"h":"11. 总述","t":"（五）应对：控制硫、氮排放与清洁能源替代；园林中选择抗性强的树种、营造复层混交群落；加强监测与指示植物应用。"}],"pit":""},{"id":"857-b-22","title":"论述城市热岛效应的形成原因及园林应对措施","type":"论述","category":"重点","score":15,"source":"2025","full":[{"h":"1. 总述","t":"（一）概念：城市气温高于郊区气温的现象，增温影响范围可达周围郊区；晴朗无风干燥的夜晚最易形成，落日后2—3小时热岛强度最大，冬季＞秋季＞夏季＞春季。"},{"h":"2. 总述","t":"（二）形成原因："},{"h":"3. 下垫面反射率小","t":"城市绿地少、建筑材料反射率低于植被，吸收太阳辐射多。"},{"h":"4. 建筑材料热容量、热导率大","t":"白天吸收积聚大量辐射热，地面温度高，供给大气的热量比郊区多。"},{"h":"5. 要点","t":"CO₂和污染物覆盖层增强大气逆辐射，保温作用加强。"},{"h":"6. 人为热释放","t":"工业、交通、空调采暖与人体散热。"},{"h":"7. 要点","t":"建筑密集、通风不良，且不透水面积大、蒸发散热少（潜热交换弱）。"},{"h":"8. 总述","t":"（三）园林应对措施："},{"h":"9. 削减人为热","t":"以植物遮荫降低空调能耗，减少硬质铺装与高耗能设施。"},{"h":"10. 减少吸收净辐射","t":"提高绿化覆盖率（覆盖率50％以上可基本抵消热岛增温），增加乔木比例与冠层郁闭度，推广屋顶绿化、立体绿化提高三维绿量。"},{"h":"11. 增加潜热交换与光能转化","t":"增加水体、喷泉、雾喷，使用透水地面与下凹绿地保蓄水分，加强蒸腾蒸发降温。"},{"h":"12. 构建通风廊道","t":"沿主导风向留出开敞绿地、河流廊道与绿道，引郊區冷空气入城，避免连片高密建筑堵塞。"},{"h":"13. 均衡布局","t":"按服务半径均匀布置公园绿地，把大块绿地与小型斑块、廊道连成网络，重点改善高密度老旧城区。"},{"h":"14. 总述","t":"（四）小结：热岛是下垫面、人为热与绿地不足共同作用的结果，园林绿化是成本最低、效益综合的缓解途径。"}],"pit":""},{"id":"857-b-23","title":"论述大熊猫国家公园建设要解决的主要生态学问题","type":"论述","category":"重点","score":15,"source":"2025","full":[{"h":"1. 栖息地破碎化与岛屿化","t":"道路、居民点、生产用地把连续栖息地切割为孤岛状斑块，种群被隔离，基因交流受阻。"},{"h":"2. 种群小、遗传多样性下降","t":"局部种群数量少，存在近交衰退与遗传漂变风险，需满足最小存活种群要求。"},{"h":"3. 食物资源与群落更新问题","t":"主食竹种单一，竹子周期性开花枯死会造成食物短缺；需研究竹类更新与针阔混交林恢复。"},{"h":"4. 群落与生态系统完整性","t":"作为伞护种，其保护依赖完整的山地森林生态系统与伴生物种群落结构。"},{"h":"5. 人为干扰","t":"旅游、放牧、采药、采矿、水电与道路建设的干扰强度与生态承载力控制。"},{"h":"6. 气候变化影响","t":"气温上升使竹子适生区与栖息地向上迁移，适宜生境面积缩小。"},{"h":"7. 病虫害与疫源疫病风险","t":"种群密集或破碎化后抗性下降。"},{"h":"8. 保护与社区发展的矛盾","t":"当地居民生计依赖资源，需通过生态补偿、特许经营、转产转业协调。"},{"h":"9. 监测评估与廊道选址","t":"建立种群与生境监测体系，用岛屿生物地理学与景观连接度理论确定生态廊道位置与斑块规模。"},{"h":"10. 总述","t":"（对策指向：分区管控、栖息地修复与廊道建设、迁地保护辅助、科研监测与社区共建。）"},{"h":"11. 总述","t":"注：资料中无“大熊猫国家公园”专门章节，以上按岛屿生物地理学、栖息地破碎化、最小存活种群、生态廊道等教材原理与国家公园通用要求组织，请对照讲义核实。"}],"pit":""},{"id":"857-b-25","title":"论述生态系统能量流动与物质循环的关系","type":"论述","category":"重点","score":15,"source":"专题","full":[{"h":"1. 总述","t":"（一）区别："},{"h":"2. 能量流动是单向的、逐级递减的","t":"太阳能在食物链中只能一次通过，各营养级按“十分之一定律”递减，最终以热的形式耗散，不能循环利用。"},{"h":"3. 物质循环是往复的、可再利用的","t":"元素由环境进入生物体，经生产者、消费者、分解者最终归还环境，可被反复利用，物质不灭。"},{"h":"4. 总述","t":"（二）联系："},{"h":"5. 物质是能量流动的载体","t":"能量储存在有机物化学键中，随物质的取食、转移而流动，没有物质载体能量无法传递。"},{"h":"6. 能量是物质循环的动力","t":"光合作用固定太阳能，驱动元素由无机态转为有机态；分解者的代谢活动又需能量支持，没有能量输入物质循环就会停止。"},{"h":"7. 要点","t":"二者同时进行、相互依存，共同把生产者、消费者、分解者和非生物环境联结成以营养结构为纽带的整体，是生态系统的基本功能。"},{"h":"8. 二者共同决定生态系统的生产力与稳定性","t":"物质循环不畅（如养分限制）会限制能量固定，能量输入不足则物质循环速率下降。"},{"h":"9. 总述","t":"（三）实践意义：城市绿地既通过植物固定能量（生物量生产），又通过枯落物归还与土壤管理维持养分循环；园林养护中清除枯落物会切断物质循环，长期导致土壤贫瘠、系统不稳定。"}],"pit":""},{"id":"857-b-26","title":"综合应用题：平原高密度城市绿地系统生态评价的内容与方法，及优化对策","type":"综合","category":"重点","score":35,"source":"2026综合","full":[{"h":"1. 总述","t":"（一）评价内容："},{"h":"2. 整体格局的合理性","t":"主要绿色通道是否有利于缓解热岛效应和其他城市问题；城市内部绿地与周边绿地的关系；各类公园与居民聚集区的空间关系是否以人为本。"},{"h":"3. 绿色廊道与绿地斑块结构","t":"绿地比例是否达标，植物搭配与带状空间配置是否合理；各项指标的服务半径、内部结构与配置、植物种类及生长状况、群落结构与演替阶段。"},{"h":"4. 生物多样性","t":"植物种类组成与分类、树木与其他植物组成结构；主要绿化树种的生长状况与绿化效果；当地特色和珍稀种类的数量、分布与生长状态。"},{"h":"5. 各类绿地及管理评价","t":"公共绿地、道路绿化、居住区与单位绿化等，从空间配置、种类组成、群落结构、生长状况、管护情况及建设管理水平评价。"},{"h":"6. （平原高密度城市侧重）生态效益与服务价值","t":"固碳释氧、降温增湿、滞尘减噪、雨水调蓄能力；绿地可达性与公平性。"},{"h":"7. 总述","t":"（二）评价方法："},{"h":"8. 资料收集与遥感解译","t":"用3S技术提取绿地斑块、计算绿地率、绿化覆盖率、人均公园绿地面积等指标，并与国家标准和先进城市比较。"},{"h":"9. 景观格局指数分析","t":"斑块密度、平均斑块面积、形状指数、连通度、聚集度、边缘密度，判断破碎化与连通性。"},{"h":"10. 可达性与公平性分析","t":"缓冲区分析、网络分析评价500米服务半径覆盖率，叠加人口密度识别服务盲区。"},{"h":"11. 生态效益定量","t":"用模型（如i-Tree、CITYgreen类）估算固碳、降温、滞尘、节能量与雨水径流削减；必要时布点实测温湿度与污染物。"},{"h":"12. 生物多样性调查","t":"样方法调查群落种类组成、多样性指数，辅以鸟类、昆虫观测。"},{"h":"13. 综合评价","t":"层次分析法（AHP）确定权重，模糊综合评价或指标打分排序；结合问卷与访谈评价社会满意度。"},{"h":"14. 总述","t":"（三）优化对策（针对平原、高密度、通风差、绿地率低、热岛强、内涝风险高的特点）："},{"h":"15. 增量与存量并举","t":"见缝插绿、拆违建绿、口袋公园与街旁绿地填补服务盲区；“三旧”改造中提高绿地配比。"},{"h":"16. 三维增绿","t":"屋顶绿化、垂直绿化、立交与桥体绿化，提高单位用地绿量。"},{"h":"17. 网络化","t":"以绿道、河流廊道、通风廊道串联大中小斑块，提升连接度，形成“大斑块—廊道—踏脚石”体系；城郊结合部建设大型郊野公园环，满足内部种需要。"},{"h":"18. 近自然化","t":"以乡土树种为主营建复层混交群落，提高抗性与自我维持能力，降低养护成本。"},{"h":"19. 海绵化","t":"下凹绿地、雨水花园、透水铺装，把绿地系统与汇水分区衔接，缓解内涝并增强蒸发降温。"},{"h":"20. 低碳全周期管理","t":"节水灌溉、枯落物还田维持养分循环、修剪废弃物资源化，控制养护碳排放。"},{"h":"21. 机制保障","t":"严格绿线管控与占补平衡，建立生态补偿与监测评估平台，把绿地生态效益纳入城市体检与考核。"},{"h":"22. 总述","t":"（四）小结：评价要“结构—功能—效益—公平”四方面并重，平原高密度城市的优化核心是增加总量、提高连通、均衡布局和提升群落质量。"}],"pit":""},{"id":"857-b-27","title":"简述Logistic增长模型及各参数含义","type":"简答","category":"重点","score":10,"source":"—","full":[{"h":"1. 模型提出","t":"自然界中资源与空间有限，种内竞争、天敌捕食、疾病和气候等构成环境阻力，种群不能无限增长，故须把环境承载力与繁殖率同时考虑，即逻辑斯谛增长模型。"},{"h":"2. 方程","t":"$\\dfrac{dN}{dt}=rN\\left(1-\\dfrac{N}{K}\\right)$"},{"h":"3. 参数含义","t":"$dN/dt$ 为种群变化率；$N$ 为种群大小；$r$ 为种群瞬时增长率（内禀增长率）；$K$ 为环境最大容纳量；$(1-N/K)$ 为环境阻力。"},{"h":"4. 动态","t":"$N<K$ 时 $dN/dt>0$ 种群增长；$N>K$ 时 $dN/dt<0$ 种群衰减；$N=K$ 时 $dN/dt=0$ 达到稳定平衡点。"},{"h":"5. 五个时期","t":"开始期（数量少、增长慢）→加速期（增长加快）→转折期（$N=K/2$ 时增长最快）→减速期（超过 $K/2$ 后减慢）→饱和期（达 $K$ 不再增加），曲线呈“S”形。"},{"h":"6. 意义","t":"是两个相互作用种群增长模型的基础；是畜牧、渔业确定最大持续产量（保持在 $K/2$ 附近）的依据；也是生物资源保护与管理的理论基础。"},{"h":"7. 总述","t":"第五部分　第 41—50 题　专题简答"}],"pit":""},{"id":"857-b-28","title":"简述种群年龄结构和生命表的生态意义","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 总述","t":"（一）年龄结构：指各个年龄级的个体数在种群中的分布情况，用年龄锥体（横柱从下至上表示幼年到老年，宽度表示各龄组个体数或百分比）表示。"},{"h":"2. 增长型（幼年个体多、锥体呈金字塔形）","t":"种群将迅速扩大，出生率大于死亡率。"},{"h":"3. 稳定型（各龄级比例适中）","t":"出生率与死亡率接近，种群数量稳定。"},{"h":"4. 衰退型（幼年个体少、老年多、锥体倒置）","t":"种群数量将下降。"},{"h":"5. 总述","t":"生态意义：年龄结构是预测种群发展趋势、判断种群兴衰的重要依据；研究园林植物的年龄结构，对分析预测园林植物种群的发展趋势、指导更新与抚育有重要价值。"},{"h":"6. 总述","t":"（二）生命表：按年龄或龄级系统记录种群死亡与存活过程的表，分动态生命表（同生群，适于1—2年生或短命植物）、静态生命表（特定时间调查，适于寿命较长的木本植物）和综合生命表。"},{"h":"7. 净生殖率 $R_0$","t":"一个个体一生平均产生的后代数，$R_0>1$ 种群增长、$R_0<1$ 下降，反映种群增殖能力。"},{"h":"8. 生命期望 $e_x$","t":"某龄级个体平均还能存活的年数，反映各龄级的存活前景。"},{"h":"9. K-因子分析","t":"通过逐期比较死亡原因，找出造成种群死亡率变化的关键因子，为种群管理提供依据。"},{"h":"10. 存活曲线分三型","t":"Ⅰ型凸型（接近生理寿命前死亡少）、Ⅱ型对角线（各龄级死亡率相等）、Ⅲ型凹型（幼年期死亡率高）。"},{"h":"11. 总述","t":"生态意义：生命表能定量揭示种群的存活、死亡规律与寿命特征，是种群动态预测和管理的基础。"}],"pit":""},{"id":"857-b-29","title":"简述种群空间格局的类型及成因","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 总述","t":"种群空间格局：种群个体在水平空间的配置状况或分布状况，反映环境因子对个体生存、生长的影响及个体间关系。"},{"h":"2. 随机分布","t":"个体在空间任何位置出现的机会相等，相互独立。成因：环境条件均匀、资源分布均匀、个体间无吸引或排斥、无明显的集群繁殖或种子散布限制。自然界中较少见。"},{"h":"3. 均匀分布","t":"个体间距离大致相等。成因：种内或种间竞争激烈、自疏作用、化感作用、人工等距栽植。"},{"h":"4. 聚集（成群）分布","t":"个体成团成簇分布，是自然界最普遍的格局。成因：环境因素的不均匀性（资源斑块化）、种子散布能力有限（重力落种集中在母树周围）、营养繁殖（根蘖、匍匐茎形成无性系）、动物的活动和人类影响、集群有利于改善小环境和共同防御。"},{"h":"5. 总述","t":"综上，产生空间格局差异的原因可归为：环境因素的不均匀性、动物活动与人类影响、植物自身的生态学与生物学特性（尤其繁殖与散布特性）、竞争能力。"}],"pit":""},{"id":"857-b-30","title":"简述种间关系的主要类型","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 总述","t":"种间关系：生活于同一生境内的所有不同物种之间的关系。按对双方的影响可分为："},{"h":"2. 竞争","t":"具有相似要求的物种争夺有限空间和资源，各方力求抑制对方，常表现为不对称（一方得利一方受害）。严重的可导致竞争排斥（高斯假说：完全的竞争者不能长期共存）。"},{"h":"3. 捕食","t":"一方取食另一方，对被捕食者不利、对捕食者有利，是能量流动的主要通道。"},{"h":"4. 寄生","t":"一方寄居于另一方体表或体内获取营养，寄主受害。"},{"h":"5. 互利共生","t":"双方均获益，如地衣（藻与菌）、根瘤（豆科与根瘤菌）、菌根（真菌与高等植物根）。"},{"h":"6. 偏利共生（偏利作用）","t":"一方获益、另一方基本不受影响，如植物为小兽、鸟类、昆虫提供庇护所。"},{"h":"7. 附生","t":"一方利用另一方身体的一部分作为定居空间，无直接营养关系，对后者基本无不利影响，如兰花附生于乔木枝干。"},{"h":"8. 化感作用","t":"植物向环境释放化学物质，对其它植物产生促进或抑制作用，是一种特殊的种内种间作用方式。"},{"h":"9. 总述","t":"上述关系通过食物网相互联系，共同维持群落结构与功能的稳定。"}],"pit":""},{"id":"857-b-31","title":"简述生态位与生态位分化","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 生态位","t":"是有机体在环境中占据的地位，指一个种群在生态系统中在时间和空间上所占据的位置，及其与相关种群之间的功能关系与作用。不仅包括占有的物理空间，还包括在群落中的功能角色以及在温度、湿度、土壤等环境梯度中的位置。"},{"h":"2. 基础生态位","t":"群落中能为某一物种所栖息的理论最大空间；实际生态位：物种实际占有的生态位空间（因竞争而压缩）。多个环境维度上的生态位称超体积生态位。"},{"h":"3. 生态位宽度与重叠","t":"宽度反映物种利用资源的多样化程度；重叠越大，种间竞争越激烈。"},{"h":"4. 生态位分化","t":"生态位相同的两个物种不能长期共存（竞争排斥原理／高斯假说），若要长期共存必然导致生态位分化，即在资源利用方式、时间、空间上产生差异。"},{"h":"5. 分化的生态意义","t":"避免种间激烈竞争、避免弱者被淘汰；使各物种保持相对稳定，维持群落稳定性；使资源利用趋于互补，充分有效利用环境资源并保持较高生产力——多物种组成的森林群落比单一群落更能有效利用资源、更稳定。"},{"h":"6. 应用","t":"引种时新引入种应与当地土生种生态位有差异（符合 $d/w>1$，即种内竞争强度大于种间竞争强度），或引入适合当地“空生态位”的物种，否则易被排挤。"}],"pit":""},{"id":"857-b-32","title":"简述植物群落的组成与结构","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 总述","t":"（一）种类组成："},{"h":"2. 优势种","t":"对群落结构和群落环境的形成有明显控制作用的植物种；优势层的优势种称建群种。"},{"h":"3. 要点","t":"其余为亚优势种、伴生种、稀有种（偶见种）。"},{"h":"4. 数量特征","t":"多度（个体数目的估测指标）、密度、盖度（投影面积占样地面积百分比，林业用郁闭度）、频度（出现的样方数占样方总数的百分比）、显著度、重要值等，用于综合衡量各种群在群落中的地位。"},{"h":"5. 总述","t":"（二）结构："},{"h":"6. 生活型与层片","t":"生活型是生物对环境适应形成的外貌形态；层片是相同生活型和相似生态要求的植物种的组合，各层片占据一定时空并形成不同结构特征。"},{"h":"7. 垂直结构——成层现象","t":"群落中各生物为充分利用营养空间而形成的垂直分层结构，是自然选择的结果，显著提高植物利用环境资源的能力、缓解对营养空间的竞争。"},{"h":"8. 水平结构——镶嵌性","t":"层片在二维空间上不均匀配置，使群落外貌呈斑块相间排列的现象。"},{"h":"9. 时间结构——季相","t":"随气候季节性交替，群落呈现不同外貌的现象。"},{"h":"10. 群落交错区与边缘效应","t":"两个或多个群落之间的过渡区域为交错区，其种数及一些种的密度增大的趋势称边缘效应。"}],"pit":""},{"id":"857-b-33","title":"简述群落演替的类型与顶极群落","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 总述","t":"（一）演替：一定地域的植物群落发生变化而形成其他植物群落、被其他群落类型所取代的过程，须经迁移、定居、竞争。"},{"h":"2. 总述","t":"（二）类型："},{"h":"3. 按起始基质","t":"原生演替（从裸岩、裸地、水面开始，如旱生演替系列、水生演替系列）；次生演替（原有植被破坏后发生，如火烧、采伐、弃耕地）。"},{"h":"4. 按演替方向","t":"进展演替（结构由简单到复杂、物种由少到多、不稳定趋向稳定）；逆行演替（结构简单化、生产力下降、群落旱生化）。"},{"h":"5. 按群落代谢特征","t":"自养性演替（生物积累越来越多，如裸岩—地衣—草本—灌木—乔木）；异养性演替（有机质随演替减少，如有机污染水体）。"},{"h":"6. 按主导因素","t":"内因演替（植物改变环境引起）；外因（异发）演替，包括火成、气候性、土壤性、动物性和人为演替。"},{"h":"7. 按持续时间与空间","t":"世纪演替、长期演替、快速演替。"},{"h":"8. 总述","t":"（三）顶极群落：演替系列最终达到的、与当地环境相适应且相对稳定的群落。"},{"h":"9. 单元顶极学说","t":"同一气候区内只能有一个顶极群落，其特征完全由当地气候决定，又称气候顶极，所有演替系列最终趋向同一顶极。"},{"h":"10. 多元顶极学说","t":"除气候外，土壤、地形、火、动物等也可形成稳定群落，一个区域可有多个顶极。"},{"h":"11. 顶极格局学说","t":"环境梯度连续变化，顶极群落相应呈连续变化的镶嵌格局，种群沿梯度分布。"}],"pit":""},{"id":"857-b-34","title":"简述生物多样性及其层次","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 生物多样性","t":"指生命有机体及其赖以生存的生态综合体的多样化和变异性，即生命形式的多样化、各种生命形式之间及其与环境之间的多种相互作用，以及各种生物群落、生态系统及其生境与生态过程的复杂性。"},{"h":"2. 遗传多样性","t":"种内基因与遗传变异的丰富程度，是物种适应环境和进化的基础。"},{"h":"3. 物种多样性","t":"一定区域内物种的丰富程度及分布的均匀性。"},{"h":"4. 生态系统多样性","t":"生态系统类型、结构与功能的多样化，以及生境的多样性。"},{"h":"5. 景观多样性","t":"景观要素在类型、结构与空间格局上的多样性。"},{"h":"6. 意义","t":"生物多样性增加景观稳定性（增强抵抗力与恢复力）、为其他生物提供栖息地、有利于演替顺利进行、增强美学与视觉效果。"},{"h":"7. 保护措施","t":"加强管理（规划、规范、法律体系）；建立监测系统与资源数据库；开展保护与利用示范工程；加强教育与培训；具体包括保护小生境斑块、保护周边自然景观要素与湿地河流廊道、提高生境斑块连通性、建设和恢复大型绿地斑块、迁地保护与种质保存。"}],"pit":""},{"id":"857-b-35","title":"简述生态系统能量流动与生态金字塔","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 总述","t":"（一）能量流动：能量由太阳辐射输入，经生产者固定为化学能，沿食物链（捕食食物链、腐生食物链）在各营养级间传递，最终以热的形式耗散。"},{"h":"2. 总述","t":"特点："},{"h":"3. 要点","t":"单向流动、不可逆，不能循环利用；"},{"h":"4. 要点","t":"逐级递减，各营养级只约十分之一（十分之一定律）；"},{"h":"5. 原因","t":"上一营养级不可能被100％利用；各营养级同化率不是100％，部分成排泄物；各营养级维持生命活动要消耗部分能量并变成热量散失。"},{"h":"6. 要点","t":"食物网使食物链彼此交错，能量通过上行效应（低营养级控制高营养级）和下行效应（捕食者控制低营养级）实现调控。"},{"h":"7. 总述","t":"（二）生态金字塔：各营养级间数量关系图形化，塔基为第一营养级、塔顶为最后营养级。"},{"h":"8. 数量金字塔","t":"按各营养级生物个体数量比较，可能倒置（如一棵树与大量昆虫）。"},{"h":"9. 生物量金字塔","t":"按各营养级干重或湿重表示，海洋生态系统常倒置。"},{"h":"10. 能量金字塔","t":"按各营养级能量换算表示，反映能量传递与转化的有效程度，最能反映真实的营养关系、永不会倒置，最为可靠。"}],"pit":""},{"id":"857-b-36","title":"简述生态系统服务与生态系统健康","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 总述","t":"（一）生态系统服务：生态系统通过其生态过程，提供给人类维持生命和社会经济发展所需要的产品和服务，分为四类："},{"h":"2. 供给服务","t":"从生态系统获得的各种产品，如粮食、燃料、基因资源、淡水、装饰资源。"},{"h":"3. 调节服务","t":"从生态系统过程的调节作用中获益，如调节空气质量、调节气候、涵养水源、控制病虫害、授粉、调节自然灾害。"},{"h":"4. 文化服务","t":"通过精神满足、发展认知、消遣和体验美感获得的非物质惠益，如教育价值、美学价值、地方感、文化遗产、生态旅游。"},{"h":"5. 支持服务","t":"其他服务生产所必需的服务，如土壤形成、光合作用、初级生产、养分循环、水循环。"},{"h":"6. 总述","t":"生态服务价值的强弱取决于绿地（生态系统）的数量、组成结构、镶嵌格局、分布特征、与周边景观的联系及管理水平。"},{"h":"7. 总述","t":"（二）生态系统健康：指一个生态系统所具有的稳定性和可持续性，即在时间上具有维持其组织结构、自我调节能力和对胁迫的恢复能力。"},{"h":"8. 总述","t":"（三）二者关系：健康的生态系统是持续提供服务的前提；服务评估（价值核算）则为生态保护与绿色决策提供依据。"}],"pit":""},{"id":"857-b-37","title":"简述景观格局的斑块—廊道—基质模型","type":"简答","category":"了解","score":10,"source":"专题","full":[{"h":"1. 斑块（patch）","t":"景观中内部属性、结构、功能、外貌特征相对一致，与周围景观要素有明显区别的块状空间地域实体。按起源分为干扰斑块、残存斑块、环境资源斑块和引入斑块（种植斑块、聚居地）。"},{"h":"2. 廊道（corridor）","t":"斑块的特殊形式，指与两侧景观要素或基质有明显区别的带状地块。分为干扰廊道、残余廊道、环境资源廊道和种植廊道；具有通道、阻隔、过滤、源和汇的功能。"},{"h":"3. 基质（本底，matrix）","t":"景观中面积最大、连接度最高、对景观功能控制作用最强的景观要素。判定依据为相对面积、连通性和动态控制作用。"},{"h":"4. 模型含义","t":"斑块、廊道、基质是景观结构的三个基本成分，任何景观都可抽象为“基质上散布斑块、由廊道连接”的镶嵌体，是景观格局分析与规划的基本语言。"},{"h":"5. 应用","t":"城市景观中，绿地与建筑群可视为斑块，道路与河流为廊道，建成区为基质；通过增加大斑块、建设绿色廊道、提高连通性，可缓解生境破碎化、改善热岛与生物多样性保护效果。"},{"h":"6. 意义","t":"为景观结构定量分析（格局指数）、生态网络构建与城市绿地系统规划提供框架。"},{"h":"7. 总述","t":"第六部分　第 51—60 题　专题论述"}],"pit":""},{"id":"857-b-38","title":"论述种群增长的影响因素及调节机制","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"（一）影响因素：种群增长取决于出生率、死亡率、迁入率和迁出率，受两方面因素制约——非密度制约因素（气候、天气、灾害等，作用强度与种群密度无关）和密度制约因素（食物、空间、竞争、天敌、疾病，作用强度随密度升高而加强）。受资源限制时种群按逻辑斯谛模型 $dN/dt=rN(1-N/K)$ 增长，呈 S 形曲线。"},{"h":"2. 总述","t":"（二）调节机制（种群调节学说）："},{"h":"3. 气候学派","t":"以昆虫为对象，认为种群参数受天气条件强烈影响，种群大发生与天气变化明显相关；强调种群数量的变动，否认稳定性。"},{"h":"4. 生物学派","t":"主张捕食、寄生、竞争等生物过程对种群调节起决定作用。"},{"h":"5. 食物因素学派","t":"强调食物数量与质量的限制作用。"},{"h":"6. 自动调节（内源性）学说","t":"强调种群内部因素与个体质的差异，认为密度本身影响出生率、死亡率、生长、成熟和迁移，建立在种群内部负反馈基础上，是物种的适应性特征。包括："},{"h":"7. 总述","t":"a 行为调节（温·爱德华学说）：社群等级和领域性限制种群数量，把剩余个体排挤为“游荡的储存者”，其不能繁殖且死亡率高，此作用为密度制约；"},{"h":"8. 总述","t":"b 内分泌调节：密度过高时种群应激反应使内分泌失调，繁殖力下降、死亡率上升（主要适用于兽类，且有争议：笼养密度不自然、调查结果不一致、存在时滞）；"},{"h":"9. 总述","t":"c 遗传调节（Chitty）：种群存在遗传多型——低密度型繁殖力高、进攻性低，高密度型进攻性强、繁殖力低并易外迁；密度变化引起自然选择方向改变，从而自动调节密度。"},{"h":"10. 总述","t":"（三）小结：外源性因素（气候、食物、天敌）与内源性自动调节共同作用；调节过程中存在时滞，故种群常出现周期性波动。"}],"pit":""},{"id":"857-b-39","title":"论述群落演替的过程与顶极理论","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"（一）演替过程：演替是从植物定居开始到形成稳定群落的过程（演替系列），每个明显步骤为一个演替阶段；群落形成须经迁移、定居、竞争三个过程。"},{"h":"2. 旱生演替系列","t":"地衣阶段→苔藓阶段→草本植物阶段→灌木阶段→乔木（森林）阶段。"},{"h":"3. 水生演替系列","t":"自由漂浮植物阶段→沉水植物阶段→浮叶根生植物阶段→直立水生阶段→湿生草本阶段→木本植物阶段。"},{"h":"4. 机制","t":"早期群落改造生境（积累土壤、改善水分与养分），使环境更适合后期群落；后期群落竞争取代前期群落，如此“接二连三”替代，直至顶极群落。演替的实质是生物改造环境与环境选择生物的双向过程。"},{"h":"5. 总述","t":"（二）演替类型的判断依据：起始基质（原生／次生；旱生／水生系列）、方向（进展／逆行）、代谢特征（自养／异养）、主导因素（内因／外因，含火成、气候性、土壤性、动物性、人为演替）、持续时间（世纪／长期／快速）。"},{"h":"6. 总述","t":"（三）顶极理论："},{"h":"7. 单元顶极学说","t":"同一气候区内只能有一个顶极群落，其性质完全由当地气候决定，称气候顶极；只要给予足够时间，所有演替系列最终趋向同一顶极，区域将被单一群落覆盖。"},{"h":"8. 多元顶极学说","t":"除气候外，土壤、地形、火、动物等因素也可形成稳定群落，因此一个区域可有多个顶极，各自与其局部环境相适应。"},{"h":"9. 顶极格局学说","t":"环境梯度是连续变化的，顶极群落在空间上并非单一，而是沿环境梯度形成连续变化的镶嵌格局，种群按各自适应的梯度位置分布。"},{"h":"10. 总述","t":"（四）意义：顶极理论揭示群落发展的方向与稳定性机制；在园林中可据潜在植被确定目标群落类型（如宫胁法），缩短恢复时间。"}],"pit":""},{"id":"857-b-40","title":"论述生物多样性丧失的原因及保护对策","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"（一）丧失原因："},{"h":"2. 生境丧失和片段化","t":"自然生境减少、植被大面积消失，生境破碎化导致种群隔离，是首要原因。"},{"h":"3. 过度利用","t":"滥捕乱猎、倒卖走私野生动物，过度采伐与采集。"},{"h":"4. 环境污染","t":"大气、水、土壤污染对生物生存造成严重威胁。"},{"h":"5. 外来物种入侵","t":"引入种与乡土种竞争、捕食或改变生境，导致当地物种灭绝。"},{"h":"6. 农、林、牧品种的单一化","t":"遗传多样性下降，系统抗性减弱。"},{"h":"7. 要点","t":"大型水利工程等建设对生境的严重影响。"},{"h":"8. 人口压力与气候变化","t":"人口众多造成生态环境破坏，气候变暖使生态幅窄的物种、特别是关键种消失，导致生产力下降、多样性减少。"},{"h":"9. 总述","t":"（二）保护对策："},{"h":"10. 加强管理","t":"制定保护计划、规范和标准，使管理科学化、制度化、规范化；健全机构、完善法律体系、强化执法监督。"},{"h":"11. 建立监测系统与资源信息数据库","t":"全面调查现状，建立监测网络，参与国际与区域合作。"},{"h":"12. 开展保护与利用示范工程","t":"在绿地系统规划和建设中体现生物多样性保护要求。"},{"h":"13. 要点","t":"加强教育与培训，提高公众保护意识。"},{"h":"14. 具体空间措施","t":"保护城市景观中的小生境斑块（不被占用、保护周边环境、保证连通性）；保护城市周边自然景观要素；保护湿地斑块和河流廊道；提高生境斑块生态连通性，形成生态网络；建设或恢复大型绿地斑块、增加乔木林地面积；对濒危物种实施迁地保护与种质保存。"},{"h":"15. 环境综合治理与科技进步","t":"控制污染、控制人口、依靠科技支撑保护工作。"}],"pit":""},{"id":"857-b-41","title":"论述生态系统服务价值评估与健康管理","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"（一）生态系统服务：生态系统通过其生态过程提供给人类维持生命和社会经济发展所需的产品和服务，包括："},{"h":"2. 要点","t":"供给服务（食物、淡水、燃料、基因资源、装饰资源）；②调节服务（调节气候与空气质量、涵养水源、控制病虫、授粉、调节自然灾害）；③文化服务（教育、美学、精神与宗教、地方感、文化遗产、生态旅游）；④支持服务（土壤形成、光合作用、初级生产、养分循环、水循环）。"},{"h":"3. 总述","t":"（二）价值评估：把服务量化为货币或价值量，明确园林绿地的服务价值，为不同园林生态系统准确定位、建立完整的投入—产出分析体系，是实现园林资源可持续利用与生态环境建设的基础。"},{"h":"4. 总述","t":"评估意义：①推动国民经济核算体系走向环境与经济综合核算；②有助于制定合理的自然资源价格体系；③有助于做出绿色决策；④提高全民保护意识。"},{"h":"5. 总述","t":"（三）生态系统健康：指生态系统所具有的稳定性和可持续性，即在时间上具有维持其组织结构、自我调节能力和对胁迫的恢复能力。城市生态安全则是人与环境关系可持续程度的表征，测度生命支持系统耦合关系、代谢过程和服务功能的完好程度与风险大小。"},{"h":"6. 总述","t":"（四）健康管理："},{"h":"7. 诊断与监测","t":"以活力、组织结构、恢复力、服务功能维持等指标评价健康状态，建立长期监测网络。"},{"h":"8. 减少胁迫","t":"控制污染排放、限制干扰强度在生态平衡阈值以内，保护关键种与关键生境。"},{"h":"9. 增强自我调节能力","t":"保护生物多样性以提高后备力，维持负反馈机制的正常运行。"},{"h":"10. 修复与调控","t":"对退化生态系统实施生态修复与重建，调整结构与过程。"},{"h":"11. 制度管理","t":"以城市生态管理手段（土地、水资源、能源管理与生态规划）维持系统结构与功能的协调，把生态服务价值纳入决策与考核。"}],"pit":""},{"id":"857-b-42","title":"论述景观格局—过程—尺度的关系","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"（一）三者概念："},{"h":"2. 景观格局","t":"大小形状各异的景观要素在空间上的排列组合，包括组成单元的类型、数目及空间分布与配置。"},{"h":"3. 景观过程","t":"景观结构与生态学过程之间的相互作用，包括物质、能量、物种和信息的流动（景观生态流）以及干扰、演替等动态过程。"},{"h":"4. 尺度","t":"研究对象的空间维度，用空间分辨率和空间范围描述，反映对细节的把握能力和对整体的概括能力。"},{"h":"5. 总述","t":"（二）格局与过程的关系："},{"h":"6. 格局控制过程","t":"斑块的大小、形状、数量和连通性决定物质与物种能否迁移，例如大斑块维持内部种、廊道促进物种移动、破碎化阻断基因交流；景观异质性影响能流、物流的方向与速率。"},{"h":"7. 过程塑造格局","t":"干扰、演替、扩散等过程反过来改变斑块的边界、数量和配置，形成新的格局，二者互为因果。"},{"h":"8. 功能随格局而变","t":"同一类型斑块的功能不仅取决于属性，还受斑块大小、形状及其在整个景观中的空间分布与配置关系影响。"},{"h":"9. 总述","t":"（三）尺度的作用："},{"h":"10. 要点","t":"格局与过程的关联随尺度而变，小尺度上显著的格局在大尺度上可能消失，研究中须明确尺度并做尺度推绎。"},{"h":"11. 尺度效应","t":"随尺度增大，景观中出现不同类型的最小斑块，最小斑块面积逐渐增大，而景观多样性指数随尺度增大而减小。"},{"h":"12. 总述","t":"（四）实践意义：景观生态学的整体观、异质性和尺度性决定了规划必须在明确尺度上分析格局与过程的关系，通过调整格局（增加大斑块、建设廊道、提高连通性）来调控过程（物种流动、水与能量循环），实现景观功能的整体优化。"}],"pit":""},{"id":"857-b-43","title":"论述城市景观格局特征及生态网络构建","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"（一）城市景观格局特征："},{"h":"2. 景观要素多样性高","t":"山体水体、街区、道路、绿地、建筑物功能不同、性质各异，对总体格局影响不同，主导着城市景观异质性。"},{"h":"3. 人工化程度高、异质性强","t":"以建成区为主体，由街区、道路、公园、绿地、林地及城郊农田构成，以人类活动为主导。"},{"h":"4. 破碎化明显","t":"绿地与自然生境呈孤岛状小面积分布，斑块小而分散，边缘效应强、内部生境不足。"},{"h":"5. 分布格局与城市同心圈层结构相重叠","t":"由自然与人为因子共同作用形成。"},{"h":"6. 连通性差","t":"生境斑块相互隔离，廊道被道路与建筑切断，生态流受阻。"},{"h":"7. 总述","t":"（二）生态网络构建："},{"h":"8. 识别核心斑块（源地）","t":"保护并建设大型绿地斑块、增加乔木林地面积，满足内部种对生境面积的需要（岛屿生物地理学原理）。"},{"h":"9. 建设廊道","t":"以河流、绿带、道路绿廊构成绿色廊道，明确廊道宽度与数目，用以保护水系并满足物种空间运动需要；廊道兼具通道、阻隔、过滤和源汇功能。"},{"h":"10. 提高连通性","t":"把分散的小斑块与外界或大斑块连接，减少孤岛化，形成“斑块—廊道—基质”完整网络。"},{"h":"11. 集中与分散相结合的格局","t":"沿主要发展轴集中建设，同时保留大面积自然廊道与斑块；开发区或建成区保留小的、分散的自然廊道和斑块以维持景观异质性——这是适应于任何景观的最优模式。"},{"h":"12. 保护关键节点","t":"城市周边自然景观要素、湿地斑块与河流廊道优先保护，保证空间与生态连通关系。"},{"h":"13. 与城市绿地系统规划衔接","t":"把绿道、通风廊道、生物廊道与公园体系叠加，实现多功能复合。"}],"pit":""},{"id":"857-b-44","title":"论述生态修复的原则与生态安全格局","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"（一）生态修复（恢复与重建）的原则："},{"h":"2. 整体综合优化原则","t":"综合考虑生态、经济、社会因素与多学科知识，谋求系统功能整体最优。"},{"h":"3. 协调共生原则","t":"协调景观内部结构、生态过程与人与自然的关系，处理好生产与生态、资源开发与保护的关系。"},{"h":"4. 功能高效原则","t":"空间配置合理，资源利用最大化并高效。"},{"h":"5. 生态可持续性原则","t":"修复成果能自我维持、尽量自给自足，尊重演替规律。"},{"h":"6. 景观多样性保护原则","t":"立足当地自然与社会经济条件，形成功能互补的区域格局。"},{"h":"7. 谨慎性原则","t":"减少对自然生态系统的干扰，谨慎使用外来物种（以乡土种和潜在植被为目标群落）。"},{"h":"8. 以演替理论为指导","t":"如宫胁法通过改造土壤、乡土种育苗、模拟演替序列，在较短时间内建成稳定顶极群落。"},{"h":"9. 总述","t":"（二）生态安全格局："},{"h":"10. 要点","t":"城市生态安全是人与环境关系可持续程度的表征，测度人与其生产生活环境及生命支持系统之间耦合关系、代谢过程和服务功能的完好程度与风险大小。"},{"h":"11. 需要重点关注的脆弱区域——生态交错区（生态脆弱区）","t":"抗干扰能力弱、对气候变化敏感、时空波动性强、边缘效应显著、环境异质性高，如西北干旱沙漠化区、西南山地石漠化区、青藏高寒区。"},{"h":"12. 构建途径","t":"识别关键生态要素与廊道（水源涵养区、生物多样性热点、通风廊道、行洪通道），划定生态保护红线与绿线并严格管控，形成“源地—廊道—缓冲区”的空间安全骨架，限制在敏感区进行高强度开发。"},{"h":"13. 与绿地系统结合","t":"以生态网络提高连通性和恢复力，以生态评价与监测预警提供动态调控依据。"}],"pit":""},{"id":"857-b-45","title":"论述全球气候变化对园林植物的影响及应对","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"（一）气候变化的表现与原因：人类活动大量排放CO₂，海洋吸收的迟滞性和生物圈控制途径减弱，使大气CO₂浓度不断升高，近地大气层保持较高温度（温室效应），全球变暖并伴随极端天气增多。"},{"h":"2. 总述","t":"（二）对园林植物的影响："},{"h":"3. 物候改变","t":"春季物候提前、生长季延长，秋季物候推迟，使植物的温度与光周期信号错位，增加晚霜危害风险。"},{"h":"4. 生理与生长","t":"CO₂浓度升高可提高光合速率与水分利用效率；但升温加剧蒸腾与土壤蒸发，若干旱同步加剧，植物受水分胁迫，生长量与成活率下降。"},{"h":"5. 分布格局与生物多样性改变","t":"物种向高纬、高海拔迁移，生态幅窄的物种（尤其关键种）可能消失，导致森林生态系统生产力下降、物种多样性减少。"},{"h":"6. 群落组成与结构改变","t":"气候变暖使养分循环加快、动植物群落组成改变，群落结构与季相随之变化。"},{"h":"7. 病虫害与外来种风险加大","t":"冬季低温限制减弱，害虫越冬存活率提高、发生代数增加；外来入侵种更易定殖。"},{"h":"8. 极端天气危害加剧","t":"高温热浪引起皮烧与根茎灼伤；干旱、暴雨、冻害交替造成生理干旱与冻拔、冻裂等伤害。"},{"h":"9. 总述","t":"（三）应对措施："},{"h":"10. 要点","t":"提高认识，强化政策与制度措施，限制温室气体排放，增加绿地碳汇。"},{"h":"11. 科学选种","t":"以乡土种和抗逆性强、生态幅宽的树种为主，提高植物多样性，避免单一化以增强系统适应性。"},{"h":"12. 优化群落结构","t":"营建复层混交的近自然群落，提高自我调节与抗干扰能力。"},{"h":"13. 改善生境与养护","t":"增加土壤有机质与保水能力、完善灌溉与排水，推广雨水利用与节水灌溉，缓解高温干旱胁迫。"},{"h":"14. 构建生态网络","t":"通过廊道与连通性为物种迁移留出空间，保护气候避难所。"},{"h":"15. 加强监测预警","t":"建立物候与病虫害监测，动态调整树种规划与养护措施。"}],"pit":""},{"id":"857-b-46","title":"论述生态系统稳定性与反馈调节","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"（一）生态平衡与稳定性：生态平衡是在一定时间和相对稳定条件下，生态系统各部分的结构与功能处于相互适应与协调的动态平衡；判断依据包括生物与环境协调性、物质与能量输入输出的平衡、内部结构的稳定性、负熵增加。"},{"h":"2. 总述","t":"（二）反馈调节机制：反馈指系统的输出变成了决定系统未来功能的输入。"},{"h":"3. 负反馈","t":"通过自身功能减缓系统压力以维持系统稳定，是系统稳定的基础；种群调节中的密度制约（如自疏）即为负反馈的体现。"},{"h":"4. 正反馈","t":"使系统偏离加剧，不能维持稳定，但为有机体生长和存活所必需（个体长大、种群数量上升）。"},{"h":"5. 生态系统如弹簧","t":"能忍受一定外来压力，压力解除后可恢复原状，这正是反馈调节功能的作用。"},{"h":"6. 总述","t":"（三）抵抗力与恢复力："},{"h":"7. 抵抗力","t":"生态系统抵抗外界干扰并维持结构和功能原状的能力；"},{"h":"8. 恢复力","t":"遭受破坏后恢复到原状的能力，由生命成分的基本属性决定——生活世代短、结构简单的系统恢复快（草原破坏后恢复快于森林）；"},{"h":"9. 要点","t":"二者常呈权衡关系，复杂系统抵抗力强而恢复力弱。"},{"h":"10. 总述","t":"（四）生态平衡阈值与失衡：不使生态平衡丧失调节能力或超过恢复力的外来干扰强度称生态平衡阈值，其大小与生态系统类型、干扰性质、方式和持续时间有关；当外界压力超过自我调节能力，出现结构破坏、功能受阻、反馈自控能力下降，即为生态失衡（生态危机）。"},{"h":"11. 总述","t":"（五）意义：城市生态系统结构简单、生物多样性低、自我调节能力弱，必须控制在阈值内并依靠人工调控与生物多样性（后备力）提高稳定性。"}],"pit":""},{"id":"857-b-47","title":"论述景观生态规划与绿色基础设施","type":"论述","category":"了解","score":15,"source":"专题","full":[{"h":"1. 总述","t":"（一）概念："},{"h":"2. 景观生态规划","t":"应用景观生态学原理与方法，以谋求区域和景观生态系统功能的整体优化和可持续发展为目标，以景观和区域尺度上的生态保护、建设、恢复、调整和管理为重点，在景观生态分析和综合评价基础上，提出景观建设调整与利用的方案、对策和措施。"},{"h":"3. 生态规划","t":"以生态学原理为依据，以实现人与环境和谐共生为根本任务，以最大限度适应、保护和提高自然系统自我更新与再生能力为核心，通过优化土地利用结构和物质能量输入输出模式，建立源—汇循环通道的新型规划设计范式。"},{"h":"4. 绿色基础设施","t":"由绿地、水体、湿地、绿道等构成的相互连通的生态网络，作为城市的“自然生命支持系统”，与灰色基础设施相对应，提供雨洪调蓄、降温、净化、生物多样性保护等服务。"},{"h":"5. 总述","t":"（二）规划原则：整体综合优化；协调共生；功能高效；生态可持续性；景观多样性保护；谨慎性（减少对自然系统干扰、慎用外来物种）。"},{"h":"6. 总述","t":"（三）主要内容：生态功能分区与产业布局；土地利用规模、结构与空间布局的调整；人口规划；环境规划（污染综合防治与综合整治）；综合生态规划（强调整体性与综合性）。"},{"h":"7. 总述","t":"（四）核心格局模式——集中与分散相结合：沿主要发展轴集中建设，保留大面积自然廊道与斑块以保护水系并满足物种运动需要；开发区或建成区保留小的分散自然廊道与斑块以维持异质性；此构型被认为是适应于任何景观的最优模式。"},{"h":"8. 总述","t":"（五）技术途径：以3S技术与景观格局指数开展评价；以生态网络（源地—廊道—节点）构建绿色基础设施；以绿线、生态红线管控落地；以生态设计把生态保护性、恢复性、功能性、展示性设计结合到具体场地。"},{"h":"9. 总述","t":"（六）意义：把绿地由孤立斑块提升为连通的绿色基础设施网络，实现生态、社会与经济效益统一，是城市可持续发展的空间保障。"}],"pit":""}]}};
